local E = ns.DB.entries
E["npc:mux-manascrambler"] = {t="npc",n="Mux Manascrambler",z="tanaris",s="Mux Manascrambler is an eccentric goblin engineer dwelling in the desert outpost of Gadgetzan. Unlike many of his peers focused strictly on explosives or mining equipment, Mux harbors a peculiar fascination with the supernatural and occult energies.",h="Mux Manascrambler is an eccentric goblin engineer dwelling in the desert outpost of Gadgetzan.",sec={{t="A Tinkerer of the Unseen",b="Tucked away inside a building in central Gadgetzan, behind Driz Plunkbow and his clanking Butcherbots, sits Mux Manascrambler. While the Steamwheedle Cartel trades heavily in oil, guns, and salvage, Mux focuses his ingenuity on more esoteric pursuits: the realm of spirits and supernatural anomalies. He uses his technical acumen to design bizarre devices capable of detecting, distilling, and interacting with spectral remnants, bridging crude goblin craftsmanship with the invisible worlds of the dead.",sp=0}},faq={{q="Where can I find Mux Manascrambler?",a="Mux makes his home in Gadgetzan in northern Tanaris. You can find him tucked inside a building near the center of the desert trading hub, positioned just behind Driz Plunkbow and the meat-carving Butcherbots.",al={"mux location","where is mux","mux manascrambler map"}},{q="What kind of work does Mux do?",a="Mux is an engineer obsessed with spectral and unseen forces. Rather than standard demolitions or transport, he builds specialized contraptions capable of revealing spirits, distilling ectoplasm, and harnessing arcane supernatural power.",al={"mux job","what does mux sell","mux research"}},{q="Does Mux belong to a faction?",a="Mux belongs to the Steamwheedle Cartel operating out of Gadgetzan. As an independent goblin operative, he maintains strict commercial neutrality and is willing to aid adventurers of either the Horde or the Alliance.",al={"is mux horde","is mux neutral","mux alliance"}}},ang={["profession:Engineering"]="Mux is an oddity among goblin tinkers, applying mechanical gears and power cells to capture and distill invisible supernatural forces rather than merely blowing things apart."},kw={"ectoplasm","gadgetzan","ghost","goblin engineer","manascrambler","mux","tanaris"},rel={"subzone:gadgetzan","zone:tanaris","topic:goblin"},src={"Mux Manascrambler"}}
E["npc:narain-soothfancy"] = {t="npc",n="Narain Soothfancy",z="tanaris",s="Narain Soothfancy is an eccentric gnome dwelling in a secluded beach hut just north of Steamwheedle Port in Tanaris. While he loudly advertises himself as a master soothsayer capable of divining the future, those who know him consider his psychic talents a complete farce compared to his genuine engineering genius.",h="Narain Soothfancy is an eccentric gnome dwelling in a secluded beach hut just north of Steamwheedle Port in...",sec={{t="Psychic Visions and Practical Gearing",b="Perched on the eastern coast of Tanaris just north of the goblin docks, Narain Soothfancy lives as a retired engineer turned self-proclaimed master fortune teller. He routinely greets visitors by pressing unopened envelopes against his forehead or making wildly inaccurate guesses about their business, such as wondering if they have arrived seeking the legendary Ashbringer. Despite his theatrical charade, Narain possesses deep technical knowledge. Even ancient beings like the blue dragon Azuregos note that while Narain is a terrible psychic, his engineering aptitude is undeniably brilliant. A handbook titled 'Soothsaying for Dummies' rests nearby.",sp=0},{t="A Shoreline Crash",b="Before settling by Steamwheedle Port, Narain suffered a catastrophic flying machine crash far to the south along Land's End Beach. He survived the wreck thanks to an unexpected rescue, though his eccentric personality and strange obsessions have kept him isolated on the desert shores, tinkering with arcane-adjacent technology and peddling dubious prophecies to anyone who passes by.",sp=0}},faq={{q="Who is Narain Soothfancy?",a="Narain Soothfancy is a retired gnome engineer residing in Tanaris north of Steamwheedle Port. He advertises himself as a master soothsayer, though his divinations are famously inaccurate.",al={"narain soothfancy lore","who is narain","tanaris psychic gnome"}},{q="Is Narain actually a psychic?",a="No. Powerful acquaintances like the dragon Azuregos openly describe him as an awful psychic. His true talent lies in masterwork engineering and tinkering, regardless of his theatrical attempts at mind-reading.",al={"can narain see the future","is narain psychic","soothfancy fortune teller"}},{q="What is the book 'Soothsaying for Dummies' beside him?",a="It is a handbook kept in Narain's hut, associated with specialized trades. Narain points travelers seeking such knowledge toward the book.",al={"soothsaying for dummies","narain tradeskill book"}},{q="How does Narain know Azuregos?",a="Narain is an old associate of the blue dragon Azuregos, who wanders Azshara. Despite Narain's bizarre pretensions, the dragon respects his unmatched engineering and crafting capabilities.",al={"narain and azuregos","blue dragon narain"}}},ang={["profession:Engineering"]="Engineers will find Narain's wild inventions fascinating, even if he prefers to pretend his mechanical triumphs are actually mystical visions.",["race:Gnome"]="Narain exemplifies the eccentric extreme of gnomish ingenuity, pairing brilliant technological problem-solving with bizarre, obsessive hobbies."},kw={"azuregos","engineer","narain","soothfancy","soothsayer","steamwheedle port","tanaris"},rel={"zone:tanaris","subzone:steamwheedle-port","subzone:land-s-end-beach","npc:azuregos","topic:gnome"},src={"Narain Soothfancy"}}
E["npc:senior-surveyor-fizzledowser"] = {t="npc",n="Senior Surveyor Fizzledowser",z="tanaris",s="Senior Surveyor Fizzledowser is a goblin researcher working from Gadgetzan in Tanaris. He investigates disruptions around the local water supply and sends adventurers to look into the disappearance of Scrimshank.",h="Senior Surveyor Fizzledowser is a goblin researcher working from Gadgetzan in Tanaris.",sec={{t="A Search for Water Gone Wrong",b="Operating out of Gadgetzan, Senior Surveyor Fizzledowser is primarily occupied with solving the desert town's chronic resource problem. With local wells and water holes constantly seized by hostile Wastewander bandits, the Gadgetzan Water Company must search further afield for untapped reservoirs. To this end, Fizzledowser dispatches scouts armed with dowsing widgets across the dunes, such as toward Sandsorrow Watch. However, instead of finding clean springs, his probes consistently tap into subterranean insect hives, trading one logistical crisis for an impending ecological disaster.",sp=1},{t="Uncovering the Silithid",b="When his surveyor crews began suffering devastating ambushes from armored, burrowing insects, Fizzledowser partnered with Alchemist Pestlezugg to examine the specimens. Further tragedies—including the loss of Junior Surveyor Scrimshank inside the Gaping Chasm—proved that these were not ordinary desert pests, but coordinated vanguard forces known as the silithid. Alarmed by findings pointing toward a threat capable of overwhelming southern Kalimdor, Fizzledowser looks past goblin neutrality and sends word to scholars of both the Horde and the Alliance.",sp=1}},faq={{q="Who is Senior Surveyor Fizzledowser?",a="He is an engineer and field supervisor for the Gadgetzan Water Company. His duty is to scout viable water wells across the desert of Tanaris to keep Gadgetzan supplied.",al={"who is fizzledowser","fizzledowser tanaris","gadgetzan surveyor"}},{q="What is the Gadgetzan Water Company?",a="It is a commercial enterprise operating out of Gadgetzan responsible for securing, processing, and distributing water in the arid desert of Tanaris, where moisture is the most valuable commodity.",al={"gadgetzan water company","who does fizzledowser work for"}},{q="What happened to Junior Surveyor Scrimshank?",a="Scrimshank is a missing prospector whose disappearance Fizzledowser asks adventurers to investigate.",al={"where is scrimshank","scrimshank redemption","what happened to scrimshank"},sp=1},{q="Why is Fizzledowser concerned about the desert insects?",a="His investigation begins with troubling insect activity and disruptions to Gadgetzan's water supply, prompting him to gather evidence for further study.",al={"why investigate bugs","noxious lair investigation","silithid threat tanaris"}}},ang={["profession:Engineering"]="Fizzledowser relies on custom goblin-engineered dowsing widgets to pinpoint hidden water sources beneath the shifting sands."},kw={"dowsing widget","fizzledowser","gadgetzan","gaping chasm","pestlezugg","scrimshank","silithid","tanaris","water company"},rel={"subzone:gadgetzan","zone:tanaris","subzone:sandsorrow-watch","subzone:gaping-chasm","subzone:noxious-lair","topic:goblin","topic:alliance","topic:horde"},src={"Senior Surveyor Fizzledowser"}}
E["npc:yeh-kinya"] = {t="npc",n="Yeh'kinya",z="tanaris",s="Yeh'kinya is a jungle troll scholar residing at Steamwheedle Port on the desert coast of Tanaris. Claiming to seek ancient lore and artifacts to understand dark powers, he dispatches willing adventurers across Azeroth on missions to gather lost troll relics.",h="Yeh'kinya is a jungle troll scholar residing at Steamwheedle Port on the desert coast of Tanaris.",sec={{t="The Scholar at Steamwheedle Port",b="Lounging among the goblins and dockworkers of Steamwheedle Port, Yeh'kinya presents himself as a quiet student of history and spirits. He recruits travelers to track down obscure magical items across Kalimdor and the Eastern Kingdoms, from ancient eggs in the Hinterlands to stone prophecy tablets buried in the ruins of Zul'Farrak. While he claims these errands serve peaceful academic inquiry into ancient troll history, his specific focus on the blood god Hakkar draws suspicion from watchful onlookers.",sp=0},{t="The Serpent's Deceit",b="Beneath his scholarly guise, Yeh'kinya is a fanatical worshipper of Hakkar the Soulflayer. Every artifact and soul essence he gathers is carefully manipulated to prepare for the dread Blood God's physical rebirth into Azeroth. Once his plot is pieced together and exposed by Prospector Ironboot, Yeh'kinya sheds all pretense of friendship. Rather than answering for his treason, he transforms into a green wind serpent and flees across the open sea toward the south seas, leaving duped heroes to seek aid from the Zandalari on Yojamba Isle.",sp=2}},faq={{q="Who is Yeh'kinya?",a="Yeh'kinya is a jungle troll found standing near the water at Steamwheedle Port in Tanaris. He presents himself as a scholar seeking historical relics and spirits, with a particular interest in the troll god Hakkar.",al={"yeh'kinya lore","who is yehkinya","yehkinya npc"},sp=2},{q="Why does Yeh'kinya want the Prophecy of Mosh'aru and the Ancient Egg?",a="Yeh'kinya says he needs these artifacts for his study of ancient troll history and spirits. The Mosh'aru tablets lie in the ruins of Zul'Farrak and the Ancient Egg in the Hinterlands, and both tie into his interest in Hakkar.",al={"why ancient egg","prophecy of mosharu troll","yehkinya purpose"},sp=2}},ang={["race:Troll"]="Darkspear trolls recognize the mortal peril of Hakkar's resurgence.",["class:Priest"]="Priests sensitive to spiritual essence may find Yeh'kinya's casual collection of trapped screecher spirits deeply troubling."},kw={"hakkar","ironboot","mosh'aru","soulflayer","steamwheedle port","tanaris","wind serpent","yeh'kinya","yehkinya"},rel={"subzone:steamwheedle-port","zone:tanaris","subzone:yojamba-isle","subzone:zul-gurub","topic:troll"},src={"Yeh'kinya"}}
E["quest:10"] = {t="quest",n="The Scrimshank Redemption",z="tanaris",s="In Gadgetzan, Senior Surveyor Fizzledowser is troubled: Junior Surveyor Scrimshank, a top assistant sent into the Gaping Chasm, an area of desert southeast of town, has gone missing. You are asked to find out what became of Scrimshank, or at the least to find the surveying equipment.",h="In Gadgetzan, Senior Surveyor Fizzledowser is troubled: Junior Surveyor Scrimshank, a top assistant sent into...",sec={{t="A Surveyor Gone Missing",b="Senior Surveyor Fizzledowser is troubled. Junior Surveyor Scrimshank went into the Gaping Chasm and has not been seen since, and the last report from there spoke of more of those weird bugs. Fizzledowser wonders whether the bugs now hold two big regions of the desert at once. You are asked to go in and search for Scrimshank, or failing that, for the surveying equipment, which Fizzledowser fears may be all that is left.",sp=0},{t="Fizzledowser's Verdict",b="Scrimshank, a good goblin by Fizzledowser's account, did not survive. Fizzledowser hopes the loss counts for something, given what the surveying equipment managed to record. The bugs show a worrying cunning, and the research so far points to a third party controlling them, which bodes ill for Gadgetzan and the whole desert.",sp=1}},faq={{q="Who is Senior Surveyor Fizzledowser?",a="Fizzledowser is the Senior Surveyor in Gadgetzan who has been looking into the weird bugs of the desert, and Scrimshank's superior.",al={"fizzledowser","who gives this quest","surveyor fizzledowser"}},{q="Who is Junior Surveyor Scrimshank?",a="Scrimshank was Fizzledowser's top assistant, sent into the desert southeast of Gadgetzan before going missing.",al={"scrimshank","who is scrimshank","junior surveyor"}},{q="Where is the Gaping Chasm located?",a="It is the area of desert southeast of Gadgetzan that the surveyors call the Gaping Chasm.",al={"gaping chasm location","where is gaping chasm","chasm location"}},{q="What came before this step?",a="It follows the Noxious Lair Investigation.",al={"previous quest","prerequisite","what quest comes first"}}},kw={"fizzledowser","gadgetzan","gaping chasm","scrimshank","surveying","tanaris"},rel={"npc:senior-surveyor-fizzledowser","subzone:gaping-chasm","subzone:gadgetzan","quest:82","quest:110","zone:tanaris","topic:goblin"},m={start="Senior Surveyor Fizzledowser",["end"]="Senior Surveyor Fizzledowser",level="48",id=10},src={"The Scrimshank Redemption"}}
E["quest:110"] = {t="quest",n="Insect Part Analysis",z="tanaris",s="With Scrimshank lost, Senior Surveyor Fizzledowser sets about going over the surveying gear and putting Scrimshank's personal effects in order, and asks you to call on Alchemist Pestlezugg in Gadgetzan about the insect parts.",h="With Scrimshank lost, Senior Surveyor Fizzledowser sets about going over the surveying gear and putting...",sec={{t="A Check-In at Gadgetzan",b="Fizzledowser means to spend some time with Scrimshank's surveying gear and personal effects, and has a sneaking feeling that these bugs will claim more losses. You are asked to call on Alchemist Pestlezugg in Gadgetzan and learn whether the insect parts the surveyors sent have been processed yet. If they are ready, Fizzledowser wants them brought back.",sp=0},{t="What Pestlezugg Found",b="Pestlezugg has the results, and they are unsettling. The first suspicion, that an outside force is controlling the bugs, is believed to be correct. That means a very powerful unknown force, and a malignant one. The bugs have been changed into pure ravagers, and Pestlezugg has never seen anything quite like it.",sp=1}},faq={{q="Who sends you to consult Alchemist Pestlezugg?",a="Senior Surveyor Fizzledowser, who is going over Scrimshank's gear and putting Scrimshank's belongings in order.",al={"quest giver","who starts insect part analysis","fizzledowser location"}},{q="Where is Alchemist Pestlezugg located?",a="In Gadgetzan, where you are to check in about the insect parts.",al={"where is pestlezugg","pestlezugg location","pestlezugg town"}},{q="What came directly before this step?",a="It follows The Scrimshank Redemption.",al={"prerequisite quest","what quest comes first","previous step"}},{q="What are you sent to find out?",a="Whether Pestlezugg has finished going through the insect parts the surveyors sent. If they are ready, they are to be brought to Fizzledowser.",al={"what does pestlezugg have"}}},kw={"fizzledowser","gadgetzan","insect part analysis","pestlezugg","scrimshank","tanaris"},rel={"quest:10","quest:113","subzone:gadgetzan","zone:tanaris"},m={start="Senior Surveyor Fizzledowser",["end"]="Alchemist Pestlezugg",level="48",id=110},src={"Insect Part Analysis"}}
E["quest:113"] = {t="quest",n="Insect Part Analysis",z="tanaris",s="Alchemist Pestlezugg has finished the report on the insect parts and says Senior Surveyor Fizzledowser must see it at once. The threat faces Tanaris and Gadgetzan and, if left unchecked, all of southern Kalimdor.",h="Alchemist Pestlezugg has finished the report on the insect parts and says Senior Surveyor Fizzledowser must...",sec={{t="A Grave Warning",b="Pestlezugg insists that Senior Surveyor Fizzledowser must see the report right away, and that everyone who can read must see it too. The threat is grave and serious, for Tanaris and Gadgetzan and, if left unchecked, for all of southern Kalimdor. It may even reach the whole of Azeroth, for it has given no sign that it will subside. You are asked to carry the report to Fizzledowser in Gadgetzan and have a duplicate made, to share freely with your allegiance. Everyone must know of this threat.",sp=0},{t="A Matter of Coin",b="Fizzledowser thanks you for the delivery and for your hard work for the Gadgetzan Water Company. Handing the company's valuable information out to everyone is not something Fizzledowser likes, since people would normally pay well for it. But Fizzledowser has long known Pestlezugg, and if Pestlezugg recommends letting everyone know, so be it. A copy is made for you.",sp=1}},faq={{q="Who sends the report and who receives it?",a="Alchemist Pestlezugg gives you the report and sends you with it to Senior Surveyor Fizzledowser in Gadgetzan.",al={"who gives insect part analysis","who do i turn insect part analysis in to","where to deliver the report"}},{q="Why is Alchemist Pestlezugg so alarmed?",a="Pestlezugg calls it a grave and serious threat to Tanaris and Gadgetzan, and if left unchecked, to all of southern Kalimdor and possibly the whole of Azeroth, with no sign of subsiding.",al={"pestlezugg warning","what is in the insect report","why is the insect threat serious"}},{q="Why do you need a copy of the report?",a="Pestlezugg wants everyone to know about the threat, so Fizzledowser is to make a duplicate that you can pass around freely among your own people.",al={"why copy the report","fizzledowser report copy","why share the report"}},{q="What comes directly before this delivery?",a="It follows an earlier step also named Insect Part Analysis.",al={"previous quest","what quest comes before this"}}},kw={"fizzledowser","gadgetzan","gadgetzan water company","insect analysis","pestlezugg","report","tanaris"},rel={"npc:senior-surveyor-fizzledowser","subzone:gadgetzan","zone:tanaris","quest:110","quest:32","quest:162"},m={start="Alchemist Pestlezugg",["end"]="Senior Surveyor Fizzledowser",level="48",id=113},src={"Insect Part Analysis (2)"}}
E["quest:1560"] = {t="quest",n="Tooga's Quest",z="tanaris",s="Tooga, a lost turtle, was sent out to fetch dinner by his wife Torta and took a wrong turn somewhere. Tooga asks you to lead him back to Torta, who waits just south of Steamwheedle Port.",h="Tooga, a lost turtle, was sent out to fetch dinner by his wife Torta and took a wrong turn somewhere.",sec={{t="A Lost Wanderer",b="Tooga wanders near a crashed goblin zeppelin close to Thistleshrub Valley. Torta sent Tooga out to fetch dinner, and a wrong turn somewhere has left the turtle hopelessly lost. Tooga asks you to lead the way back.",sp=0},{t="Across the Zone",b="Torta waits just south of Steamwheedle Port, in the opposite corner of Tanaris, so the walk takes you across almost the whole width of the zone.",sp=0},{t="A Wife's Welcome",b="Torta is not surprised that Tooga could not find the way home alone, and tells Tooga to get into the ocean and bring back some food.",sp=1}},faq={{q="Who is Tooga?",a="A lost turtle in Tanaris who needs help finding the way back to his wife.",al={"who is tooga","tooga turtle","who is the turtle in tanaris"}},{q="Who is Torta?",a="Tooga's wife, who waits just south of Steamwheedle Port.",al={"who is torta","where is torta","torta location"}},{q="Why is Tooga lost in the desert?",a="Torta sent Tooga to fetch dinner, and a wrong turn left him lost.",al={"why is tooga lost","what happened to tooga","tooga backstory"}},{q="Where is Tooga originally found?",a="Near a crashed goblin zeppelin by Thistleshrub Valley in Tanaris.",al={"tooga start location","where does toogas quest start","find tooga"}}},kw={"steamwheedle port","tanaris","thistleshrub valley","tooga","torta","turtle"},rel={"zone:tanaris","subzone:thistleshrub-valley","subzone:steamwheedle-port","topic:goblin"},m={start="Tooga",["end"]="Torta",level="50",id=1560},src={"Tooga's Quest"}}
E["quest:162"] = {t="quest",n="Rise of the Silithid",z="tanaris",s="Senior Surveyor Fizzledowser urges you to carry the report on the insect threat to Gracina Spiritmight, a night elf scholar and historian in Darnassus.",h="Senior Surveyor Fizzledowser urges you to carry the report on the insect threat to Gracina Spiritmight, a...",sec={{t="A Scholar in Darnassus",b="Fizzledowser wants the report to reach someone with working knowledge of such matters. Gracina Spiritmight is a night elf scholar who has spent a lot of time studying the life forms unique to Azeroth's ecology, and she is a historian too. Fizzledowser hopes she can help work out what the danger really is and, above all, how it might be halted. By Fizzledowser's last word, she was living in the Temple of the Moon in Darnassus.",sp=0},{t="Gracina's Answer",b="Gracina says the night elves know of the terror described in the report, and thinks Fizzledowser chose well in sending it, and you. These creatures will devour the Tanaris desert rapidly and number among the greatest menaces anyone will face. They are the silithid, the tools of one of the gravest threats to both Horde and Alliance. Gracina laments that no one was wise enough to see it sooner.",sp=1}},faq={{q="Who is Gracina Spiritmight?",a="A night elf scholar and historian who has spent a great deal of time studying life forms unique to the ecology of Azeroth.",al={"gracina spiritmight lore","who is gracina","temple of the moon scholar"}},{q="Who sends you to Gracina?",a="Senior Surveyor Fizzledowser gives you the Insect Analysis Report and asks you to take it to her.",al={"where did the report come from","insect analysis report origin"}},{q="Where can Gracina Spiritmight be found?",a="In the Temple of the Moon in Darnassus, by Fizzledowser's last word.",al={"where is gracina","gracina spiritmight location","find gracina spiritmight"}},{q="What came before this journey to Darnassus?",a="It follows Insect Part Analysis.",al={"previous quest","what led to rise of the silithid","prior quest to gracina"}}},kw={"darnassus","fizzledowser","gracina","insect analysis","silithid","spiritmight","tanaris","temple of the moon"},rel={"npc:senior-surveyor-fizzledowser","zone:tanaris","zone:darnassus","subzone:temple-of-the-moon","topic:night-elf","topic:alliance","topic:horde","quest:113"},m={start="Senior Surveyor Fizzledowser",["end"]="Gracina Spiritmight",level="49",faction="Alliance",id=162},src={"Rise of the Silithid (Alliance)"}}
E["quest:1690"] = {t="quest",n="Wastewander Justice",z="tanaris",s="Chief Engineer Bilgewhizzle of the Gadgetzan Water Company says the Wastewander nomads now hold nearly every water well in the Tanaris desert. You are sent east of Gadgetzan to bring justice to the Wastewander Bandits and Thieves.",h="Chief Engineer Bilgewhizzle of the Gadgetzan Water Company says the Wastewander nomads now hold nearly every...",sec={{t="Justice for the Wells",b="Out in the Tanaris desert, the Wastewander nomads now hold nearly every water well, and Gadgetzan's supply will soon run dry without access to them. Chief Engineer Bilgewhizzle, who has a taste for goblin-style justice, wants ten Wastewander Bandits and Thieves brought down east of town, and then a report back at once.",sp=0},{t="Far From Done",b="Bilgewhizzle is pleased with the speed of the work. The nomads are thinned enough that the company can start thinking about winning back its water wells, though it is far from done with the foul nomads and has more in mind.",sp=1}},faq={{q="Who is Chief Engineer Bilgewhizzle?",a="A Chief Engineer of the Gadgetzan Water Company, in Gadgetzan.",al={"bilgewhizzle","who gives wastewander justice","gadgetzan water company engineer"}},{q="Why is the Gadgetzan Water Company going after the Wastewanders?",a="The Wastewander nomads hold nearly every water well in the desert, and without access to them Gadgetzan's water supply will dry up.",al={"why kill wastewander bandits","wastewander justice reason","why attack nomads tanaris"}},{q="Where are the Wastewander Bandits and Thieves located?",a="Out to the east of Gadgetzan, in the desert.",al={"where to find wastewander bandits","wastewander bandit location","thieves tanaris location"}}},kw={"bandit","bilgewhizzle","gadgetzan","tanaris","thief","wastewander","water company","wells"},rel={"quest:1691","subzone:gadgetzan","zone:tanaris","topic:goblin"},m={start="Chief Engineer Bilgewhizzle",["end"]="Chief Engineer Bilgewhizzle",level="43",id=1690},src={"Wastewander Justice"}}
E["quest:1691"] = {t="quest",n="More Wastewander Justice",z="tanaris",s="Chief Engineer Bilgewhizzle in Gadgetzan now turns to the tougher Wastewander nomads: their rogues, assassins and shadow mages, to be found east and southeast of town. The fewer nomads left, the easier it will be to take back the water wells.",h="Chief Engineer Bilgewhizzle in Gadgetzan now turns to the tougher Wastewander nomads: their rogues, assassins...",sec={{t="The Stronger Ranks",b="You have done a good job so far, in Bilgewhizzle's view, but taking back the wells is best done against as few nomads as possible. Now the targets are the nomads' rogues, assassins and shadow mages, east and southeast of Gadgetzan. Bilgewhizzle admits they are a nasty lot, but says the wells are rightfully the company's.",sp=0},{t="Taking the Fight to Them",b="The nomad population is now thin enough that the company can take the fight to them. Bilgewhizzle suggests speaking to Spigot Operator Luglunket in town, who gives a bounty on any Wastewander water pouches that came your way while dealing with the nomads.",sp=1}},faq={{q="Who asks for this?",a="Chief Engineer Bilgewhizzle of the Gadgetzan Water Company, in Gadgetzan.",al={"who gives more wastewander justice","quest giver"}},{q="Why does the Gadgetzan Water Company want these nomads removed?",a="The company means to take back the water wells, and that is easier against as few nomads as possible.",al={"why kill wastewanders","bilgewhizzle motive"}},{q="Where can the targeted nomads be found?",a="Lying east and southeast of Gadgetzan, where the nomads are found.",al={"where are wastewander rogues","where to find shadow mages"}},{q="What comes before this step?",a="It follows Wastewander Justice.",al={"prerequisite","prior quest"}}},kw={"assassins","bilgewhizzle","gadgetzan","shadow mages","tanaris","wastewander","water company"},rel={"quest:1690","subzone:gadgetzan","zone:tanaris"},m={start="Chief Engineer Bilgewhizzle",["end"]="Chief Engineer Bilgewhizzle",level="44",id=1691},src={"More Wastewander Justice"}}
E["quest:1707"] = {t="quest",n="Water Pouch Bounty",z="tanaris",s="Spigot Operator Luglunket in Gadgetzan wants the Wastewander water pouches the nomads stole, wherever you find them out in the desert. The Gadgetzan Water Company offers an official care package in return for each five.",h="Spigot Operator Luglunket in Gadgetzan wants the Wastewander water pouches the nomads stole, wherever you...",sec={{t="Water That Belongs to Gadgetzan",b="Luglunket, a seasoned spigot operator, would like nothing better than to receive the Wastewander water pouches you come across in the desert. It was Gadgetzan's water in the first place, and the nomads simply stole it. For every five pouches brought in, the Gadgetzan Water Company offers an official care package, and you are helping Gadgetzan help itself.",sp=0},{t="Keep Them Coming",b="Luglunket is glad of every pouch reclaimed, since each one keeps everyone further from disaster. Luglunket promises to make it worth your while for every five pouches you bring.",sp=1}},faq={{q="Who is Spigot Operator Luglunket?",a="A seasoned spigot operator in Gadgetzan who asks for Wastewander water pouches.",al={"who is luglunket","luglunket role","spigot operator"}},{q="Why does Luglunket want Wastewander water pouches?",a="The water is Gadgetzan's own, and the nomads stole it.",al={"why water pouches","why kill wastewander","wastewander water lore"}},{q="Where can Wastewander water pouches be found?",a="Out in the desert, in the hands of the Wastewander nomads who stole them.",al={"where to find water pouches","wastewander pouch location","who drops water pouches"}},{q="What does the Gadgetzan Water Company offer for the pouches?",a="One official care package for each set of five pouches.",al={"care package","what do i get for pouches"}}},kw={"gadgetzan","luglunket","tanaris","wastewander","water company","water pouch"},rel={"subzone:gadgetzan","zone:tanaris"},m={start="Spigot Operator Luglunket",["end"]="Spigot Operator Luglunket",level="44",id=1707},src={"Water Pouch Bounty"}}
E["quest:1878"] = {t="quest",n="Water Pouch Bounty",z="tanaris",s="Spigot Operator Luglunket greets you again, hoping you carry five more Wastewander water pouches, and keeping a care package ready.",h="Spigot Operator Luglunket greets you again, hoping you carry five more Wastewander water pouches, and keeping...",sec={{t="Back Again",b="After Water Pouch Bounty, Luglunket welcomes you back and asks whether five more Wastewander water pouches are in your pack. If so, a care package is already set aside with your name on it.",sp=0},{t="Keep Them Coming",b="Luglunket is pleased with the pouches reclaimed, since each one keeps everyone further from disaster. Luglunket promises to make it worth your while for every five pouches you bring.",sp=1}},faq={{q="Who is offering this bounty?",a="Luglunket, the spigot operator in Gadgetzan.",al={"who gives water pouch bounty","luglunket quest","who takes water pouches"}},{q="How many water pouches are needed?",a="Five Wastewander water pouches, the same as before.",al={"how many pouches","water pouch count","pouches per turn in"}},{q="What does Luglunket have ready?",a="A care package, held for you by name.",al={"what is the care package","what do i get"}},{q="What comes before this step?",a="It follows the earlier Water Pouch Bounty, in which you first brought pouches to Luglunket.",al={"previous quest","what do i do first"}}},kw={"care package","spigot operator luglunket","tanaris","wastewander water pouch","water pouch bounty"},rel={"quest:1707","zone:tanaris"},m={start="Spigot Operator Luglunket",["end"]="Spigot Operator Luglunket",level="44",faction="Neutral",id=1878},src={"Water Pouch Bounty (2)"}}
E["quest:243"] = {t="quest",n="Into the Field",z="tanaris",s="Apothecary Zinge sends you into the Tanaris desert with a field testing kit to test the tissue of basilisks, scorpids and hyenas. The modified kit also needs a power source that the goblins of Gadgetzan have, so Zinge points you to Chief Engineer Bilgewhizzle there.",h="Apothecary Zinge sends you into the Tanaris desert with a field testing kit to test the tissue of basilisks...",sec={{t="Tissue in the Desert",b="Apothecary Zinge wants the consistency of the tissue of the desert's basilisks, scorpids and hyenas tested. You gather samples and run them through the testing kit you carry, though a good chunk of the samples will fail. Eight acceptable samples of each kind of creature are needed, and Zinge asks you to return only once you have succeeded.",sp=0},{t="A Power Source in Gadgetzan",b="The modified kit has to be used with a power source of a kind the goblins of Gadgetzan have. Zinge sends you to Chief Engineer Bilgewhizzle in Gadgetzan to get one.",sp=0},{t="Nothing Is Free",b="Bilgewhizzle knows the model 4711-FTZ power sources well; they normally run the water wells, and thanks to the vile nomads there are more than enough of them just now. Bilgewhizzle will arrange one for whatever nefarious experiment you are trying to hide, but not for free, since in Gadgetzan nothing is.",sp=1}},faq={{q="Who sends you to Tanaris for this research?",a="Apothecary Zinge, who hands you a field testing kit and wants tissue from the desert creatures tested.",al={"who starts into the field","who gives into the field","into the field questgiver"}},{q="Why do you need to see Chief Engineer Bilgewhizzle?",a="The modified testing kit needs a power supply of the kind the goblins of Gadgetzan have, and Bilgewhizzle is the one to speak to about getting one.",al={"bilgewhizzle role","why visit bilgewhizzle","testing kit power source"}},{q="Which beasts are targeted for testing?",a="Basilisks, scorpids and hyenas of the Tanaris desert, with eight acceptable samples of each needed.",al={"beasts to test","into the field creature types","tissue samples tanaris"}}},kw={"apothecary","basilisk","bilgewhizzle","gadgetzan","hyena","power source","scorpid","tanaris","testing kit","zinge"},rel={"npc:apothecary-zinge","subzone:gadgetzan","zone:tanaris","quest:379","topic:goblin"},m={start="Apothecary Zinge",["end"]="Chief Engineer Bilgewhizzle",level="46",faction="Horde",id=243},src={"Into the Field"}}
E["quest:2605"] = {t="quest",n="The Thirsty Goblin",z="tanaris",s="Marin Noggenfogger in Gadgetzan is tormented by thirst. Rumor says the dew collectors of the cactus garden to the southwest store water in special glands, and Marin hopes one of those glands can become a drink that finally quenches it.",h="Marin Noggenfogger in Gadgetzan is tormented by thirst.",sec={{t="A Gland Worth Drinking",b="Marin has heard of strange creatures called dew collectors, living southwest of Gadgetzan, that keep water in special glands. A laden gland, Marin reckons, could be the start of a drink to end the thirst for good. You are asked to find the cactus garden where they live and bring one back.",sp=0}},faq={{q="Who sends you to hunt for the dew gland?",a="Marin Noggenfogger, in the town of Gadgetzan, asks you to find a laden dew gland to cure a terrible thirst.",al={"thirsty goblin questgiver","who starts thirsty goblin","marin noggenfogger"}},{q="Where are the dew collectors located?",a="They live in the cactus garden of Thistleshrub Valley, southwest of Gadgetzan in Tanaris.",al={"dew collector location","where to find dew gland","cactus garden location"}},{q="What creature carries the laden dew gland?",a="The glands come from the Thistleshrub Dew Collectors, creatures said to store water in special glands.",al={"what drops laden dew gland","dew collector mob"}},{q="What comes next in the chain?",a="The chain carries on with In Good Taste.",al={"thirsty goblin follow up","next quest after thirsty goblin"}}},kw={"cactus garden","dew collector","dew gland","gadgetzan","marin noggenfogger","tanaris","thistleshrub valley"},rel={"quest:2606","subzone:gadgetzan","zone:tanaris","subzone:thistleshrub-valley","quest:2641","quest:2661","quest:2662","topic:goblin"},m={start="Marin Noggenfogger",["end"]="Marin Noggenfogger",level="49",id=2605},src={"The Thirsty Goblin"}}
E["quest:2606"] = {t="quest",n="In Good Taste",z="tanaris",s="Marin Noggenfogger finds the thistleshrub dew terrible to taste, yet decides not to give up on it. You are sent to Sprinkle, a friend of Marin's in Gadgetzan, with the dew in hand.",h="Marin Noggenfogger finds the thistleshrub dew terrible to taste, yet decides not to give up on it.",sec={{t="A Cook for a Bad Brew",b="Marin tastes the dew and finds it awful, yet decides not to give up on the idea after all. Instead you are handed the dew and sent to Sprinkle, a friend in Gadgetzan whom Marin calls an excellent chef. You are to tell her what is going on and that the drink needs to go down more easily. Marin also wants it to have some kick.",sp=0}},faq={{q="Where does this step fit in the chain?",a="It follows The Thirsty Goblin, and Sprinkle's Secret Ingredient comes after it.",al={"what quest is before this","what is next in the chain","quest progression"}},{q="Why does Marin Noggenfogger want the dew taken to Sprinkle?",a="Marin found the dew awful to drink. Marin calls Sprinkle an excellent chef and hopes she can make it go down easier, with some kick to it.",al={"why sprinkle","what does marin want with sprinkle","who is sprinkle"}},{q="Where can Sprinkle be found?",a="Sprinkle is in Gadgetzan, the same town as Marin Noggenfogger.",al={"sprinkle location","where is sprinkle","find sprinkle"}}},kw={"gadgetzan","in good taste","marin noggenfogger","sprinkle","tanaris","thistleshrub dew"},rel={"quest:2605","quest:2641","quest:2661","quest:2662","subzone:gadgetzan","zone:tanaris","topic:goblin"},m={start="Marin Noggenfogger",["end"]="Sprinkle",level="49",id=2606},src={"In Good Taste"}}
E["quest:2641"] = {t="quest",n="Sprinkle's Secret Ingredient",z="tanaris",s="After Marin Noggenfogger's brew turns out foul, Sprinkle in Gadgetzan offers to make it edible with her secret ingredient, a mushroom called the Violet Tragan. It grows underwater in a small lake in the Hinterlands.",h="After Marin Noggenfogger's brew turns out foul, Sprinkle in Gadgetzan offers to make it edible with her...",sec={{t="A Cook's Secret",b="Sprinkle tells of her childhood, when her sister did all the cooking and the results were hard to stomach. Then she found a mushroom, the Violet Tragan, her \"secret\" ingredient, and it made every dish taste wonderful. She will use it to help turn Marin's horrid brew into something drinkable.",sp=0},{t="Under the Water",b="The mushroom is found in the Hinterlands, in a small lake there. Valorwind Lake lies just south of the road that crosses the zone. The Violet Tragan grows only underwater, so you will have to dive beneath the surface to gather it before returning to Sprinkle in Gadgetzan.",sp=0}},faq={{q="Who is Sprinkle?",a="Sprinkle is a cook in Gadgetzan and a friend of Marin Noggenfogger, who sent you to her with a bad-tasting brew.",al={"who is sprinkle","sprinkle gadgetzan","sprinkles secret ingredient quest giver"}},{q="What is the Violet Tragan?",a="It is a mushroom Sprinkle found as a child and calls her secret ingredient. She says it makes anything taste great.",al={"violet tragan","what is violet tragan","secret ingredient mushroom"}},{q="Where can the Violet Tragan be found?",a="Only underwater, in a small lake in the Hinterlands. Valorwind Lake lies just south of the road across the zone.",al={"where is violet tragan","where to find secret ingredient","violet tragan location"}},{q="How does this connect to Marin Noggenfogger?",a="Marin's brew tasted terrible, so Sprinkle wants the Violet Tragan to turn it into something edible.",al={"why does sprinkle need this","marin noggenfogger connection","noggenfogger questline"}}},kw={"gadgetzan","hinterlands","mushroom","noggenfogger","sprinkle","tanaris","violet tragan"},rel={"quest:2606","quest:2661","quest:2605","quest:2662","subzone:gadgetzan","zone:tanaris","zone:hinterlands","topic:goblin"},m={start="Sprinkle",["end"]="Sprinkle",level="49",id=2641},src={"Sprinkle's Secret Ingredient"}}
E["quest:2661"] = {t="quest",n="Delivery for Marin",z="tanaris",s="Sprinkle in Gadgetzan hands you the Violet Powder to carry to Marin Noggenfogger, along with a reminder that Marin owes her a favor.",h="Sprinkle in Gadgetzan hands you the Violet Powder to carry to Marin Noggenfogger, along with a reminder that...",sec={{t="A Town Delivery",b="With the Violet Tragan in hand, Sprinkle gives you the Violet Powder to take to Marin Noggenfogger, who is also in Gadgetzan. You are to tell Marin that a favor is owed to her.",sp=0}},faq={{q="Who sends you to Marin Noggenfogger?",a="Sprinkle, in Gadgetzan, gives you the Violet Powder after you bring her the Violet Tragan.",al={"who gives delivery for marin","delivery for marin quest giver","sprinkle delivery"}},{q="What item are you delivering?",a="Violet Powder, which Sprinkle gives you to carry to Marin Noggenfogger.",al={"what do you bring marin","marin delivery item","what powder is it"}},{q="Where is Marin Noggenfogger located?",a="In Gadgetzan, the same town as Sprinkle.",al={"marin noggenfogger location","where is marin","find marin noggenfogger"}},{q="What message does Sprinkle want passed to Marin?",a="She wants Marin told that he owes her a favor.",al={"sprinkle message","what does sprinkle say to marin","sprinkle favor"}}},kw={"gadgetzan","marin noggenfogger","noggenfogger elixir","sprinkle","tanaris","violet powder"},rel={"quest:2641","quest:2662","quest:2606","quest:2605","subzone:gadgetzan","zone:tanaris","topic:goblin"},m={start="Sprinkle",["end"]="Marin Noggenfogger",level="49",id=2661},src={"Delivery for Marin"}}
E["quest:2662"] = {t="quest",n="Noggenfogger Elixir",z="tanaris",s="Marin Noggenfogger in Gadgetzan takes the Violet Powder to mix into the dew, and asks you to come back to him in a moment, once his fabulous elixir is perfected.",h="Marin Noggenfogger in Gadgetzan takes the Violet Powder to mix into the dew, and asks you to come back to him...",sec={{t="Mixing the Elixir",b="Marin, who has the dew and now the powder, sets about mixing the one into the other. You are to wait a short while and then speak to Marin again, when the Noggenfogger Elixir should be ready.",sp=0},{t="Marin's Verdict",b="When Marin is done, a drink is pressed on you and declared wonderful. Marin boasts of the millions the elixir will bring, asks you to stand aside so you are not blocking business, and laughs off Sprinkle's claim of a favor as a joke.",sp=1}},faq={{q="Who offers this quest?",a="Marin Noggenfogger, in Gadgetzan.",al={"noggenfogger quest giver","who gives noggenfogger elixir","marin noggenfogger quest"}},{q="What came before this step?",a="It follows Delivery for Marin. Before that came The Thirsty Goblin, In Good Taste and Sprinkle's Secret Ingredient.",al={"prereq noggenfogger elixir","previous quest for marin","what comes before noggenfogger elixir"}},{q="What ingredients does Marin combine here?",a="Marin mixes the Violet Powder from Sprinkle into the dew.",al={"noggenfogger ingredients","what is marin mixing","what is in the elixir"}}},kw={"dew","gadgetzan","goblin","marin noggenfogger","noggenfogger elixir","powder","sprinkle","tanaris"},rel={"quest:2661","quest:2641","quest:2606","quest:2605","subzone:gadgetzan","zone:tanaris","topic:goblin"},m={start="Marin Noggenfogger",["end"]="Marin Noggenfogger",level="49",id=2662},src={"Noggenfogger Elixir (quest)"}}
E["quest:2741"] = {t="quest",n="The Super Egg-O-Matic",z="tanaris",s="Curgle Cranklehop's newest invention is an impressive piece of machinery, and it sputters wildly when you reach its control panel. Hippogryph eggs go into it.",h="Curgle Cranklehop's newest invention is an impressive piece of machinery, and it sputters wildly when you...",sec={{t="A Machine of Curgle Cranklehop",b="Curgle Cranklehop's newest invention makes an impressive sight. When you walk up to its control panel it sputters wildly. It is built to take a hippogryph egg, and the eggs are to be found in the mountains of southern Feralas, around the Ruins of Isildien.",sp=0},{t="What the Machine Does",b="Place a hippogryph egg inside and the machine answers with a run of beeps and odd mechanical noises. Its Eggometer weighs and measures the egg, then packages it up, all in very quick service. What comes out is an Egg Crate, which holds an egg of some variety.",sp=1}},faq={{q="Who built the Super Egg-O-Matic?",a="Curgle Cranklehop, whose latest invention it is.",al={"who made egg-o-matic","egg-o-matic creator","curgle cranklehop invention"}},{q="What does the machine need to operate?",a="A hippogryph egg, which you place into the machine.",al={"what do i give the egg-o-matic","egg-o-matic item needed","hippogryph egg machine"}},{q="Where do you find hippogryph eggs?",a="Up in the mountains of southern Feralas, around the Ruins of Isildien.",al={"hippogryph egg location","where to find hippogryph eggs","where are the eggs feralas"}}},kw={"curgle cranklehop","egg-o-matic","eggometer","feralas","hippogryph egg","tanaris"},rel={"zone:tanaris","zone:feralas","subzone:ruins-of-isildien"},m={start="Egg-O-Matic",["end"]="Egg-O-Matic",level="47",faction="Neutral",id=2741},src={"The Super Egg-O-Matic"}}
E["quest:2747"] = {t="quest",n="An Extraordinary Egg",z="tanaris",s="Curgle Cranklehop has rarely seen an egg from Feralas in extraordinary shape. Such eggs are the rarest of all.",h="Curgle Cranklehop has rarely seen an egg from Feralas in extraordinary shape.",sec={{t="A Rarity from Feralas",b="Curgle Cranklehop says that very few eggs come out of Feralas in extraordinary shape, and that these are the rarest of all. An egg of that kind is what Curgle is looking for.",sp=0}},faq={{q="Who is looking for an extraordinary egg?",a="Curgle Cranklehop, who is the inventor of the Super Egg-O-Matic.",al={"who starts an extraordinary egg","who gives an extraordinary egg quest","curgle cranklehop egg"}},{q="Where do these extraordinary eggs come from?",a="They are retrieved from Feralas, but very few arrive in extraordinary shape.",al={"extraordinary egg location","where to find extraordinary egg","egg from feralas"}},{q="What comes before this request?",a="It follows The Super Egg-O-Matic.",al={"prerequisite for extraordinary egg","an extraordinary egg chain","previous quest for extraordinary egg"}}},kw={"curgle cranklehop","extraordinary egg","feralas","super egg-o-matic","tanaris"},rel={"quest:2741","zone:feralas","zone:tanaris"},m={start="Curgle Cranklehop",["end"]="Curgle Cranklehop",level="60",id=2747},src={"An Extraordinary Egg"}}
E["quest:2748"] = {t="quest",n="A Fine Egg",z="tanaris",s="Curgle Cranklehop speaks of the fine egg, which stands a chance of hatching free of the Gordunni ogres' evil incantations.",h="Curgle Cranklehop speaks of the fine egg, which stands a chance of hatching free of the Gordunni ogres' evil...",sec={{t="What Makes It Fine",b="Curgle Cranklehop describes a fine egg as one with a good chance of hatching untouched by the wicked chanting of the Gordunni ogres, provided conditions are ideal.",sp=0},{t="What Curgle Does Next",b="Curgle takes the egg and plans to send it to Darnassus, where it is hoped that it will soon hatch.",sp=1}},faq={{q="What makes an egg considered a fine egg?",a="With ideal conditions it can hatch free of the evil that Gordunni ogre incantations bring.",al={"what is a fine egg","fine egg lore","why fine egg"}},{q="What came before this step?",a="It follows The Super Egg-O-Matic.",al={"fine egg prerequisite","previous quest fine egg"}}},kw={"curgle cranklehop","darnassus","fine egg","gordunni","ogre incantations","super egg-o-matic","tanaris"},rel={"quest:2741","zone:darnassus","zone:tanaris"},m={start="Curgle Cranklehop",["end"]="Curgle Cranklehop",level="60",id=2748},src={"A Fine Egg"}}
E["quest:2749"] = {t="quest",n="An Ordinary Egg",z="tanaris",s="Curgle Cranklehop works with ordinary hippogryph eggs, which are a coin toss: about half of them hatch. Curgle tends them and hopes for luck.",h="Curgle Cranklehop works with ordinary hippogryph eggs, which are a coin toss: about half of them hatch.",sec={{t="Half a Chance",b="An ordinary hippogryph egg hatches only about half the time. Curgle Cranklehop does their best to nurture each one, and with some luck it will hatch.",sp=0}},faq={{q="Who is Curgle Cranklehop?",a="Curgle Cranklehop is the inventor of the Super Egg-O-Matic, and works with the hippogryph eggs found in Feralas.",al={"who is curgle","curgle cranklehop"}},{q="What happens to the ordinary hippogryph egg?",a="Curgle tends it and hopes for luck, since only about half of such eggs hatch.",al={"what does curgle do with the egg","egg hatching chance"}},{q="Where do these eggs come from?",a="From Feralas.",al={"where do i find the egg","ordinary egg location"}},{q="What came before this step?",a="It follows The Super Egg-O-Matic.",al={"prerequisite quest","what is the previous quest"}}},kw={"curgle cranklehop","feralas","hippogryph","ordinary egg","tanaris","the super egg-o-matic"},rel={"quest:2741","zone:feralas","zone:tanaris"},m={start="Curgle Cranklehop",["end"]="Curgle Cranklehop",level="60",id=2749},src={"An Ordinary Egg"}}
E["quest:2750"] = {t="quest",n="A Bad Egg",z="tanaris",s="Curgle Cranklehop speaks of the eggs that cannot be saved, which will never hatch.",h="Curgle Cranklehop speaks of the eggs that cannot be saved, which will never hatch.",sec={{t="An Egg Beyond Saving",b="Some hippogryph eggs cannot be saved, and a bad egg is one that will never hatch. It is Curgle Cranklehop who deals with such eggs.",sp=0},{t="What Becomes of It",b="Curgle takes the egg so that it is disposed of properly. Not every egg can be saved, Curgle says, and you should not be discouraged but try again with another egg from Feralas.",sp=1}},faq={{q="Who accepts the bad egg?",a="Curgle Cranklehop.",al={"who do i give bad egg to","curgle cranklehop egg","who takes bad egg"}},{q="Can the egg be saved?",a="No. A bad egg is one that cannot be saved and will never hatch.",al={"can bad egg hatch","will bad egg hatch","save bad egg"}},{q="What came before this?",a="It follows The Super Egg-O-Matic.",al={"previous quest","pre-req","bad egg prerequisite"}}},kw={"bad egg","curgle cranklehop","feralas","super egg-o-matic","tanaris"},rel={"quest:2741","zone:tanaris","zone:feralas"},m={start="Curgle Cranklehop",["end"]="Curgle Cranklehop",level="60",id=2750},src={"A Bad Egg"}}
E["quest:2781"] = {t="quest",n="WANTED: Caliph Scorpidsting",z="tanaris",s="The Gadgetzan Water Company posts a bounty on Caliph Scorpidsting, who heads the Wastewander outlaws. Proof of his death goes to Chief Engineer Bilgewhizzle in Gadgetzan.",h="The Gadgetzan Water Company posts a bounty on Caliph Scorpidsting, who heads the Wastewander outlaws.",sec={{t="The Company's Charges",b="Notices at Gadgetzan and Steamwheedle Port announce a high bounty from the Gadgetzan Water Company for Caliph Scorpidsting, who leads the Wastewander outlaws. The charges against him are the murder of company employees, the theft of company resources and the seizure of company property. Proof of his death is to go to Chief Engineer Bilgewhizzle in Gadgetzan.",sp=0},{t="What the Water Company Hopes For",b="Chief Engineer Bilgewhizzle calls Scorpidsting's death justice and a mighty blow against the Wastewanders, whom the engineer calls vile nomads and squatters. The hope is that it might finally push them off the water wells of Gadgetzan, and the bounty is paid on behalf of the company.",sp=1}},faq={{q="Who is Caliph Scorpidsting?",a="He leads the Wastewander outlaws, wanted by the Gadgetzan Water Company.",al={"caliph scorpidsting lore","who leads wastewanders","scorpidsting"}},{q="Why does the Gadgetzan Water Company want him dead?",a="The company accuses him of murdering its employees, stealing its resources and seizing its property.",al={"why bounty on scorpidsting","caliph scorpidsting crimes","gadgetzan water company enemy"}},{q="Who pays the bounty for Caliph Scorpidsting?",a="Chief Engineer Bilgewhizzle of the Gadgetzan Water Company, in Gadgetzan, takes proof of Scorpidsting's death.",al={"who turns in scorpidsting","where to turn in caliph head","bilgewhizzle bounty"}},{q="Where are the wanted posters located?",a="In Gadgetzan and at Steamwheedle Port.",al={"caliph poster location","where to pick up caliph bounty","scorpidsting notice"}}},kw={"bounty","caliph scorpidsting","chief engineer bilgewhizzle","gadgetzan","gadgetzan water company","steamwheedle port","tanaris","wastewander"},rel={"subzone:gadgetzan","zone:tanaris"},m={start="Wanted Poster (Gadgetzan) / Wanted Poster (Steamwheedle Port)",["end"]="Chief Engineer Bilgewhizzle",level="46",faction="Neutral",id=2781},src={"WANTED: Caliph Scorpidsting"}}
E["quest:2872"] = {t="quest",n="Stoley's Debt",z="tanaris",s="\"Sea Wolf\" MacKinley has a bet with his old friend Stoley, who tends the bar at Steamwheedle Port, over whose rum is stronger. Stoley seems to be dodging it, so MacKinley asks you to go and talk to him.",h="\"Sea Wolf\" MacKinley has a bet with his old friend Stoley, who tends the bar at Steamwheedle Port, over whose...",sec={{t="A Matter of Rum and Coin",b="Stoley owes \"Sea Wolf\" MacKinley a very special bottle of rum. Stoley boasted that the rum at Steamwheedle Port is stronger than anything in Booty Bay, and said the money owed would be doubled if MacKinley tried it and disagreed. Now MacKinley thinks Stoley has lost his nerve about handing it over, but MacKinley never backs away from a wager. You are asked to go and speak to Stoley at the Steamwheedle Port bar.",sp=0},{t="Stoley's Answer",b="Stoley is not afraid to hand over Steamwheedle Bilge Rum, and says so. The trouble is that there is no rum left to give.",sp=1}},faq={{q="Who is \"Sea Wolf\" MacKinley?",a="A friend of Stoley's who has a wager with him about whose rum is stronger. He mentions Booty Bay as the place to compare it to.",al={"who is mackinley","sea wolf mackinley","who gives stoleys debt"}},{q="Where is Stoley located?",a="Stoley is the barkeep at Steamwheedle Port in Tanaris.",al={"where is stoley","stoley location","find stoley"}},{q="What bet did Stoley make with MacKinley?",a="Stoley boasted that the rum at Steamwheedle Port beats anything in Booty Bay. If MacKinley tried it and disagreed, Stoley would double the money he owes him.",al={"what is the wager","what bet","stoley wager"}}},kw={"bilge rum","booty bay","mackinley","rum","steamwheedle port","stoley","tanaris","wager"},rel={"quest:2873","quest:2874","subzone:steamwheedle-port","subzone:booty-bay","zone:tanaris"},m={start="\"Sea Wolf\" MacKinley",["end"]="Stoley",level="45",id=2872},src={"Stoley's Debt"}}
E["quest:2873"] = {t="quest",n="Stoley's Shipment",z="tanaris",s="Stoley is out of rum and in debt to a friend over a wager. Captain Cuergo stole the last shipment and keeps it in the walled pirate town to the south, so Stoley asks you to bring it back.",h="Stoley is out of rum and in debt to a friend over a wager.",sec={{t="A Stolen Shipment",b="Stoley has none left of the rum promised to \"Sea Wolf\" MacKinley of Booty Bay to settle their wager. Captain Cuergo stole the last shipment, and has it stowed in the walled pirate town to the south, which is Lost Rigger Cove. Stoley asks you to find the rum and return it, so that he can show Kalimdor's drink is far better than anything Booty Bay pours.",sp=0},{t="Where It Is Kept",b="Inside the pirate town, the rum sits in crates on the upper floor of the house in the northwest.",sp=0}},faq={{q="Who is Stoley?",a="Stoley is at Steamwheedle Port in Tanaris, and owes rum to \"Sea Wolf\" MacKinley in Booty Bay to settle a bet.",al={"stoley","who gives stoleys shipment","stoley tanaris"}},{q="Why does Stoley want his shipment back?",a="Captain Cuergo stole his last shipment of rum. Stoley needs it to settle a bet with MacKinley, and to prove that Kalimdor's booze beats Booty Bay's.",al={"why rum","stoley motivation","what is stoleys shipment"}},{q="Where did the pirates hide the rum?",a="In the walled pirate town to the south, Lost Rigger Cove, in crates on the upper floor of the northwestern house.",al={"stoley rum location","where is shipment","lost rigger cove rum"}},{q="Who is Captain Cuergo?",a="The one who stole Stoley's last shipment of rum and keeps it in the walled pirate town to the south.",al={"cuergo","captain cuergo"}},{q="Where does this step fit in the chain?",a="It follows Stoley's Debt.",al={"stoleys shipment chain","what comes after stoleys debt"}},{q="Who is \"Sea Wolf\" MacKinley?",a="He is in Booty Bay and made a wager with Stoley over whose rum is better.",al={"sea wolf mackinley","mackinley booty bay"}}},kw={"cuergo","lost rigger cove","mackinley","rum","shipment","steamwheedle port","stoley","tanaris"},rel={"quest:2872","quest:2874","subzone:steamwheedle-port","subzone:lost-rigger-cove","subzone:booty-bay","topic:pirate","zone:tanaris"},m={start="Stoley",["end"]="Stoley",level="45",faction="Neutral",id=2873},src={"Stoley's Shipment (quest)"}}
E["quest:2874"] = {t="quest",n="Deliver to MacKinley",z="tanaris",s="Stoley hands you a bottle of Steamwheedle bilge rum for MacKinley, the \"Sea Wolf\" of Booty Bay, to put an end to MacKinley's beliefs about Booty Bay booze.",h="Stoley hands you a bottle of Steamwheedle bilge rum for MacKinley, the \"Sea Wolf\" of Booty Bay, to put an end...",sec={{t="A Bottle to Carry",b="After the help you gave with the shipment, Stoley gives you a bottle of Steamwheedle bilge rum. You are to take it to MacKinley, in Booty Bay, so that he can finally let go of his crazy beliefs about the booze there.",sp=0},{t="MacKinley's Verdict",b="MacKinley tries the rum and cannot believe how awful it is, which delights him. Stoley kept his word about the bilge rum, so he need not pay the money he owes. MacKinley calls the stuff thick as gravel and burning like lava.",sp=1}},faq={{q="Who gives you the bottle?",a="Stoley, at Steamwheedle Port.",al={"who starts deliver to mackinley","deliver to mackinley quest giver"}},{q="Who receives the bottle of rum?",a="\"Sea Wolf\" MacKinley, in Booty Bay.",al={"where do i take the bottle","who gets the rum","mackinley location"}},{q="What kind of alcohol is being delivered?",a="A bottle of Steamwheedle bilge rum.",al={"what rum is it","what booze does stoley give"}},{q="Where does this step fit in the chain?",a="It follows Stoley's Debt and Stoley's Shipment.",al={"what comes before deliver to mackinley","deliver to mackinley quest chain"}}},kw={"booty bay","mackinley","sea wolf mackinley","steamwheedle bilge rum","stoley","stoley's debt","stoley's shipment","tanaris"},rel={"quest:2873","quest:2872","subzone:booty-bay","zone:tanaris"},m={start="Stoley",["end"]="\"Sea Wolf\" MacKinley",level="45",faction="Neutral",id=2874},src={"Deliver to MacKinley"}}
E["quest:2875"] = {t="quest",n="WANTED: Andre Firebeard",z="tanaris",s="A wanted notice in Gadgetzan and Steamwheedle Port names the pirate Andre Firebeard, who stands accused of crimes against Steamwheedle and Gadgetzan. The notice declares that his head, delivered to Security Chief Bilgewhizzle at Steamwheedle Port, counts as a binding contract.",h="A wanted notice in Gadgetzan and Steamwheedle Port names the pirate Andre Firebeard, who stands accused of...",sec={{t="The Decree",b="The notice calls Andre Firebeard a vile pirate, accused of crimes against Steamwheedle and Gadgetzan. The governing counsel has decreed that anyone who reads it may use lethal force in capturing Andre and those who aid him. He is to be found at the pirate enclave a way south along the coast from Steamwheedle Port, where he stands by a campfire inside the walls.",sp=0},{t="The Head as Proxy",b="A further decree says that if Andre is dead or otherwise unable to attend when his hearing comes, his head can act in his place. Delivered to Security Chief Bilgewhizzle at Steamwheedle Port, it counts as a binding contract.",sp=0},{t="Terms of Payment",b="Bilgewhizzle is pleased that Andre will make his trial after all. Payment is issued once you sign, and Bilgewhizzle waves off the small print as harmless, adding that it is too small for any magnifying glass to read.",sp=1}},faq={{q="Who is Andre Firebeard?",a="A pirate accused of crimes against Steamwheedle and Gadgetzan.",al={"andre firebeard","who is andre","firebeard tanaris"}},{q="Where can the wanted notice be found?",a="In Gadgetzan and at Steamwheedle Port.",al={"where to get quest","wanted poster location","wanted andre firebeard poster"}},{q="Where is Andre Firebeard located?",a="At a campfire inside the walls of the pirate enclave, a way south along the coast from Steamwheedle Port.",al={"firebeard location","where is firebeard","find andre firebeard"}},{q="Who receives the head once Andre is dealt with?",a="Security Chief Bilgewhizzle, in Steamwheedle Port.",al={"who do i turn in firebeard to","bilgewhizzle location","where to turn in firebeard head"}},{q="Why is his head required?",a="A decree lets it act in his place if he is dead or otherwise unable to attend when his hearing comes.",al={"why his head","head as proxy","trial proxy"}}},kw={"andre firebeard","bilgewhizzle","gadgetzan","pirate enclave","steamwheedle port","tanaris","wanted poster"},rel={"subzone:steamwheedle-port","subzone:gadgetzan","zone:tanaris","topic:pirate"},m={start="Wanted Poster (Gadgetzan) / Wanted Poster (Steamwheedle Port)",["end"]="Security Chief Bilgewhizzle",level="45",faction="Neutral",id=2875},src={"WANTED: Andre Firebeard"}}
E["quest:2876"] = {t="quest",n="Ship Schedules",z="tanaris",s="A scroll records ships sailing between Steamwheedle Port and Booty Bay, with marks beside some voyages. It belongs in the hands of an authority at Steamwheedle Port.",h="A scroll records ships sailing between Steamwheedle Port and Booty Bay, with marks beside some voyages.",sec={{t="The Scroll",b="The scroll lists the shipments that sail between Steamwheedle Port and Booty Bay, those already made and those to come, along with the ships' names. Some journeys are marked with a large X, and others carry notes about plunder to be had or a hard fight. It is meant for someone in authority at Steamwheedle Port.",sp=0},{t="The Port's Reaction",b="Security Chief Bilgewhizzle finds the dates and times on the schedule accurate, and fears what a pirate captain could do with it. On hearing that you took it from a pirate, Bilgewhizzle calls that disturbing news, thanks you, and is glad the pirate is dead.",sp=1}},faq={{q="What is written on the schedule?",a="Ship names and the timings of voyages between Steamwheedle Port and Booty Bay, past and future, with large X marks beside some journeys and notes about plunder or a hard fight beside others.",al={"what does the ship schedule say","ship schedule text","shipment notes"}},{q="Who needs to see this document?",a="Someone in authority at Steamwheedle Port. Security Chief Bilgewhizzle is the one who takes it.",al={"who do i give the schedule to","ship schedules turn in","where does the schedule go"}}},kw={"bilgewhizzle","booty bay","pirates","ship schedules","steamwheedle port","tanaris"},rel={"subzone:steamwheedle-port","subzone:booty-bay","topic:pirate","zone:tanaris"},m={start="Ship Schedule",["end"]="Security Chief Bilgewhizzle",level="45",id=2876},src={"Ship Schedules"}}
E["quest:2954"] = {t="quest",n="The Stone Watcher",z="tanaris",s="You carried the platinum discs out to the Tanaris desert, and the Stone Watcher of Norgannon has appeared at the Uldum Pedestal. It guards entry to the Uldum compound and admits only those whose disc set includes the Plates of Uldum. You are to learn its story before going on.",h="You carried the platinum discs out to the Tanaris desert, and the Stone Watcher of Norgannon has appeared at...",sec={{t="A Guardian at the Pedestal",b="The Watcher's arrival is just the reaction that was hoped for when you were sent out to the desert of Tanaris carrying the platinum discs. It names itself a guardian of entry, and it will not let you into the Uldum compound unless the Plates of Uldum are already integrated with your disc set. Before going further you are to find out the story behind the Stone Watcher, and then use the Uldum Pedestal.",sp=0},{t="What the Watcher Explains",b="The Stone Watcher is there to control who may enter the Uldum complex on behalf of the Creators, and lets in only those who show the proper sequencing discs. The Plates of Uldum are discs made by the Creators that store data on their activities at Uldum. They are almost the same size as your own discs, but their markings concern Uldum rather than Uldaman. Uldum is a research facility, where the Creators work to enhance Azeroth's biosphere, and details of their work are for those who hold the Plates. In the end the Watcher promises that your discs will be returned once you access the pedestal, and that you may enter the complex once you have the Plates in your set.",sp=1},{t="More From the Watcher",b="The Stone Watcher adds that the Creators control the distribution of these discs for all the complexes of this world, and that Azeroth has been rescheduled for a visitation. The Creators use visitation to reestablish control over seeded worlds whenever forces from outside or within upset the balance of those worlds' matrix dynamics, and it is not to be taken lightly.",sp=2}},faq={{q="Who is the Stone Watcher of Norgannon?",a="A guardian of entry standing at the Uldum Pedestal out in the desert of Tanaris, which decides who may enter the Uldum compound.",al={"what is the stone watcher","who is the watcher at uldum","stone watcher identity"}},{q="Why does the Stone Watcher deny entry?",a="Entry is allowed only if the Plates of Uldum are already integrated with your disc set, and yours do not yet have them.",al={"why can't i enter uldum","plates of uldum missing","uldum entry denied"}}},kw={"creators","plates of uldum","platinum discs","stone watcher of norgannon","tanaris","uldaman","uldum","uldum pedestal"},rel={"subzone:uldum","zone:tanaris","subzone:uldaman"},m={start="Uldum Pedestal",["end"]="Uldum Pedestal",level="50",id=2954},src={"The Stone Watcher"}}
E["quest:3022"] = {t="quest",n="Handle With Care",z="tanaris",s="Curgle Cranklehop gives you a crate of eggs and asks you to carry it to the druid Erelas Ambersky, who can be found in Rut'theran, a small village in Teldrassil.",h="Curgle Cranklehop gives you a crate of eggs and asks you to carry it to the druid Erelas Ambersky, who can be...",sec={{t="A Crate of Eggs",b="Curgle Cranklehop gives you a carefully packed crate of eggs. They are hippogryph eggs, and they are bound for a druid named Erelas Ambersky.",sp=0},{t="The Druid of Rut'theran",b="Erelas Ambersky is a druid who cares for these eggs. He helps them hatch and then trains the young hippogryphs. Rut'theran Village is a small village in Teldrassil, to the south.",sp=0}},faq={{q="What is inside the crate from Curgle Cranklehop?",a="The carefully packed crate holds hippogryph eggs.",al={"what is in the crate","carefully packed crate contents","what am i carrying"}},{q="Where does the crate need to go?",a="The crate goes to the druid Erelas Ambersky, in the small village of Rut'theran in Teldrassil.",al={"where do i take the crate","erelas ambersky location","where is rut'theran village"}},{q="Who is Erelas Ambersky?",a="Erelas Ambersky is a druid in Rut'theran Village. He looks after hippogryph eggs and trains the young hippogryphs once they hatch.",al={"who is erelas","ambersky lore","who receives the eggs"}}},kw={"curgle cranklehop","erelas ambersky","hippogryph eggs","rut'theran village","tanaris","teldrassil"},rel={"subzone:rut-theran-village","zone:tanaris"},m={start="Curgle Cranklehop",["end"]="Erelas Ambersky",level="47",faction="Alliance",id=3022},src={"Handle With Care (Tanaris)"}}
E["quest:3161"] = {t="quest",n="Gahz'ridian",z="tanaris",s="Marvon Rivetseeker, a scientist and treasure hunter at heart, wants thirty ornaments left behind by the trolls who once lived in Tanaris. Marvon gives you a detector of their own invention to help find them.",h="Marvon Rivetseeker, a scientist and treasure hunter at heart, wants thirty ornaments left behind by the...",sec={{t="Relics of the Hydra God",b="Long ago trolls occupied this land, and they made great numbers of ornaments in the likeness of Gahz'rilla, a hydra they revered as a god. Marvon Rivetseeker calls the element these were carved from Gahz'ridian, after the hydra god. Marvon has found a few and would like more to study.",sp=0},{t="The Detector",b="Marvon has invented a detector that makes finding Gahz'ridian simple, and gives it to you. Wearing it starts the search. Ornaments can be found nearly anywhere in Tanaris, though they gather thickest near Broken Pillar, the Eastmoon Ruins and the Southmoon Ruins.",sp=0}},faq={{q="Who is Marvon Rivetseeker?",a="Marvon Rivetseeker is a scientist in Tanaris who is also a treasure hunter at heart. He studies the ornaments the old trolls made.",al={"marvon rivetseeker","who gives gahzridian","quest giver"}},{q="What is Gahz'ridian?",a="It is Marvon Rivetseeker's name for the element the trolls' hydra ornaments were carved from, taken from the hydra god.",al={"what is gahzridian","gahzridian mineral","gahzridian material"}},{q="Who is Gahz'rilla?",a="Gahz'rilla is a hydra that the old trolls revered as a god. They made their ornaments in its likeness.",al={"gahzrilla deity","hydra worship","who is gahzrilla"}},{q="Where are Gahz'ridian ornaments found?",a="Nearly anywhere in Tanaris, though the heaviest concentrations are around Broken Pillar and the Eastmoon and Southmoon Ruins.",al={"where to find gahzridian","best place for gahzridian","gahzridian locations"}},{q="How do you find the ornaments?",a="Marvon has invented a detector for the purpose. Wearing it starts the search.",al={"how to spot ornaments","gahzridian detector","finding gahzridian"}}},kw={"broken pillar","detector","eastmoon ruins","gahz'ridian","gahz'rilla","marvon rivetseeker","southmoon ruins","tanaris","troll"},rel={"zone:tanaris","subzone:broken-pillar","subzone:eastmoon-ruins","subzone:southmoon-ruins"},m={start="Marvon Rivetseeker",["end"]="Marvon Rivetseeker",level="48",faction="Neutral",id=3161},src={"Gahz'ridian (quest)"}}
E["quest:32"] = {t="quest",n="Rise of the Silithid",z="tanaris",s="Senior Surveyor Fizzledowser hands you the report on the insect threat and urges you to take it to Orgrimmar, to a troll scholar named Zilzibin Drumlore.",h="Senior Surveyor Fizzledowser hands you the report on the insect threat and urges you to take it to Orgrimmar...",sec={{t="Someone Who Knows",b="Fizzledowser wants the report in the hands of someone who has working knowledge of such matters. Zilzibin Drumlore is a troll scholar who has spent a lot of time studying the life forms unique to Azeroth's ecology, and is a historian besides. Fizzledowser hopes Zilzibin can work out what the danger really is and how it might be halted, and says all the help available will be needed. Zilzibin lives in a house on the Drag's second tier, in Orgrimmar.",sp=0},{t="Zilzibin's Answer",b="Zilzibin has dealt with these creatures before and thinks Fizzledowser chose well in sending the report, and you. They will devour the Tanaris desert rapidly and number among the greatest menaces anyone will face. They are the silithid, the tools of one of the gravest threats to both Horde and Alliance. Zilzibin laments that no one was wise enough to see it sooner.",sp=1}},faq={{q="Who is Zilzibin Drumlore?",a="A troll scholar and historian who has spent a lot of time studying the life forms unique to the ecology of Azeroth.",al={"who is drumlore","zilzibin drumlore lore","troll scholar in orgrimmar"}},{q="Who sends you to Zilzibin?",a="Senior Surveyor Fizzledowser, who gives you the report and asks you to carry it to Orgrimmar.",al={"rise of the silithid start","who gives rise of the silithid"}},{q="Where is Zilzibin Drumlore located in Orgrimmar?",a="In a house on the Drag, up on its second tier, in Orgrimmar.",al={"where is zilzibin","where is drumlore house"}},{q="What comes directly before this step?",a="It follows Insect Part Analysis.",al={"previous quest rise of the silithid","what led to rise of the silithid"}}},kw={"drag","drumlore","fizzledowser","insects","orgrimmar","silithid","tanaris","zilzibin"},rel={"npc:senior-surveyor-fizzledowser","quest:113","zone:tanaris","zone:orgrimmar","subzone:drag","topic:troll","topic:horde","topic:alliance"},m={start="Senior Surveyor Fizzledowser",["end"]="Zilzibin Drumlore",level="48",faction="Horde",id=32},src={"Rise of the Silithid (Horde)"}}
E["quest:3362"] = {t="quest",n="Thistleshrub Valley",z="tanaris",s="Tran'rek in Gadgetzan wants to get into Thistleshrub Valley, but the strange beasts there keep them away. Clear some of the thistleshrubs out, and Tran'rek might think about going back.",h="Tran'rek in Gadgetzan wants to get into Thistleshrub Valley, but the strange beasts there keep them away.",sec={{t="A Dangerous Valley",b="Thistleshrub Valley lies south-west of Gadgetzan, and Tran'rek calls it a mighty dangerous place. They do not trust the strange beasts there, gnarled thistleshrubs and thistleshrub rootshapers, and with so many around they will not go back.",sp=0},{t="Thinning the Thistleshrubs",b="Tran'rek wants eight gnarled thistleshrubs and eight thistleshrub rootshapers cleared out. There is one condition: Tran'rek wants a closer look at the cactus in the valley, so some of it must be left in one piece.",sp=0}},faq={{q="Who asks for help with Thistleshrub Valley?",a="Tran'rek, who is in Gadgetzan.",al={"quest giver","tran'rek location","who offers thistleshrub valley"}},{q="Where is Thistleshrub Valley?",a="It lies south-west of Gadgetzan.",al={"thistleshrub valley location","where is valley","find valley tanaris"}},{q="Which creatures need clearing out?",a="Eight gnarled thistleshrubs and eight thistleshrub rootshapers.",al={"targets","what to kill","which thistleshrubs"}},{q="Why does Tran'rek want some of the cactus left in one piece?",a="Tran'rek wants to take a closer look at the cactus in the valley, so some of it should be left in one piece.",al={"tranrek motive","why go to valley","cacti interest"}}},kw={"cactus","gadgetzan","gnarled thistleshrub","rootshaper","tanaris","thistleshrub","tran'rek","thistleshrub valley"},rel={"subzone:thistleshrub-valley","subzone:gadgetzan","zone:tanaris"},m={start="Tran'rek",["end"]="Tran'rek",level="50",faction="Neutral",id=3362},src={"Thistleshrub Valley (quest)"}}
E["quest:3444"] = {t="quest",n="The Stone Circle",z="tanaris",s="Marvon Rivetseeker once went into the Sunken Temple and only just got out. A round stone with a serpent symbol, now sitting in Marvon's workshop in Ratchet, might let Marvon tell you more, and you are asked to fetch it.",h="Marvon Rivetseeker once went into the Sunken Temple and only just got out.",sec={{t="Marvon's Memory",b="Marvon Rivetseeker speaks of the evil in the Sunken Temple that seeps into everyone who walks its chambers. Escape was a struggle through the ooze now spread across the floors, and what remains is a memory of a big round room crowded with statues of serpents.",sp=0},{t="The Stone in Ratchet",b="Marvon has since come across a round stone that seems to bear the same serpent symbol. Marvon had it crated and sent on to the workshop in Ratchet. Fetch it and Marvon may have more to share.",sp=0},{t="When the Stone Returns",b="Seeing the stone, Marvon confirms it is the right one and says it is all coming back.",sp=1}},faq={{q="Who is Marvon Rivetseeker?",a="Marvon Rivetseeker is the one who sends you for the stone. Marvon once entered the Sunken Temple and barely got out.",al={"marvon rivetseeker","who gives the stone circle quest","questgiver tanaris"}},{q="Where is the stone circle?",a="It was crated and sent on to Marvon's workshop in Ratchet.",al={"where is the stone circle","stone circle workshop","stone circle location"}},{q="Why does Marvon want the stone circle?",a="The stone carries a serpent symbol like the statues Marvon recalls from a round room in the Sunken Temple. With it in hand, Marvon may be able to say more.",al={"why find the stone circle","stone circle purpose"}},{q="What happened to Marvon in the Sunken Temple?",a="Marvon barely found the way out, wading through the ooze spread across the floors. All Marvon can recall is stumbling through a large round room filled with serpent statues.",al={"marvon sunken temple","marvon backstory"}}},kw={"marvon rivetseeker","ratchet","serpent statue","sunken temple","tanaris","stone circle"},rel={"zone:tanaris","subzone:ratchet"},m={start="Marvon Rivetseeker",["end"]="Marvon Rivetseeker",level="51",id=3444},src={"The Stone Circle"}}
E["quest:351"] = {t="quest",n="Find OOX-17/TN!",z="tanaris",s="A strange egg-shaped metal device you have uncovered springs to life when you fiddle with its knob, and a voice from inside introduces itself as Oglethorpe. Oglethorpe's homing robot has gone missing, and you are asked to carry the beacon to it.",h="A strange egg-shaped metal device you have uncovered springs to life when you fiddle with its knob, and a...",sec={{t="A Voice From the Egg",b="Fiddling with a knob on the strange egg opens it up into a gnomish robotic contraption, and a voice crackles to life from inside. The speaker gives the name Oglethorpe and says a homing robot has gone missing. Oglethorpe has now computed where it went down, near the Gaping Chasm in Tanaris, and asks you to take the beacon to the robot.",sp=0},{t="At the Crash Site",b="At the crash site, the homing robot turns out to be a robotic chicken. Oglethorpe says it must be jump started before it can fly home to Booty Bay for repairs, and the beacon goes inside it. Hums and whirs follow as the robot struggles to stand, and Oglethorpe's voice now comes from the robot itself. It works, but major repairs are needed, and it is far too heavy for you to lift.",sp=1}},faq={{q="Who is contacting you through the device?",a="A voice from inside the egg gives the name Oglethorpe and says the homing robot has gone missing.",al={"who is oglethorpe","who speaks through the egg"}},{q="Where did the homing robot crash?",a="Oglethorpe's computed coordinates put it near the Gaping Chasm in Tanaris.",al={"where is the robot","where is oox-17/tn","where do i bring the beacon","gaping chasm robot location"}},{q="What is the beacon for?",a="Oglethorpe asks you to bring the beacon to the missing homing robot.",al={"what does the beacon do","what is the egg","why carry the beacon"}}},kw={"distress beacon","gaping chasm","homing robot","mechanical chicken","oglethorpe","oox-17/tn","tanaris"},rel={"quest:648","zone:tanaris","subzone:gaping-chasm","subzone:booty-bay"},m={start="OOX-17/TN Distress Beacon",["end"]="Homing Robot OOX-17/TN",level="48",faction="Neutral",id=351},src={"Find OOX-17/TN!"}}
E["quest:3520"] = {t="quest",n="Screecher Spirits",z="tanaris",s="Yeh'kinya in Steamwheedle Port wants the spirits of the vale screechers found in Feralas, kin to an ancient god. You are sent to southern and central Feralas with a bramble wand, and Yeh'kinya promises to say more of that god on your return.",h="Yeh'kinya in Steamwheedle Port wants the spirits of the vale screechers found in Feralas, kin to an ancient...",sec={{t="Spirits of Feralas",b="Yeh'kinya says the vale screechers of Feralas are kin to an ancient god, and that their spirits are linked to him. You are given a bramble wand and sent to southern and central Feralas. Waving the bramble over a fallen vale screecher coaxes its spirit out, and touching the spirit gathers its essence. Three spirits are wanted, and Yeh'kinya expects the bramble and the essence back.",sp=0},{t="What Yeh'kinya Shares",b="Yeh'kinya names the old god as Hakkar the Soulflayer, the dead god of an ancient troll prophecy foretelling his return to the world. Opinions differ: some expect glory and joy for the trolls, others the end of everything. Yeh'kinya puts no faith in the myth, yet knows Hakkar's essence is powerful and should stay out of the wrong hands.",sp=1}},faq={{q="Who gives this quest and where are they?",a="Yeh'kinya, in Steamwheedle Port.",al={"who gives screecher spirits","yehkinya location","where is yehkinya"}},{q="Where are the vale screechers?",a="In southern and central Feralas.",al={"where to find screechers","screecher location","where are screechers in feralas"}},{q="How do you capture the screecher spirits?",a="Yeh'kinya's bramble is waved over a fallen vale screecher, which coaxes the spirit out. Touching the spirit gathers its essence.",al={"how to get screecher spirit","using yehkinyas bramble","bramble wand"}},{q="Why does Yeh'kinya want screecher spirits?",a="Yeh'kinya says the vale screechers are kin to an ancient god and that their spirits are linked to him. On your return, Yeh'kinya will tell you more of that god.",al={"why gather screecher spirits","yehkinya motive"}}},kw={"bramble wand","feralas","screecher spirits","steamwheedle port","tanaris","vale screecher","yeh'kinya"},rel={"npc:yeh-kinya","subzone:steamwheedle-port","zone:tanaris","zone:feralas"},m={start="Yeh'kinya",["end"]="Yeh'kinya",level="44",faction="Neutral",id=3520},src={"Screecher Spirits"}}
E["quest:379"] = {t="quest",n="Slake That Thirst",z="tanaris",s="Chief Engineer Bilgewhizzle in Gadgetzan can supply the 4711-FTZ power source for your kit, but first wants something to drink: five Wastewander Water Pouches, to be had from the Wastewander nomads east of town.",h="Chief Engineer Bilgewhizzle in Gadgetzan can supply the 4711-FTZ power source for your kit, but first wants...",sec={{t="A Drink for a Power Source",b="After Into the Field, you know the kit needs a power source, and Chief Engineer Bilgewhizzle in Gadgetzan can help. The price is a drink: five Wastewander Water Pouches. Bilgewhizzle points you to the Wastewander nomads east of Gadgetzan, suggests you simply walk up to one and ask, and wants to hear how that works out.",sp=0},{t="A Limit on the Power",b="Once the pouches are handed over, the power source is yours, but it was not made for a science kit. There is only so long before every bit of data you gather is lost: two hours at most. When you have what you need, bring it back to Bilgewhizzle to be shut down properly. If time runs out, another power source can be had, but it will be sold, not given.",sp=1}},faq={{q="Who asks for the water pouches?",a="Chief Engineer Bilgewhizzle in Gadgetzan, who wants five of them in return for the 4711-FTZ power source.",al={"who gives slake that thirst","bilgewhizzle quest","gadgetzan engineer water"}},{q="Where do you find the Wastewander Water Pouches?",a="From the Wastewander nomads, who are found to the east of Gadgetzan.",al={"where are wastewander water pouches","nomad water tanaris","wastewander pouches location"}},{q="What power source does Chief Engineer Bilgewhizzle offer?",a="The 4711-FTZ, the power source for your kit.",al={"what item does bilgewhizzle give","4711 ftz power source","power source name"}},{q="What came before this step?",a="It follows Into the Field.",al={"slake that thirst prerequisite","previous quest for slake that thirst","into the field connection"}}},kw={"4711-ftz","bilgewhizzle","gadgetzan","power source","tanaris","wastewander","water pouch"},rel={"quest:243","quest:841","subzone:gadgetzan","zone:tanaris"},m={start="Chief Engineer Bilgewhizzle",["end"]="Chief Engineer Bilgewhizzle",level="46",faction="Horde",id=379},src={"Slake That Thirst"}}
E["quest:4496"] = {t="quest",n="Bungle in the Jungle",z="tanaris",s="Alchemist Pestlezugg in Gadgetzan has studied the silithid and likens them to bees, with the queen as the weak point. A lure must draw her out, and it calls for a scent gland and soil from Un'Goro Crater, to the west.",h="Alchemist Pestlezugg in Gadgetzan has studied the silithid and likens them to bees, with the queen as the...",sec={{t="A Lure for the Queen",b="Pestlezugg's research compares the silithid to bees. Destroy the hive's queen, and the rest should be thrown into disarray. A lure will be brewed to bring the queen out, and once she is summoned, you are the one to take her down.",sp=0},{t="Reagents from Un'Goro",b="Before the lure can be brewed, Pestlezugg needs reagents. The silithid hive lies west in Un'Goro Crater, and a scent gland must come from one of the bugs there. The gland cannot be damaged. Pestlezugg also needs five samples of the native Un'Goro soil.",sp=0}},faq={{q="Who asks for the scent gland and soil, and where?",a="Alchemist Pestlezugg, in Gadgetzan.",al={"who gives bungle in the jungle","where is pestlezugg","bungle in the jungle questgiver"}},{q="What does Pestlezugg need for the lure?",a="One undamaged Gorishi scent gland, taken from one of the silithid bugs, and five samples of the native Un'Goro soil.",al={"bungle in the jungle items","what reagents does pestlezugg need","scent gland and soil"}},{q="Where is the silithid hive?",a="In Un'Goro Crater, to the west of Gadgetzan.",al={"where to find gorishi scent gland","where is the silithid hive","where is un'goro soil found"}},{q="Why does Pestlezugg want to bring out the hive queen?",a="Pestlezugg's research compares the silithid to bees, so with their queen gone the rest should fall into disarray.",al={"why kill the queen","pestlezugg plan","silithid bee theory"}}},kw={"gadgetzan","gorishi","pestlezugg","scent gland","silithid","tanaris","un'goro crater","un'goro soil"},rel={"quest:4507","subzone:gadgetzan","zone:ungoro","zone:tanaris"},m={start="Alchemist Pestlezugg",["end"]="Alchemist Pestlezugg",level="53",id=4496},src={"Bungle in the Jungle"}}
E["quest:4504"] = {t="quest",n="Super Sticky",z="tanaris",s="Tran'rek in Gadgetzan wants a fast profit and has a new idea: a super sticky glue. The tar for it must come from beasts in northern Un'Goro Crater, near the tar pits, and Tran'rek will share a little of the profit.",h="Tran'rek in Gadgetzan wants a fast profit and has a new idea: a super sticky glue.",sec={{t="A Sticky Idea",b="Tran'rek hopes this newest idea will bring quick gold, and offers you a little of the profit. Ordinary tar is not sticky enough. Twelve samples are wanted, taken from creatures dwelling near the tar pits of northern Un'Goro Crater.",sp=0},{t="Why the Beasts",b="The plant-like creatures around the pits have chlorophyll in their skin. Mixed with the tar, it makes a super sticky glue.",sp=0},{t="Once the Tar Arrives",b="Tran'rek handles the tar and soon finds hands stuck together. The scheme changes on the spot: a super sticky tar remover, Tran'rek decides, is where the real money is.",sp=1}},faq={{q="Who asks for the sticky tar?",a="Tran'rek, in Gadgetzan.",al={"who gives super sticky","super sticky quest giver","tran'rek quest"}},{q="Why does the tar have to come from beasts?",a="Regular tar is not sticky enough. The plant-like creatures around the tar pits have chlorophyll in their skin, which makes the tar super sticky.",al={"why beast tar","regular tar vs sticky tar","why get tar from beasts"}},{q="Where are the tar beasts?",a="By the tar pits of northern Un'Goro Crater.",al={"where is super sticky tar","tar beasts location","ungoro tar pits"}},{q="What does Tran'rek plan to do with the tar?",a="Tran'rek wants to make super sticky glue as a quick way to earn gold, and promises a little of the profit to whoever helps.",al={"tranrek goal","super sticky purpose","why does tran'rek want tar"}}},kw={"chlorophyll","gadgetzan","glue","super sticky tar","tanaris","tar pits","tran'rek","un'goro crater"},rel={"subzone:gadgetzan","zone:tanaris","zone:ungoro"},m={start="Tran'rek",["end"]="Tran'rek",level="54",faction="Neutral",id=4504},src={"Super Sticky (Classic)"}}
E["quest:4507"] = {t="quest",n="Pawn Captures Queen",z="tanaris",s="After Bungle in the Jungle, Alchemist Pestlezugg hands you the lure and sends you into the silithid hive in Un'Goro Crater. The lure is meant to rouse the Gorishi Hive Queen, whose brain Pestlezugg wants brought back to Gadgetzan for study.",h="After Bungle in the Jungle, Alchemist Pestlezugg hands you the lure and sends you into the silithid hive in...",sec={{t="The Lure and the Crystal",b="Pestlezugg gives you the lure. The hive network is thought to hold a crystal that the silithid use as a hive-wide attunement device, and the hatcheries are the best place to look. Apply the lure to that crystal and the queen should come out, though several guards will probably be with her.",sp=0},{t="The Queen's Brain",b="Pestlezugg wants the queen's brain taken and carried to Gadgetzan. Pestlezugg admits it sounds icky, yet says the brain is badly needed for study.",sp=0},{t="After the Queen Falls",b="Pestlezugg suspects the silithid may be controlled by a malign intelligence, and shudders to think what could command something so insidious. When the brain arrives, Pestlezugg calls it quite a victory, yet doubts it was the full extent of the silithid presence, saying it is too clean a resolution.",sp=1}},faq={{q="Where is the Gorishi Hive Queen?",a="She is summoned inside the silithid hive in Un'Goro Crater, using the lure on a crystal Pestlezugg expects to find in the hatcheries.",al={"gorishi queen location","where is the silithid queen","where to find gorishi queen"}},{q="What is the crystal in the hive for?",a="Pestlezugg thinks the silithid use a crystal in the hive network as a hive-wide attunement device. The lure is meant for that crystal, and the hatcheries are the place to try.",al={"hive crystal","queen lure crystal","using queen lure"}},{q="Why does Pestlezugg want the queen's brain?",a="Pestlezugg says it must be studied, and wants it brought to Gadgetzan.",al={"why gorishi brain","gorishi queen brain purpose","pestlezugg research"}},{q="What comes before this?",a="Bungle in the Jungle, in which Pestlezugg asked for a scent gland and Un'Goro soil to brew the lure.",al={"pawn captures queen prerequisites","what quest comes before pawn captures queen","previous quest"}}},kw={"brain","gadgetzan","gorishi","lure","pestlezugg","queen","silithid","tanaris","un'goro"},rel={"quest:4496","subzone:gadgetzan","zone:ungoro","zone:tanaris"},m={start="Alchemist Pestlezugg",["end"]="Alchemist Pestlezugg",level="54",id=4507},src={"Pawn Captures Queen"}}
E["quest:4508"] = {t="quest",n="Calm Before the Storm",z="tanaris",s="After the queen's fall, Alchemist Pestlezugg wants the latest findings to reach people who can act on them. You carry the Un'Goro report to Gracina Spiritmight at the Temple of the Moon in Darnassus.",h="After the queen's fall, Alchemist Pestlezugg wants the latest findings to reach people who can act on them.",sec={{t="A Report for Darnassus",b="Pestlezugg says that the findings of the day must reach hands that might do something with them, since Gadgetzan cannot manage alone. The latest report is to go to Gracina Spiritmight in Darnassus, whom Pestlezugg hopes can be found at the Temple of the Moon. She has friends among the Alliance bigwigs, and if they can be drawn in, there may be a way through this alive.",sp=0},{t="Gracina's Answer",b="Gracina calls those who will not look past their hatred of the Horde fools, and says she cannot prove the silithid threat any further short of dropping them into a hive. She is glad of the report but doubts it will help, for the Alliance ignores any threat but the Horde, and even the leaders of Darnassus disagree about what this threat is. Fandral Staghelm, she says, theorizes that the silithid are unlike the ancient peril she believes them to be. She urges you to stay committed to defeating the silithid.",sp=1}},faq={{q="Who sends you with the report?",a="Alchemist Pestlezugg, from Gadgetzan.",al={"who starts calm before the storm","quest giver calm before the storm","where does calm before the storm start"}},{q="Where must the report be delivered?",a="To Gracina Spiritmight in Darnassus, where Pestlezugg last knew her to be, at the Temple of the Moon.",al={"where do i take pestlezugg's report","where is gracina spiritmight","turn in calm before the storm"}},{q="Why does Pestlezugg send the report to Gracina Spiritmight?",a="Gadgetzan cannot do this alone. Gracina has friends who are Alliance bigwigs, and if they can be drawn in, there may be a way through this alive.",al={"why send to darnassus","why gracina spiritmight"}},{q="What comes directly before this?",a="Pawn Captures Queen, in which you were sent after the Gorishi Hive Queen.",al={"prerequisite for calm before the storm","previous quest calm before the storm"}}},kw={"darnassus","gadgetzan","gracina spiritmight","pestlezugg","silithid","tanaris","temple of the moon","un'goro report"},rel={"quest:4507","subzone:gadgetzan","zone:tanaris","zone:darnassus","subzone:temple-of-the-moon"},m={start="Alchemist Pestlezugg",["end"]="Gracina Spiritmight",level="54",faction="Alliance",id=4508},src={"Calm Before the Storm (Alliance)"}}
E["quest:4509"] = {t="quest",n="Calm Before the Storm",z="tanaris",s="After the queen's fall, Alchemist Pestlezugg wants the latest findings to reach people who can act on them. You carry Pestlezugg's report on Un'Goro to Zilzibin Drumlore in Orgrimmar.",h="After the queen's fall, Alchemist Pestlezugg wants the latest findings to reach people who can act on them.",sec={{t="A Report for Orgrimmar",b="Pestlezugg says that the findings of the day must reach hands that might do something with them, since Gadgetzan cannot manage alone. The latest report is to go to Zilzibin Drumlore in Orgrimmar, who Pestlezugg expects is still in the upper part of the Drag. Zilzibin has friends high in the Horde, and if they can be drawn in, there may be a way through this alive.",sp=0},{t="Zilzibin's Answer",b="Zilzibin calls those who will not look past their hatred of the Alliance fools, and says he cannot prove the silithid threat any further short of dropping them into a hive. He is glad of the report but doubts it will help, for the Horde ignores any threat but the Alliance. Thrall himself might act if the facts reached him, but conflicting advice presses on him from every side. Zilzibin urges you to stay committed to defeating the silithid.",sp=1}},faq={{q="Who sends you with the report?",a="Alchemist Pestlezugg, from Gadgetzan.",al={"quest giver calm before the storm","who gives calm before the storm","pestlezugg quest"}},{q="Where is Zilzibin Drumlore?",a="In Orgrimmar. Pestlezugg expects him to be up in the upper part of the Drag.",al={"zilzibin drumlore location","where is zilzibin","zilzibin drumlore orgrimmar"}},{q="Why does Pestlezugg send the report to Zilzibin Drumlore?",a="Gadgetzan cannot do this alone. Zilzibin has friends high within the Horde, and if they can be drawn in, there may be a way through this alive.",al={"why send report to orgrimmar","pestlezugg motive"}},{q="What comes directly before this?",a="Pawn Captures Queen, in which you were sent after the Gorishi Hive Queen.",al={"calm before the storm prerequisites","previous quest calm before the storm"}}},kw={"calm before the storm","drag","gadgetzan","orgrimmar","pestlezugg","silithid","tanaris","zilzibin drumlore"},rel={"quest:4507","subzone:gadgetzan","subzone:drag","zone:orgrimmar","zone:tanaris"},m={start="Alchemist Pestlezugg",["end"]="Zilzibin Drumlore",level="54",faction="Horde",id=4509},src={"Calm Before the Storm (Horde)"}}
E["quest:5801"] = {t="quest",n="Fire Plume Forged",z="tanaris",s="Krinkle Goodsteel points you to Fire Plume Ridge, a simmering volcano west in Un'Goro Crater, where the lava lake at the top is hot enough to forge the stem of a skeletal key. Afterward you carry it to Alchemist Arbington at Chillwind Point in the Western Plaguelands.",h="Krinkle Goodsteel points you to Fire Plume Ridge, a simmering volcano west in Un'Goro Crater, where the lava...",sec={{t="Fire for the Key Stem",b="Forging the stem of the key takes two bars of thorium and fierce heat. The thorium is yours to find, but Krinkle Goodsteel can help with the heat. Your gold has bought a mold, and it only needs dipping in the lava lake on top of Fire Plume Ridge. The lava does the rest, fusing thorium and bone together.",sp=0},{t="Back to Arbington",b="Krinkle Goodsteel has done their part. To finish the key, you will need to talk to Alchemist Arbington at Chillwind Point in the Western Plaguelands again. The key from the lava is still unfinished, and the work so far is preparation for an assault.",sp=0},{t="What Lies Ahead",b="Arbington calls the key quite costly, but says it is still unfinished. The foe all this work has been aimed at is in Andorhal: Araj the Summoner, a lich who ranks among the most powerful of the Scourge.",sp=1}},faq={{q="Where is the key stem forged?",a="At the lava lake on top of Fire Plume Ridge, a simmering volcano in Un'Goro Crater, west of Krinkle Goodsteel.",al={"where to forge key","fire plume forged location","lava lake location"}},{q="What is needed to forge the key stem?",a="The skeleton key mold and two bars of thorium. The thorium is for you to find.",al={"what do i need","key materials","thorium requirement"}},{q="Who receives the unfinished key?",a="Alchemist Arbington, at Chillwind Point in the Western Plaguelands.",al={"who do i turn this in to","arbington location","where does unfinished key go"}}},kw={"alchemist arbington","chillwind point","fire plume ridge","krinkle goodsteel","skeleton key mold","thorium","un'goro crater","unfinished skeleton key"},rel={"subzone:fire-plume-ridge","zone:ungoro","subzone:chillwind-point","zone:westernplaguelands","zone:tanaris"},m={start="Krinkle Goodsteel",["end"]="Alchemist Arbington",level="57",faction="Alliance",id=5801},src={"Fire Plume Forged (Alliance)"}}
E["quest:5802"] = {t="quest",n="Fire Plume Forged",z="tanaris",s="Krinkle Goodsteel points you to Fire Plume Ridge, a simmering volcano west in Un'Goro Crater, where the lava lake at the top is hot enough to forge the stem of a skeletal key. Afterward you carry it to Apothecary Dithers at the Bulwark in the Western Plaguelands.",h="Krinkle Goodsteel points you to Fire Plume Ridge, a simmering volcano west in Un'Goro Crater, where the lava...",sec={{t="Fire for the Key Stem",b="Forging the stem of the key takes two bars of thorium and fierce heat. The thorium is yours to find, but Krinkle Goodsteel can help with the heat. Your gold has bought a mold, and it only needs dipping in the lava lake on top of Fire Plume Ridge. The lava does the rest, fusing thorium and bone together.",sp=0},{t="Back to Dithers",b="Krinkle Goodsteel has done their part. To finish the key, you will need to talk to Apothecary Dithers at the Bulwark in the Western Plaguelands again. The key from the lava is still unfinished, and the work so far is preparation for an assault.",sp=0},{t="What Lies Ahead",b="Dithers calls the key quite costly, but says it is still unfinished. The foe all this work has been aimed at is in Andorhal: Araj the Summoner, a lich who ranks among the most powerful of the Scourge.",sp=1}},faq={{q="Where is the key stem forged?",a="At the lava lake on top of Fire Plume Ridge, a simmering volcano in Un'Goro Crater, west of Krinkle Goodsteel.",al={"where to forge key","lava lake location","fire plume ridge lava"}},{q="What is needed to forge the key stem?",a="The skeleton key mold and two bars of thorium. The thorium is for you to find.",al={"what do i need","key materials","thorium needed"}},{q="Who receives the unfinished key?",a="Apothecary Dithers, at the Bulwark in the Western Plaguelands.",al={"who to turn in to","where does the key go","hand in key"}}},kw={"andorhal","apothecary dithers","bulwark","fire plume ridge","krinkle goodsteel","skeleton key mold","thorium bar","un'goro crater","unfinished skeleton key"},rel={"subzone:fire-plume-ridge","zone:ungoro","subzone:bulwark","zone:westernplaguelands","zone:tanaris"},m={start="Krinkle Goodsteel",["end"]="Apothecary Dithers",level="57",faction="Horde",id=5802},src={"Fire Plume Forged (Horde)"}}
E["quest:5863"] = {t="quest",n="The Dunemaul Compound",z="tanaris",s="Andi Lynn in Gadgetzan warns of a large band of nomadic ogres that has lately arrived in Tanaris. South of town they have formed a compound, and Andi Lynn wants it destroyed before they can build up a force.",h="Andi Lynn in Gadgetzan warns of a large band of nomadic ogres that has lately arrived in Tanaris.",sec={{t="Ogres in the Desert",b="A large band of nomadic ogres has arrived in Tanaris of late. South of Gadgetzan they have seized a broad stretch of desert and formed the Dunemaul Compound. Several smaller bands wander the desert as well, and some have invaded the old troll ruins. Andi Lynn says the ogres cannot be allowed to build up a force.",sp=0},{t="Cutting Off the Head",b="Andi Lynn wants ten Dunemaul Brutes and ten Dunemaul Enforcers cut down. The leader of the band is Gor'marok the Ravager, and Andi Lynn believes that once he no longer commands, the ogres will begin to crumble.",sp=0}},faq={{q="Who asks for the Dunemaul Compound to be destroyed?",a="Andi Lynn, in Gadgetzan.",al={"andi lynn","who gives the quest","quest giver"}},{q="Where is the Dunemaul Compound?",a="South of Gadgetzan, in a large area of the desert the ogres have taken over.",al={"dunemaul compound location","where are the ogres","dunemaul location"}},{q="Who leads the Dunemaul ogres?",a="Gor'marok the Ravager leads the band. Andi Lynn believes the ogres will start to fall once he is gone from command.",al={"ogre leader","who is gormarok","gor'marok the ravager"}},{q="Why does Andi Lynn see the ogres as a danger?",a="Andi Lynn says the ogres cannot be allowed to build up a force. A large band holds a compound south of town, and smaller bands roam the desert, some of them in the old troll ruins.",al={"why kill the ogres","ogre danger tanaris"}}},kw={"andi lynn","dunemaul","dunemaul brute","dunemaul compound","dunemaul enforcer","gadgetzan","gor'marok the ravager","ogres","tanaris"},rel={"subzone:dunemaul-compound","subzone:gadgetzan","zone:tanaris"},m={start="Andi Lynn",["end"]="Andi Lynn",level="49",id=5863},src={"The Dunemaul Compound"}}
E["quest:648"] = {t="quest",n="Rescue OOX-17/TN!",z="tanaris",s="The damaged homing robot OOX-17/TN speaks with Oglethorpe's voice. It needs an open, safe place for a lengthy take-off, and you are asked to see it safely to Steamwheedle Port, and then to find Oglethorpe Obnoticus in Booty Bay.",h="The damaged homing robot OOX-17/TN speaks with Oglethorpe's voice.",sec={{t="An Escort to the Port",b="Oglethorpe's voice crackles from the robot once more. The robot has built-in cloaking, but Oglethorpe needs time to make it operational again, so it must reach an open, safe place where its lengthy take-off procedure can begin. Steamwheedle Port is the spot Oglethorpe has in mind, and the trip gives the time needed to get things working. Your part is to escort the robot there safely.",sp=0},{t="Report in Booty Bay",b="Once the robot is safely at the port, you are asked to look for Oglethorpe Obnoticus, a master inventor, in Booty Bay.",sp=0},{t="A Grateful Inventor",b="Oglethorpe greets you as the one who saved OOX-17/TN. The homing robot series still needs more development, but getting this one back has saved countless hours of rebuilding and a great many gold pieces in rebinding costs. Oglethorpe says both the robots and the inventor are in your debt.",sp=1}},faq={{q="Where does the robot need to be escorted?",a="To Steamwheedle Port, where it can safely begin its take-off.",al={"where does oox-17 go","oox-17 escort path","robot destination"}},{q="Who is speaking through the robot?",a="Oglethorpe Obnoticus, a gnome and master inventor, whose homing robot this is. You find the inventor in Booty Bay.",al={"who made oox-17","oox-17 creator","who is speaking through the robot"}},{q="Why does the robot need to be moved?",a="It needs an open, safe place to begin a lengthy take-off. Its built-in cloaking also needs time to be made operational again.",al={"why move oox-17","why steamwheedle port"}},{q="Where do you report after the escort?",a="Oglethorpe Obnoticus waits in Booty Bay.",al={"where is oglethorpe obnoticus","who do i turn this in to","oox-17 turn in location"}}},kw={"booty bay","homing robot","mechanical chicken","oglethorpe obnoticus","oox-17/tn","steamwheedle port","tanaris"},rel={"quest:351","zone:tanaris","subzone:booty-bay","subzone:steamwheedle-port","topic:gnome"},m={start="Homing Robot OOX-17/TN",["end"]="Oglethorpe Obnoticus",level="48",faction="Neutral",id=648},src={"Rescue OOX-17/TN!"}}
E["quest:654"] = {t="quest",n="Tanaris Field Sampling",z="tanaris",s="Switching on the power source sets the field testing kit glowing and vibrating. You now have two hours to gather what the Tanaris desert can give, or the data is lost.",h="Switching on the power source sets the field testing kit glowing and vibrating.",sec={{t="A Ticking Power Source",b="With the power source running, the kit glows and vibrates, so it seems to be working as planned. Chief Engineer Bilgewhizzle has said you have two hours to gather your data in the Tanaris desert: acceptable samples from eight basilisks, eight hyenas and eight scorpions. If time runs out, all of it is lost and another power source must be bought from Bilgewhizzle. The kit is meant to go back to Bilgewhizzle in Gadgetzan before the power runs out.",sp=0},{t="The Company's Profit",b="Bilgewhizzle offers no sympathy to anyone whose kit goes dead. All that matters is that the Gadgetzan Water Company makes a profit. Bilgewhizzle is willing to keep selling power sources until the company can afford to import water from the icy springs of Dun Morogh.",sp=0}},faq={{q="What creatures need to be sampled for the testing kit?",a="Acceptable samples from eight basilisks, eight hyenas and eight scorpions of the Tanaris desert.",al={"what animals to test","sampling targets","what do i kill"}},{q="How much time is available to complete the sampling?",a="Two hours from the moment the power source is switched on.",al={"time limit","how long do i have","timer"}},{q="What happens if the power source runs out?",a="Everything in the kit is ruined, and another power source must be bought from Chief Engineer Bilgewhizzle in Gadgetzan to start again.",al={"if timer runs out","failed quest","power ran out"}},{q="Where does the testing kit go once full?",a="To Chief Engineer Bilgewhizzle in Gadgetzan, ahead of the power giving out.",al={"who do i turn this in to","turn in location","where is bilgewhizzle"}},{q="Why does Bilgewhizzle keep selling power sources?",a="Bilgewhizzle wants the Gadgetzan Water Company to turn a profit, even if that means selling power sources until the company can afford to import water from the icy springs of Dun Morogh.",al={"bilgewhizzle goal","gadgetzan water company goal","why sample"}}},kw={"basilisk","bilgewhizzle","field testing kit","gadgetzan","hyena","power source","scorpion","tanaris","water company"},rel={"subzone:gadgetzan","zone:tanaris","quest:379","quest:841","zone:dunmorogh"},m={start="Model 4711-FTZ Power Source",["end"]="Chief Engineer Bilgewhizzle",level="46",faction="Horde",id=654},src={"Tanaris Field Sampling"}}
E["quest:82"] = {t="quest",n="Noxious Lair Investigation",z="tanaris",s="Senior Surveyor Fizzledowser wants to know who the enemy is. Bugs have been draining the pools of water that lay where the Noxious Lair now stands, and little else is known about them. You are asked to take five insect parts from the Centipaar in the lair and bring them to Alchemist Pestlezugg in Gadgetzan.",h="Senior Surveyor Fizzledowser wants to know who the enemy is.",sec={{t="Parts From the Lair",b="After the Gadgetzan Water Survey, Senior Surveyor Fizzledowser turns to the reports about the bugs. Little is known except that they are draining the pools that once lay where the Noxious Lair now is. Fizzledowser wants to learn who the enemy is first, and asks you to go into the lair, take five parts from the Centipaar found there, and carry them back to Gadgetzan, to the alchemist Pestlezugg, to be examined.",sp=0},{t="What Pestlezugg Finds",b="Pestlezugg starts on the parts at once and says right away that they match no insect form seen before, almost as if an outside force were controlling the bugs. Pestlezugg then sends you back to Fizzledowser, for an emergency needs your help, one that may involve more of the bugs in Tanaris.",sp=1}},faq={{q="Why does Senior Surveyor Fizzledowser want insect parts?",a="Bugs are draining the water pools that once lay where the Noxious Lair is, and little else about them is known. Parts from the Centipaar are meant to help Pestlezugg work out what they are.",al={"why collect bug parts","fizzledowser insect parts","noxious lair purpose"}},{q="Where are the Centipaar found?",a="The Centipaar are in the Noxious Lair, where water pools used to be.",al={"where is noxious lair","centipaar location","where to find centipaar"}},{q="Who receives the insect parts in Gadgetzan?",a="Alchemist Pestlezugg in Gadgetzan, who is to examine them.",al={"who to turn in to","pestlezugg location","who wants the bug parts"}},{q="What comes before this step?",a="It follows the Gadgetzan Water Survey.",al={"previous quest","prerequisite quest","what leads to this"}}},kw={"centipaar","fizzledowser","gadgetzan","insects","noxious lair","pestlezugg","tanaris"},rel={"subzone:noxious-lair","npc:senior-surveyor-fizzledowser","subzone:gadgetzan","zone:tanaris","quest:992","quest:10"},m={start="Senior Surveyor Fizzledowser",["end"]="Alchemist Pestlezugg",level="47",id=82},src={"Noxious Lair Investigation"}}
E["quest:841"] = {t="quest",n="Another Power Source?",z="tanaris",s="Chief Engineer Bilgewhizzle in Gadgetzan has more power sources and will sell you another one, at a price of ten Wastewander Water Pouches.",h="Chief Engineer Bilgewhizzle in Gadgetzan has more power sources and will sell you another one, at a price of...",sec={{t="A Costly Replacement",b="Chief Engineer Bilgewhizzle guesses the first power source from Slake That Thirst ran out of time, or perhaps got lost in the sand. Whatever the reason, Bilgewhizzle has additional power sources to sell. This time the price is ten Wastewander Water Pouches, because times are tough all around and power sources do not grow on trees.",sp=0}},faq={{q="Why does Chief Engineer Bilgewhizzle want Wastewander water pouches?",a="Bilgewhizzle sells another power source for ten Wastewander Water Pouches, saying times are tough all around.",al={"bilgewhizzle water pouches","why water pouches"}},{q="Who offers this exchange?",a="Chief Engineer Bilgewhizzle, who has additional power sources to sell.",al={"who starts another power source","power source quest giver"}},{q="What happened prior to needing another power source?",a="It follows Slake That Thirst, where you first obtained a power source for your kit.",al={"prereq another power source","previous quest power source"}}},kw={"bilgewhizzle","gadgetzan","power source","tanaris","wastewander","water pouches"},rel={"quest:379","subzone:gadgetzan","zone:tanaris"},m={start="Chief Engineer Bilgewhizzle",["end"]="Chief Engineer Bilgewhizzle",level="46",faction="Horde",id=841},src={"Another Power Source?"}}
E["quest:8555"] = {t="quest",n="The Charge of the Dragonflights",z="tanaris",s="Anachronos, of the bronze dragonflight, meets you in Tanaris to wrap up the first part of the Scepter of the Shifting Sands. That chain is the road toward opening the Gates of Ahn'Qiraj.",h="Anachronos, of the bronze dragonflight, meets you in Tanaris to wrap up the first part of the Scepter of the...",sec={{t="The End of the Beginning",b="This meeting wraps up the opening stretch of the Scepter of the Shifting Sands, the chain that leads toward opening the Gates of Ahn'Qiraj. Anachronos is the one who closes this first part with you.",sp=0},{t="The Three Watchers",b="Anachronos names three dragons, Eranikus, Vaelastrasz and Azuregos, who have played influential roles as watchers of the world. Each of these guardians, Anachronos says, has fallen to tragedy, whether through agents of the Old Gods or through betrayal by those who called them friend. Anachronos admits to being partly to blame through naivety, and says the whole matter has fueled a distrust of mortals. You are told to seek the three out and prepare for the worst.",sp=1}},faq={{q="Who is Anachronos?",a="Anachronos is a dragon of the bronze dragonflight, met here in Tanaris.",al={"who is anachronos","anachronos tanaris","bronze dragon"}},{q="What is the Scepter of the Shifting Sands?",a="It is the long chain that leads toward opening the Gates of Ahn'Qiraj. This meeting wraps up its first part.",al={"scepter chain","scepter of the shifting sands","gates of ahn'qiraj chain"}}},kw={"anachronos","azuregos","eranikus","gates of ahn'qiraj","scepter of the shifting sands","tanaris","vaelastrasz"},rel={"npc:azuregos","zone:tanaris"},m={start="Anachronos",["end"]="Anachronos",level="60",id=8555},src={"The Charge of the Dragonflights"}}
E["quest:8576"] = {t="quest",n="Translating the Ledger",z="tanaris",s="You bring Azuregos's ledger to Narain Soothfancy, who must work out what is written in it. It is a step on the road toward opening the Gates of Ahn'Qiraj.",h="You bring Azuregos's ledger to Narain Soothfancy, who must work out what is written in it.",sec={{t="The Ledger Comes to Narain",b="You take Azuregos's ledger to Narain Soothfancy. Someone has to work out what Azuregos wrote in it, and that falls to Narain.",sp=0},{t="What Narain Makes of It",b="Narain hears that Azuregos has set you to building an arcanite buoy, and that the ledger holds the schematic. Narain finds it odd that Azuregos wrote it in Draconic, which Narain cannot read. To make it work, Narain will need the scrying goggles, a chicken of five hundred pounds and the second volume of Draconic for Dummies, in whatever order.",sp=1}},faq={{q="Whose ledger is it?",a="It is Azuregos's ledger. Narain Soothfancy is the one you bring it to.",al={"whose ledger","azuregos ledger","who wrote the ledger"}},{q="Who reads the ledger?",a="Narain Soothfancy, who has to work out what Azuregos wrote in it.",al={"who translates the ledger","narain soothfancy","where to take the ledger"}}},kw={"arcanite buoy","azuregos","draconic","ledger","narain soothfancy","tanaris"},rel={"npc:narain-soothfancy","zone:tanaris"},m={start="Narain Soothfancy",["end"]="Narain Soothfancy",level="60",id=8576},src={"Translating the Ledger"}}
E["quest:8577"] = {t="quest",n="Stewvul, Ex-B.F.F.",z="tanaris",s="After Translating the Ledger, Narain Soothfancy says nothing can be translated without the scrying goggles. Narain's ex-best friend forever, Stewvul, stole them, and you are to find Stewvul and take them back.",h="After Translating the Ledger, Narain Soothfancy says nothing can be translated without the scrying goggles.",sec={{t="The Stolen Goggles",b="Narain Soothfancy needs the scrying goggles before translating anything. They were stolen a while back by Stewvul, Narain's ex-best friend forever, who broke Narain's heart in five places and then abandoned Narain in this place.",sp=0},{t="Where to Look",b="With the help of a trusty crystal ball, Narain has narrowed Stewvul's whereabouts to two places. One is the Greymane Wall in Silverpine. The other is a world beyond a portal. You are the one to track Stewvul down and get the goggles back.",sp=0},{t="What Stewvul Says",b="Stewvul cannot believe Narain has found them. Stewvul will not go back, and is finished with being a friend only part of the time and a slave the rest.",sp=1}},faq={{q="Why does Narain need the scrying goggles?",a="Narain says nothing can be translated without them.",al={"why need goggles","narain goggles purpose","scrying goggles use"}},{q="Who is Stewvul?",a="Stewvul is Narain Soothfancy's ex-best friend forever. Stewvul stole the scrying goggles, broke Narain's heart in five places and then abandoned Narain here.",al={"who is stewvul","stewvul lore","narain friend"}},{q="Where does Narain think Stewvul is?",a="Narain's crystal ball narrows it to two places: the Greymane Wall in Silverpine, or a distant portal world.",al={"where is stewvul","stewvul locations","greymane wall"}},{q="What comes before this?",a="Translating the Ledger, where you brought Azuregos's ledger to Narain.",al={"previous quest","prereq","what leads to this"}}},kw={"greymane wall","inconspicuous crate","ledger","narain soothfancy","scrying goggles","silverpine","stewvul","tanaris"},rel={"npc:narain-soothfancy","quest:8576","subzone:greymane-wall","zone:tanaris"},m={start="Narain Soothfancy",["end"]="Inconspicuous Crate",level="60",id=8577},src={"Stewvul, Ex-B.F.F."}}
E["quest:8584"] = {t="quest",n="Never Ask Me About My Business",z="tanaris",s="Narain Soothfancy has a plan he refuses to explain, and it calls for a chicken of five hundred pounds. You head for Gadgetzan to speak with Dirge Quikcleave, who can get you started on finding a fitting bird.",h="Narain Soothfancy has a plan he refuses to explain, and it calls for a chicken of five hundred pounds.",sec={{t="Planning and Fetching",b="Narain Soothfancy wants no more questions about his business, which deals in things you could never hope to grasp. The planning is his and the fetching is yours. As he said before, the plan needs a chicken of five hundred pounds, and Dirge Quikcleave in the Gadgetzan inn can point you toward one.",sp=0},{t="Dirge's Answer",b="Dirge Quikcleave scratches his head. A chicken of that weight is no longer to be found, he says, though he once knew of one, the Black Chicken of Death, and nobody who saw that bird lived to tell of it. Then he says he has an idea that could be good for you both.",sp=1}},faq={{q="Why does Narain Soothfancy need a five-hundred-pound chicken?",a="Narain will not say. His business involves things you could not understand, such as a psychotronic muzzledorf, and he leaves the planning to himself and the fetching to you.",al={"why 500 pound chicken","narain chicken business","why does narain want a chicken"}},{q="Who do you need to talk to in Gadgetzan?",a="Narain sends you to Dirge Quikcleave, found in the Gadgetzan inn, who will start you on finding a suitable chicken.",al={"where to go","who to see in gadgetzan","where is dirge quikcleave"}},{q="What comes before this quest?",a="Translating the Ledger comes first. Narain Soothfancy raises the matter of the chicken after that.",al={"prerequisite quest","what quest comes first","prior step"}},{q="Where is Narain Soothfancy located?",a="Narain Soothfancy is in Tanaris.",al={"where is narain","narain location","narain soothfancy tanaris location"}}},kw={"500 pound chicken","black chicken of death","dirge quikcleave","gadgetzan","narain soothfancy","tanaris"},rel={"npc:narain-soothfancy","npc:dirge-quikcleave","quest:8576","subzone:gadgetzan","zone:tanaris"},m={start="Narain Soothfancy",["end"]="Dirge Quikcleave",level="60",id=8584},src={"Never Ask Me About My Business"}}
E["quest:8586"] = {t="quest",n="Dirge's Kickin' Chimaerok Chops",z="tanaris",s="Dirge Quikcleave in Gadgetzan has finished working out his recipe. He still needs twenty Goblin Rocket Fuel and twenty Deeprock Salt from you, and he wants them fast so the meat you brought him does not spoil.",h="Dirge Quikcleave in Gadgetzan has finished working out his recipe.",sec={{t="What Dirge Still Needs",b="Dirge Quikcleave sees to the spices himself, and the meat you brought him makes up the remainder of the dish. All he lacks is rocket fuel and deeprock salt, twenty of each. With those in his hands, the chicken will be ready to go back to Narain Soothfancy. Dirge urges you not to dawdle, because he does not want the meat going bad.",sp=0}},faq={{q="Who asks for these supplies?",a="Dirge Quikcleave in Gadgetzan asks for them, to finish his recipe.",al={"who starts this quest","who gives dirge's kickin chimaerok chops","dirge quikcleave quest"}},{q="What ingredients does Dirge Quikcleave need?",a="Dirge wants twenty Goblin Rocket Fuel and twenty Deeprock Salt. The spices are his own job, and the meat you gave him covers the rest.",al={"what items do i need","ingredients for dirge chops","dirges chops items"}},{q="Who is the finished dish intended for?",a="Dirge says that once you bring him what he asked for, the bird is ready to be carried back to Narain Soothfancy.",al={"who eats the chops","who gets the chicken","who is the food for"}},{q="What comes after delivering these ingredients?",a="Return to Narain is the next step.",al={"next quest","what do i do after dirge chops","what follows this quest"}}},kw={"chimaerok","chops","deeprock salt","dirge","gadgetzan","narain","quikcleave","rocket fuel"},rel={"npc:dirge-quikcleave","npc:narain-soothfancy","quest:8587","subzone:gadgetzan","zone:tanaris"},m={start="Dirge Quikcleave",["end"]="Dirge Quikcleave",level="60",id=8586},src={"Dirge's Kickin' Chimaerok Chops (quest)"}}
E["quest:8587"] = {t="quest",n="Return to Narain",z="tanaris",s="Dirge Quikcleave keeps his word and hands over the five-hundred-pound chicken. You carry it to Narain Soothfancy in Tanaris. This comes after Dirge's Kickin' Chimaerok Chops.",h="Dirge Quikcleave keeps his word and hands over the five-hundred-pound chicken.",sec={{t="A Bargain Kept",b="Dirge Quikcleave gives you the chicken he promised, saying he is a goblin of his word. He cannot imagine what a gnome would want with a bird that large, and grumbles that it must be to sleep in. From here you take it to Narain Soothfancy in Tanaris.",sp=0},{t="Narain's Welcome",b="The scent of the chicken draws Narain Soothfancy's notice. He mashes both fists into the bird and stuffs his face with Dirge's cooking, declaring it the best chicken he has ever had.",sp=1}},faq={{q="What came before this delivery?",a="Dirge's Kickin' Chimaerok Chops comes first, where Dirge Quikcleave asked for the rocket fuel and salt to finish his recipe.",al={"previous quest","what did i do before this","prerequisite"}},{q="Who receives the massive chicken?",a="Narain Soothfancy, in Tanaris.",al={"who gets the chicken","who do i take this to","turn in location"}},{q="Why did Dirge prepare a five-hundred-pound chicken?",a="Dirge is keeping his word by handing the chicken over. He says he will never know what a gnome wants with a bird that size.",al={"why 500 pound chicken","what is the chicken for","dirge chicken"}},{q="What comes after delivering the chicken?",a="The Good News and The Bad News follows, though Narain only offers it once two other parts of the work, Narain's Scrying Goggles and Draconic For Dummies: Volume II, are also finished.",al={"next quest","what follows this","where to next"}}},kw={"500 pound chicken","chimaerok","dirge quikcleave","narain soothfancy","tanaris"},rel={"npc:narain-soothfancy","npc:dirge-quikcleave","zone:tanaris","quest:8586","quest:8728","topic:gnome","topic:goblin"},m={start="Dirge Quikcleave",["end"]="Narain Soothfancy",level="60",id=8587},src={"Return to Narain"}}
E["quest:8597"] = {t="quest",n="Draconic for Dummies",z="tanaris",s="Narain Soothfancy remembers a book he stowed somewhere safe. To reach it you look for his crashed gyrocopter on Land's End Beach, then swim south from there to an island in the South Seas. This follows Translating the Ledger.",h="Narain Soothfancy remembers a book he stowed somewhere safe.",sec={{t="A Book Stowed Away",b="Narain Soothfancy says the book is bound to come in handy, and that he hid it where nobody could hope to find it. He needed a gyrocopter to get there the first time and crashed it on the beach on the way back. That crash, he says, gave him his super-gnomish psychic powers. The wreck lies somewhere along Land's End Beach, and from there you swim south. Narain is sure you will recognise the place at a glance. The island where the book lies buried is out in the South Seas.",sp=0},{t="At the Island",b="On the island you find a mound of dirt, and the book is gone. A note lies on top of the mound in its place.",sp=1}},faq={{q="Who sends you to find this book?",a="Narain Soothfancy sends you after the book, once you have finished Translating the Ledger for him.",al={"who gives draconic for dummies","narain quest starter","who gives this quest"}},{q="Where did Narain crash his gyrocopter?",a="Narain says he crashed it on a beach on his way back from hiding the book. You will find the wreck somewhere on Land's End Beach.",al={"where is the gyrocopter","crashed gyrocopter location","lands end beach crash"}},{q="Where is the book supposed to be hidden?",a="Narain Soothfancy says it lies buried on an island out in the South Seas. You swim south from the wreck on Land's End Beach, and he says the spot will be plain when you see it.",al={"book location","where is the island","where to swim"}},{q="How did Narain get his psychic powers?",a="Narain says the gyrocopter crash on the beach gave him his psychic powers.",al={"narain psychic powers","how did narain become psychic"}}},kw={"draconic for dummies","freshly dug dirt","gyrocopter","land's end beach","narain soothfancy","south seas","tanaris"},rel={"npc:narain-soothfancy","quest:8576","subzone:land-s-end-beach","subzone:south-seas","zone:tanaris","quest:8598","quest:8599"},m={start="Narain Soothfancy",["end"]="Freshly Dug Dirt",level="60",id=8597},src={"Draconic for Dummies (quest)"}}
E["quest:8598"] = {t="quest",n="rAnS0m",z="tanaris",s="At the freshly dug dirt where Narain Soothfancy's book should lie, a ransom note has been left in its place. You carry the letter back to Narain Soothfancy in Tanaris. This follows Draconic for Dummies.",h="At the freshly dug dirt where Narain Soothfancy's book should lie, a ransom note has been left in its place.",sec={{t="A Note Made of Scraps",b="The note is made up of many different typefaces glued onto parchment. It tells Narain, calling him a gnome, that his precious book is in the writers' hands and that he will see it again only by doing exactly as told. Detailed instructions fill three pages, closing with a demand to bring the money and come alone. You take the letter to Narain Soothfancy in Tanaris.",sp=0},{t="Narain's Answer",b="Narain Soothfancy asks what the matter is, then reads the letter and his face glows bright red. He is outraged that anyone would snatch his book, and vows to show the culprits what it means to cross a psychic gnome.",sp=1}},faq={{q="What is the ransom note demanding?",a="The writers claim to have Narain's book, and he will see it again only if he does exactly as they ask. The instructions run three pages and end with a demand for money and for him to come alone. The note does not say who wrote it.",al={"what does the note say","ransom letter text","who took the book"}},{q="Where does this step lead next?",a="Once the letter is with Narain Soothfancy in Tanaris, the chain carries on with Decoy!",al={"what comes after ransom","ransom follow up","next quest after ransom"}},{q="What came before finding the ransom note?",a="Draconic for Dummies comes before it, the search for Narain's buried book that ends at the freshly dug dirt.",al={"previous quest","prereq for ransom"}}},kw={"draconic for dummies","freshly dug dirt","narain soothfancy","ransom","ransom letter","tanaris"},rel={"npc:narain-soothfancy","quest:8606","zone:tanaris","topic:gnome"},m={start="Freshly Dug Dirt",["end"]="Narain Soothfancy",level="60",id=8598},src={"RAnS0m"}}
E["quest:8599"] = {t="quest",n="Love Song for Narain",z="tanaris",s="Meridith the Mermaiden has a message for Narain Soothfancy, the gnome she once rescued from the wreckage of a crashed flying machine. She asks you to carry her love letter to him in Tanaris. You can take this up while seeking Narain's book in Draconic for Dummies.",h="Meridith the Mermaiden has a message for Narain Soothfancy, the gnome she once rescued from the wreckage of a...",sec={{t="A Message for the Shore",b="Meridith the Mermaiden seldom has visitors. The last was the gnome she rescued from the wreckage of a crashed flying machine, and she gazes into nothing for a moment, lost in the memory. She asks whether you know Narain Soothfancy, because she has to tell him how she feels, and she is sure it is love. She begs you to carry a message to him, and promises to be forever in your debt.",sp=0},{t="Narain's Answer",b="Narain Soothfancy remarks that you smell of fish. When he learns what the letter says, he fidgets and protests that she is a fish and he is a gnome, so it could never work out.",sp=1}},faq={{q="Who is Meridith?",a="Meridith is a mermaiden who seldom has visitors. The last was the gnome she rescued from a crashed flying machine, Narain Soothfancy.",al={"who is meridith","meridith the mermaiden","mermaiden lore"}},{q="How does Meridith know Narain Soothfancy?",a="She rescued him from the wreckage of his crashed flying machine, and she believes she is in love with him.",al={"how did meridith meet narain","narain and meridith relationship","narain plane crash"}},{q="What is the love letter?",a="It is Meridith's message to Narain Soothfancy, telling him how she feels. She wants it delivered to him in Tanaris.",al={"meridith's love letter","love letter to narain","what is in the message"}},{q="What came before this request?",a="Draconic for Dummies comes before it. Meridith offers her request to those already seeking Narain's buried book.",al={"previous quest","prerequisite for love song for narain"}}},kw={"flying machine","love letter","meridith","mermaiden","narain soothfancy","tanaris","wreckage"},rel={"npc:narain-soothfancy","quest:8597","zone:tanaris","topic:gnome"},m={start="Meridith the Mermaiden",["end"]="Narain Soothfancy",level="60",id=8599},src={"Love Song for Narain"}}
E["quest:8606"] = {t="quest",n="Decoy!",z="tanaris",s="Narain Soothfancy has a plan for the ransom: a sack of rocks in place of money, and you in place of him. You carry his disguise to the handover spot the booknappers set down in Winterspring. This follows the ransom letter.",h="Narain Soothfancy has a plan for the ransom: a sack of rocks in place of money, and you in place of him.",sec={{t="Narain's Scheme",b="The ransom note said Narain should make the delivery himself, and he means to, after a fashion. He fills a sack with rocks, looks you up and down, and decides you will do. His special kit holds a turban, a robe and the sack, and you carry it to the handover spot the booknappers set down in Winterspring. When the booknappers show up for the goods, Narain wants them snuffed out, as a lesson in what comes of crossing him.",sp=0},{t="Narain's Verdict",b="When you return, Narain admits that he and you may have underestimated these booknappers.",sp=1}},faq={{q="Why does Narain want you to wear a disguise?",a="The ransom note said Narain should make the delivery himself. His plan is to send you in his place, with the turban and robe from his special kit.",al={"why wear the turban","why the disguise","why dress like narain"}},{q="Where does the handover take place?",a="At the handover spot in Winterspring that the booknappers set down, where the sack of rocks is to be left.",al={"where is the drop","where do i take the bag","drop off point location"}},{q="What is inside the ransom bag?",a="Narain fills the sack with rocks rather than money.",al={"what is in the bag","is it real gold","what did narain pack"}},{q="What came before this quest?",a="The ransom letter came before, the note demanding money for Narain's stolen book that you carried back to him.",al={"prerequisite quest","previous quest","what led to this"}}},kw={"booknappers","decoy","narain soothfancy","number two","ransom","winterspring"},rel={"npc:narain-soothfancy","zone:winterspring","zone:tanaris"},m={start="Narain Soothfancy",["end"]="Narain Soothfancy",level="60",id=8606},src={"Decoy!"}}
E["quest:8728"] = {t="quest",n="The Good News and The Bad News",z="tanaris",s="Narain Soothfancy has read through the ledger and has both good news and bad. He is nearly certain he can build an arcanite buoy to your specifications, but he needs a great deal of arcanite, elementium ore and fine gems. This comes once the chicken, the goggles and the second Draconic For Dummies book are all done.",h="Narain Soothfancy has read through the ledger and has both good news and bad.",sec={{t="Good News, Bad News",b="Narain Soothfancy reads the ledger in silence, mumbling under his breath. He is ninety-nine percent sure he can make an arcanite buoy that will work as you specified, but says all of that depends on the bad news. For the buoy he wants twenty arcanite bars, ten elementium ore, ten Azerothian diamonds and ten blue sapphires. Bring them, and he will craft it.",sp=0},{t="Narain's Warning",b="When you bring everything, Narain says a deal is a deal. He hopes you know what you are getting into, since in his view it is a great deal of bother just to go fishing.",sp=1}},faq={{q="Who offers this quest?",a="Narain Soothfancy in Tanaris. He offers it only after the chicken, the Scrying Goggles and the second Draconic For Dummies parts of the work are all complete.",al={"quest giver","narain soothfancy location","where is narain"}},{q="What materials does Narain require?",a="Narain wants twenty arcanite bars, ten elementium ore, ten Azerothian diamonds and ten blue sapphires.",al={"required items","mats needed","what materials do i need"}},{q="What is Narain building with these materials?",a="An arcanite buoy. He is ninety-nine percent sure he can make one that works to the specifications you gave him.",al={"what is narain making","why arcanite buoy","what is the buoy for"}},{q="What comes before this step?",a="Return to Narain comes before it. Narain also expects the goggles and the second Draconic For Dummies parts of the work to be finished.",al={"previous quest","prerequisites","what leads to this"}}},kw={"arcanite bar","arcanite buoy","azerothian diamond","blue sapphire","elementium","narain soothfancy","tanaris"},rel={"npc:narain-soothfancy","quest:8587","zone:tanaris","quest:8597"},m={start="Narain Soothfancy",["end"]="Narain Soothfancy",level="60",id=8728},src={"The Good News and The Bad News"}}
E["quest:8742"] = {t="quest",n="The Might of Kalimdor",z="tanaris",s="Anachronos greets you as the one fate has been waiting a thousand years to bring forward, a champion to lead their people into a new age. This opens the end of the Scepter of the Shifting Sands, and comes only after the Blue, Green and Red Scepter Shard forks are done.",h="Anachronos greets you as the one fate has been waiting a thousand years to bring forward, a champion to lead...",sec={{t="The Old God Trembles",b="Anachronos speaks of a fate a thousand years in the making. The Old God is shaken by your coming and fears your faith, and Anachronos urges you to break the prophecy of C'Thun. You bring Kalimdor's strength with you. Whenever you are prepared, you need only tell Anachronos, who will place the Scepter of the Shifting Sands in your hands.",sp=0},{t="Words of Parting",b="Anachronos declares the scepter complete again, and says it falls to you alone to wield it and lead your people into the age ahead. The Scarab Gong is not yours to ring yet: first the Horde and Alliance armies must both arrive in Silithus.",sp=1}},faq={{q="Who offers The Might of Kalimdor?",a="Anachronos. They offer it only to those who have finished all three of the Scepter Shard forks: Blue, Green and Red.",al={"who gives the might of kalimdor","anachronos quest","who gives the scepter"}},{q="What does the Old God fear?",a="Anachronos says the Old God C'Thun trembles at your coming and fears your faith, and urges you to shatter its prophecy.",al={"what old god","who fears the might of kalimdor","cthun prophecy"}},{q="What must be done before this step?",a="All three Scepter Shard forks must be finished first: the Blue, the Green and the Red.",al={"prerequisite","what do i need before might of kalimdor","scepter shard forks"}}},kw={"anachronos","c'thun","might of kalimdor","scepter","shifting sands","silithus","tanaris"},rel={"zone:tanaris","zone:silithus","topic:old-god"},m={start="Anachronos",["end"]="Anachronos",level="60",id=8742},src={"The Might of Kalimdor"}}
E["quest:8921"] = {t="quest",n="The Ectoplasmic Distiller",z="tanaris",s="Mux Manascrambler in Gadgetzan is working on his extra-dimensional ghost revealer but has run out of funds and manpower. The first piece he needs is an ectoplasmic distiller, and he asks you for a list of costly materials and forty gold to build it.",h="Mux Manascrambler in Gadgetzan is working on his extra-dimensional ghost revealer but has run out of funds...",sec={{t="What Mux Needs",b="After A Supernatural Device, Mux Manascrambler welcomes your help with his ghost revealer, a machine meant to reach across dimensions. The first piece is a distiller, meant to gather the fabric of death itself, and he warns that building it will not be easy. He wants a delicate arcanite converter, four greater eternal essences, ten stonescale oil and twenty-five volcanic ash, plus forty gold. The ash is for a filter, and it must come from the lava pools of the Burning Steppes. Mux admits the materials are pricey, but swears every one will be needed.",sp=0},{t="Mux's Thanks",b="Mux says these are exactly the materials he needed, and that you arrived at a timely moment. He promises to have your distiller ready in moments and gives you something for your trouble.",sp=1}},faq={{q="Who asks for these materials?",a="Mux Manascrambler in Gadgetzan, in Tanaris, who is building an extra-dimensional ghost revealer.",al={"quest giver","who gives the quest","who is mux"}},{q="What materials does Mux require?",a="One delicate arcanite converter, four greater eternal essences, ten stonescale oil, twenty-five volcanic ash and forty gold.",al={"required items","what do i need","distiller materials"}},{q="Where is the volcanic ash found?",a="Mux says to gather it at the lava pools of the Burning Steppes.",al={"volcanic ash location","where to get ash"}},{q="Why does Mux need these specific components?",a="They go into an ectoplasmic distiller, a device to gather the stuff death is made of. The volcanic ash is for building its filter.",al={"why arcanite","what is the ash for","why the items"}},{q="What comes after delivering the materials?",a="Hunting for Ectoplasm is the next step.",al={"next step","what happens next","next quest"}}},kw={"arcanite converter","burning steppes","ectoplasmic distiller","gadgetzan","mux manascrambler","stonescale oil","tanaris","volcanic ash"},rel={"npc:mux-manascrambler","subzone:gadgetzan","quest:8924","zone:tanaris","zone:burningsteppes"},m={start="Mux Manascrambler",["end"]="Mux Manascrambler",level="60",id=8921},src={"The Ectoplasmic Distiller"}}
E["quest:8922"] = {t="quest",n="A Supernatural Device",z="tanaris",s="Deliana is looking for a way to speak with the ghost of Anthion Harmon. An engineer with a peculiar fascination for the supernatural says he can build a machine for talking to the dead, and you bring him the blood you collected, in Gadgetzan, as his payment.",h="Deliana is looking for a way to speak with the ghost of Anthion Harmon.",sec={{t="Payment for an Engineer",b="Deliana is searching for a way to reach Anthion Harmon, or more exactly his ghost. The engineer Deliana has in mind is Mux Manascrambler, who boasts of a machine for conversing with the dead. That blood of yours was meant for him from the start, so carry it to Gadgetzan in Tanaris and give it to Mux in exchange for his services.",sp=0},{t="A Welcome Delivery",b="Mux is pleased to receive the blood, since he was running low. He then asks you whether Deliana sent you.",sp=1}},faq={{q="Why does Deliana send you to Gadgetzan?",a="Deliana wants to speak with the ghost of Anthion Harmon. An engineer in Gadgetzan claims he can build a machine to speak with the dead, so you bring him his payment.",al={"why go to gadgetzan","deliana gadgetzan","supernatural device purpose"}},{q="What is inside the container being delivered?",a="It is a sealed container of the blood you collected, intended as payment for the engineer's services.",al={"what is in the container","sealed venom container","what blood is this"}},{q="Who receives the delivery in Gadgetzan?",a="Mux Manascrambler, the engineer in Gadgetzan with a peculiar fascination for the supernatural.",al={"who gets the container","gadgetzan contact","who is mux manascrambler"}},{q="What follows this delivery?",a="The Ectoplasmic Distiller follows.",al={"what happens next","next quest","after a supernatural device"}}},ang={["faction:Alliance"]="Deliana sends Alliance adventurers to Mux Manascrambler in Gadgetzan."},kw={"anthion harmon","deliana","gadgetzan","mux manascrambler","sealed venom container","supernatural device","tanaris"},rel={"npc:mux-manascrambler","subzone:gadgetzan","quest:8921","zone:tanaris"},m={start="Deliana",["end"]="Mux Manascrambler",level="60",faction="Alliance",id=8922},src={"A Supernatural Device (Alliance)"}}
E["quest:8923"] = {t="quest",n="A Supernatural Device",z="tanaris",s="Mokvar has a use for the venom samples you collected: they are for an acquaintance, Mux Manascrambler, who is in Gadgetzan. Mux is working on a device for speaking with the dead, and Mokvar hopes it will help reach Anthion.",h="Mokvar has a use for the venom samples you collected: they are for an acquaintance, Mux Manascrambler, who is...",sec={{t="Venom for an Engineer",b="Mokvar remarks that you must be brave to have stayed on, and says there is more armor to be had for anyone still willing to help. The venom you gathered belongs with an acquaintance, Mux Manascrambler, an engineer who takes an interest in the supernatural. Mux's current project is a device for talking to the dead. Mokvar pins a last hope on it: reaching Anthion to learn more about Mokvar's own situation. You take the sealed container to Mux in Gadgetzan, in Tanaris.",sp=0},{t="A Welcome Delivery",b="Mux is pleased to receive the venom, as the supply was running low. Mux then asks whether Mokvar sent you.",sp=1}},faq={{q="Who is sending you on this delivery?",a="Mokvar, who wants the sealed venom container taken to an acquaintance in Gadgetzan.",al={"who gives this quest","quest giver","mokvar"}},{q="Where does the venom need to go?",a="To Mux Manascrambler in Gadgetzan, in Tanaris.",al={"where do i take the venom","turn in location","mux location"}},{q="Who is Mux Manascrambler?",a="An engineer fascinated by the supernatural, and an acquaintance of Mokvar's.",al={"who is mux","mux manascrambler lore"}},{q="What is Mux building?",a="A device that lets you communicate with the dead. It is Mux's latest project.",al={"what is the device","what does mux build","supernatural device"}},{q="Why does Mokvar want to reach the dead?",a="Mokvar hopes to reach Anthion and learn more about Mokvar's own situation, and sees the device as a final chance.",al={"why contact anthion","who is anthion","mokvar motive"}}},ang={["faction:Horde"]="Mokvar sends Horde adventurers to Mux Manascrambler in Gadgetzan."},kw={"anthion","gadgetzan","mokvar","mux manascrambler","sealed venom container","supernatural device","tanaris"},rel={"npc:mux-manascrambler","subzone:gadgetzan","zone:tanaris","quest:8921"},m={start="Mokvar",["end"]="Mux Manascrambler",level="60",faction="Horde",id=8923},src={"A Supernatural Device (Horde)"}}
E["quest:8924"] = {t="quest",n="Hunting for Ectoplasm",z="tanaris",s="Mux Manascrambler in Gadgetzan has his ectoplasmic distiller ready and now needs ectoplasm. You carry it to three distant lands, Silithus, Winterspring and the Eastern Plaguelands, and gather twelve of each kind from the incorporeal dead. This follows The Ectoplasmic Distiller.",h="Mux Manascrambler in Gadgetzan has his ectoplasmic distiller ready and now needs ectoplasm.",sec={{t="Three Climates, Three Kinds",b="Mux Manascrambler is proud of the distiller and warns that you have some travelling ahead to find the incorporeal undead. In Mux's view, climate changes what the spectral fabric of the dead is like. Silithus has tortured night elves, Winterspring has spirits of the highborne, and the Eastern Plaguelands have ghosts and banshees. Each place yields a different ectoplasm: twelve scorched, twelve frozen and twelve stable. Mux says to set the distiller down nearby before harvesting, then bring it and the ectoplasm back to Gadgetzan.",sp=0},{t="Mux's Verdict",b="Mux is delighted with the ectoplasm. Mux explains that the otherworldly energies in it will let you reach out to souls that have not fully left this world.",sp=1}},faq={{q="Who sends you to gather ectoplasm?",a="Mux Manascrambler in Gadgetzan, in Tanaris, once his distiller is built.",al={"who gives hunting for ectoplasm","quest giver hunting for ectoplasm"}},{q="Why does Mux need ectoplasm from three different places?",a="Mux says different climates give the spectral fabric of the dead different consistencies. He wants twelve scorched from Silithus, twelve frozen from Winterspring and twelve stable from the Eastern Plaguelands.",al={"why three ectoplasms","different ectoplasm types","why silithus winterspring plaguelands"}},{q="Which spirits provide the ectoplasm?",a="Tortured night elves in Silithus, spirits of the highborne in Winterspring, and ghosts and banshees in the Eastern Plaguelands.",al={"what enemies drop ectoplasm","what to kill for ectoplasm","which ghosts drop it"}},{q="How is the ectoplasm gathered?",a="Mux says to put the distiller down near the incorporeal undead before you harvest them.",al={"how does the distiller work","how to collect ectoplasm"}},{q="Where does this fit in Mux's work?",a="It comes after The Ectoplasmic Distiller, and A Portable Power Source follows it.",al={"hunting for ectoplasm prerequisite","what comes before hunting for ectoplasm"}}},kw={"eastern plaguelands","ectoplasmic distiller","frozen ectoplasm","gadgetzan","hunting for ectoplasm","mux manascrambler","scorched ectoplasm","silithus","stable ectoplasm","winterspring"},rel={"npc:mux-manascrambler","quest:8921","quest:8925","subzone:gadgetzan","zone:silithus","zone:winterspring","zone:easternplaguelands","zone:tanaris"},m={start="Mux Manascrambler",["end"]="Mux Manascrambler",level="60",id=8924},src={"Hunting for Ectoplasm"}}
E["quest:8925"] = {t="quest",n="A Portable Power Source",z="tanaris",s="With the ectoplasm in hand, Mux Manascrambler needs a stable, portable source of energy to keep it active. He has heard rumours of Magma Lord Bokk, an elemental in the Burning Steppes whose heart is a Magma Core, and wants that core brought to him in Gadgetzan.",h="With the ectoplasm in hand, Mux Manascrambler needs a stable, portable source of energy to keep it active.",sec={{t="A Heart of Endless Heat",b="After Hunting for Ectoplasm, Mux Manascrambler wants a steady, movable source of power to keep the ectoplasm active. Rumour has it that Magma Lord Bokk, a mighty elemental, carries a Magma Core for a heart, an endless supply of heat. The Magma Lord is said to dwell in the Burning Steppes, to the south of Blackrock Mountain and west of the Pillar of Ash. Mux wants that core brought to Gadgetzan, so the extra-dimensional ghost revealer can run.",sp=0},{t="Power at Last",b="Mux is thrilled when you arrive with the core, and declares that it will certainly give the ghost revealer all the energy it needs.",sp=1}},faq={{q="Why does Mux Manascrambler need a power source?",a="Mux wants a steady, movable supply of energy, enough to keep the ectoplasm going and run the extra-dimensional ghost revealer.",al={"why need power source","what is the power source for","why magma core"}},{q="Who is Magma Lord Bokk?",a="A mighty elemental, according to rumour, with a Magma Core for a heart, a font of heat that never runs dry.",al={"who is bokk","magma lord bokk lore","where is bokk"}},{q="Where in the Burning Steppes can Magma Lord Bokk be found?",a="Rumour places him in the Burning Steppes, to the south of Blackrock Mountain and west of the Pillar of Ash.",al={"bokk location","where is magma lord bokk","find magma lord bokk"}},{q="Where does this step fit into Mux's work?",a="It comes after Hunting for Ectoplasm, and A Shifty Merchant follows it.",al={"what comes before","quest chain order","what comes next"}}},kw={"blackrock mountain","burning steppes","gadgetzan","ghost revealer","magma core","magma lord bokk","mux manascrambler"},rel={"npc:mux-manascrambler","zone:burningsteppes","subzone:blackrock-mountain","subzone:gadgetzan","quest:8924","quest:8928","zone:tanaris"},m={start="Mux Manascrambler",["end"]="Mux Manascrambler",level="60",id=8925},src={"A Portable Power Source"}}
E["quest:8928"] = {t="quest",n="A Shifty Merchant",z="tanaris",s="Mux Manascrambler has the core to power his device and now needs a rod able to carry that power without melting. He once met an imp in Winterspring selling exotic goods, and wishes he had bought the elemental rod on offer. You look for the imp in a cave at the entrance to Darkwhisper Gorge and buy the Fel Elemental Rod.",h="Mux Manascrambler has the core to power his device and now needs a rod able to carry that power without...",sec={{t="The Imp in the Cave",b="After A Portable Power Source, Mux Manascrambler turns to the next problem: a rod able to carry the core's power without melting. Mux met an imp in Winterspring selling all manner of exotic goods, and the imp's elemental rod would have done perfectly. Mux is kicking himself for not buying it. The imp lives inside a cave at the entrance to Darkwhisper Gorge in southern Winterspring. You find the imp, buy the Fel Elemental Rod, and bring it back to Mux in Gadgetzan. Mux insists the imp charge only forty gold, the price quoted to Mux.",sp=0},{t="The Rod Arrives",b="Mux is delighted with the rod, saying it will do perfectly, and turns to putting everything together.",sp=1}},faq={{q="Who sends you after the rod?",a="Mux Manascrambler in Gadgetzan, in Tanaris.",al={"who gives a shifty merchant","quest giver a shifty merchant"}},{q="What came before this step?",a="It follows A Portable Power Source.",al={"previous quest","prereq a shifty merchant"}},{q="Where can the imp merchant be found?",a="Inside a cave at the entrance to Darkwhisper Gorge, in southern Winterspring.",al={"where is the imp","darkwhisper gorge imp location","where is the merchant in winterspring"}},{q="What item are you sent to purchase?",a="A Fel Elemental Rod.",al={"what item do i buy","what does the imp sell"}},{q="How much does the rod cost?",a="Forty gold is the price the imp quoted Mux, and Mux wants you charged no more.",al={"rod cost","how much gold for rod","imp price"}},{q="Why does Mux need this rod?",a="The core will give the device enough power, but Mux still needs a rod able to carry that power without melting.",al={"why fel elemental rod","what is the rod for"}}},kw={"darkwhisper gorge","fel elemental rod","gadgetzan","imp","merchant","mux manascrambler","winterspring"},rel={"npc:mux-manascrambler","quest:8925","subzone:gadgetzan","subzone:darkwhisper-gorge","zone:winterspring","zone:tanaris"},m={start="Mux Manascrambler",["end"]="Mux Manascrambler",level="60",id=8928},src={"A Shifty Merchant"}}
E["quest:992"] = {t="quest",n="Gadgetzan Water Survey",z="tanaris",s="Senior Surveyor Fizzledowser in Gadgetzan is hiring a temporary junior-grade surveyor for the Gadgetzan Water Company. With the nomads seizing the company's wells, you are handed a dowsing widget to tap a sample from the pool near Sandsorrow Watch.",h="Senior Surveyor Fizzledowser in Gadgetzan is hiring a temporary junior-grade surveyor for the Gadgetzan Water...",sec={{t="A Company in Need of Water",b="The nomads have seized all the wells of the Gadgetzan Water Company, so the company must find more free sources of water. Senior Surveyor Fizzledowser believes the desert holds some, though only for those clever enough to survey first, and wants a temporary junior-grade surveyor to help.",sp=0},{t="Sampling at Sandsorrow Watch",b="You are given an untapped dowsing widget and sent to the pool near Sandsorrow Watch. The pool lies due west of Gadgetzan and south of Zul'Farrak, within view of the trolls nearby. The aim is to tap a sample of its water with the widget and bring the tapped widget back to Fizzledowser.",sp=0},{t="Back With Fizzledowser",b="When you return, Fizzledowser hears that you were ambushed by some bad mojo creepy-crawly, and admits that reports have been coming in of crazy bug-creatures sucking up the desert's water. Fizzledowser took them for nonsense at first, most likely more trouble from the nomads, but now the truth is known.",sp=1}},faq={{q="Who offers the survey work in Gadgetzan?",a="Senior Surveyor Fizzledowser, who is hiring a temporary junior-grade surveyor for the Gadgetzan Water Company.",al={"who gives gadgetzan water survey","gadgetzan water survey quest giver","who is fizzledowser"}},{q="Why is the Gadgetzan Water Company searching for new pools?",a="The nomads have seized all the company's wells, so it needs other free sources of water.",al={"why survey water","why need water gadgetzan"}},{q="Where is the pool to be sampled located?",a="By the pool near Sandsorrow Watch, which lies due west of Gadgetzan and south of Zul'Farrak, within view of the trolls nearby.",al={"where is the pool","sandsorrow watch pool location","where to use dowsing widget"}},{q="What tool is provided for gathering the sample?",a="A dowsing widget, which you use at the pool to tap a sample of the water.",al={"dowsing widget","what item is used"}},{q="What follows this step?",a="This opens the chain that continues with the Noxious Lair Investigation.",al={"what quest comes next","gadgetzan water survey chain"}}},kw={"dowsing widget","fizzledowser","gadgetzan","gadgetzan water company","sandsorrow watch","tanaris"},rel={"npc:senior-surveyor-fizzledowser","subzone:gadgetzan","subzone:sandsorrow-watch","quest:82","subzone:zul-farrak","zone:tanaris","topic:troll"},m={start="Senior Surveyor Fizzledowser",["end"]="Senior Surveyor Fizzledowser",level="46",id=992},src={"Gadgetzan Water Survey"}}
E["subzone:broken-pillar"] = {t="subzone",n="Broken Pillar",z="tanaris",s="The Broken Pillar is a weathered cluster of ancient troll ruins jutting from the dunes south of Gadgetzan. It serves as an isolated research post for the goblin prospector and scientist Marvon Rivetseeker, who studies the enigmatic artifacts buried beneath the surrounding sands.",h="The Broken Pillar is a weathered cluster of ancient troll ruins jutting from the dunes south of Gadgetzan.",sec={{t="Sun-Bleached Stone",b="Rising out of the sands south of Gadgetzan and east of the treacherous Abyssal Sands, the Broken Pillar marks the remnants of ancient troll architecture long swallowed by Tanaris. Despite the desolate surroundings and encroaching desert beasts, the site offers rare clues to the continent's prehistoric civilisations. Marvon Rivetseeker, a goblin researcher originally based out of Ratchet, has established a lonely camp beside the shattered stonework to examine curious relics known as Gahz'ridian scattered across the waste.",sp=0}},faq={{q="What is the Broken Pillar?",a="The Broken Pillar is an ancient troll ruin located in central Tanaris, south of Gadgetzan and east of the Abyssal Sands. Little remains of the original structure aside from weathered stone pillars and debris half-buried in the shifting dunes.",al={"broken pillar tanaris","what is broken pillar","pillar ruins"}},{q="Who is camped at the Broken Pillar?",a="Marvon Rivetseeker, an inquisitive goblin scientist and prospector from Ratchet, has set up a solitary research camp among the ruins. He investigates the mysterious Gahz'ridian ornaments buried throughout the surrounding desert.",al={"who is at broken pillar","broken pillar npc","marvon rivetseeker location"}},{q="Who built the original ruins here?",a="The stonework is of ancient troll design, dating back to the eras when ancient troll empires held dominion across southern Kalimdor long before desert sands engulfed the region.",al={"who built broken pillar","broken pillar history","broken pillar origin"}},{q="What are Gahz'ridian relics?",a="Gahz'ridian are ancient stone artifacts and carved faces buried in the sands of Tanaris. Marvon Rivetseeker studies them from his camp at the Broken Pillar to unlock the secrets and power held within the vanished empire's craft.",al={"gahzridian","what is gahzridian","marvon quest items"}}},ang={["race:Troll"]="The crumbling pillars are solemn markers of ancestral troll architecture, echoing an era before the empire's dominion over southern Kalimdor was fractured by time and sand.",["race:Gnome"]="The curiosity driving Marvon Rivetseeker's research into unknown relic properties mirrors gnomish scholarly ambition, though his methods remain distinctively goblin."},kw={"broken pillar","gadgetzan","gahz'ridian","marvon rivetseeker","ratchet","tanaris","troll ruins"},rel={"zone:tanaris","subzone:gadgetzan","subzone:ratchet","topic:troll","topic:goblin"},src={"Broken Pillar"}}
E["subzone:caverns-of-time"] = {t="subzone",n="Caverns of Time",z="tanaris",s="Tucked into the eastern cliffs of Tanaris, the Caverns of Time serve as the mystical lair of Nozdormu and the bronze dragonflight. Within its winding depths, the dragons monitor and safeguard the fragile timeways of Azeroth against any mortal intrusion or temporal tampering.",h="Tucked into the eastern cliffs of Tanaris, the Caverns of Time serve as the mystical lair of Nozdormu and the...",sec={{t="The Winding Timeways",b="Carved deep beneath the desert cliffs, the Caverns of Time are a nexus where the currents of history converge. Charged by the titans at the dawn of the world, Nozdormu the Timeless One and his bronze dragonflight act as eternal sentinels over these corridors. Inside, time behaves erratically; glimpses of past and future slip through hidden rifts, and relics plucked from distant eras lie scattered across the sands. While the great wyrm Anachronos keeps watch near the entrance, lesser bronze drakes patrol the winding descent, fiercely protective of the one true timeline.",sp=0},{t="A Hoard of Eras",b="Beyond being a junction of past and future, the caverns serve as an eccentric vault. Over millennia, the bronze flight has gathered historical fragments from every corner of Azeroth: ancient dwarven structures, a watchtower from Lordaeron, chieftain quarters from the orcish clans, and armor dating back to the first kings of Stromgarde. Yet despite the occasional traveler daring to slip past the sentinels to glimpse these wonders, the inner gateways remain tightly shut, awaiting the day the flight deems mortal intervention necessary.",sp=0}},faq={{q="Can I go inside the Caverns of Time right now?",a="No. The way into the caverns remains sealed, and the bronze dragonflight admits no mortals. You must be careful around the drakes patrolling the entrance; while the elder bronze dragon Anachronos remains indifferent to travelers, his companions will attack any mortal who strays too close.",al={"can i enter caverns of time","how to enter caverns of time","is caverns of time open"}},{q="Who rules over the Caverns of Time?",a="The caverns belong to Nozdormu the Timeless One, the Dragon Aspect empowered by the titans to oversee time. Day-to-day stewardship and guarding of the entrance often fall to his prime scion, Anachronos, alongside the guardians of the bronze dragonflight.",al={"who leads caverns of time","caverns of time boss","who lives in caverns of time"}},{q="Why are there random buildings and artifacts inside?",a="Nozdormu spent ages cataloging and collecting physical relics from across Azeroth's history. Scattered across the caverns are misplaced treasures, including an entire Lordaeron guard tower, dwarven architecture, orcish structures, and weapons from long-forgotten mortal kingdoms.",al={"why are there human towers in caverns of time","artifacts in caverns of time"}},{q="What is the purpose of the bronze dragonflight here?",a="Their sacred duty, granted by the titans, is to safeguard the flow of time and maintain the integrity of history. They ensure that mortal tampering or outside disruptions do not unravel the events that define the world.",al={"what do bronze dragons do here","bronze flight purpose"}}},ang={["class:Mage"]="The temporal magic saturating the caverns far exceeds mortal chronomancy, offering a humbling glimpse at forces beyond arcane manipulation.",["race:NightElf"]="The kaldorei remember the ancient pacts of the Dragon Aspects well, regarding Nozdormu's charge as essential to preserving the world's survival."},kw={"anachronos","bronze dragonflight","caverns of time","nozdormu","tanaris","temporal","timeways"},rel={"zone:tanaris","topic:titan","topic:lordaeron"},src={"Caverns of Time"}}
E["subzone:circle-of-aquementas"] = {t="subzone",n="Circle of Aquementas",z="tanaris",s="The Circle of Aquementas is a mysterious ring of upright standing stones positioned along the eastern shoreline of Tanaris, just south of Lost Rigger Cove. It serves as a ritual site where travelers can call forth the elemental spirit Aquementas.",h="The Circle of Aquementas is a mysterious ring of upright standing stones positioned along the eastern...",sec={{t="A Ring by the Sea",b="Tucked away along the windswept eastern coast of Tanaris, the Circle of Aquementas sits quietly south of the pirate stronghold at Lost Rigger Cove. Composed of weathered, upright stones arranged in a circular formation, this unusual site hums with elemental energy against the desert shore. It acts as a focus for summoning Aquementas, an elemental entity tied to an ancient artifact. While the surrounding beaches crawl with Southsea brigands and roaming sea creatures, the circle itself remains a solemn pocket of ritual power amidst the dunes.",sp=0}},faq={{q="What is the Circle of Aquementas?",a="It is a circular arrangement of upright standing stones situated on the southeastern coastline of Tanaris, used to summon the elemental entity Aquementas.",al={"what is this stone ring","circle of aquementas purpose","standing stones tanaris"}},{q="Where is the circle located?",a="The circle lies on the eastern shore of Tanaris, directly south of the cliffs and entrance leading to Lost Rigger Cove.",al={"where is circle of aquementas","how to find circle of aquementas","circle of aquementas location"}},{q="Who is Aquementas?",a="Aquementas is an elemental spirit linked to an ancient quest line involving strange artifacts, summoned directly into the circle of stones.",al={"who is aquementas","aquementas lore"}},{q="Is the circle guarded by pirates?",a="While Southsea pirates prowl nearby Lost Rigger Cove and the surrounding shoreline, the circle itself is primarily an isolated site for summoning.",al={"are there pirates here","southsea pirates near circle"}}},ang={["class:Shaman"]="The circle's ability to focus primal energies and anchor an elemental spirit makes it an intriguing curiosity for any shaman wandering the Tanaris coast."},kw={"aquementas","circle of aquementas","elemental","lost rigger cove","standing stones","tanaris"},rel={"zone:tanaris","subzone:lost-rigger-cove","topic:pirate"},src={"Circle of Aquementas"}}
E["subzone:dunemaul-compound"] = {t="subzone",n="Dunemaul Compound",z="tanaris",s="Dunemaul Compound serves as the central settlement and ogre mound for the Dunemaul clan in Tanaris. Tucked into the rocky ridges bordering the desert wastes, it houses the clan's brute enforcers and spellcasters.",h="Dunemaul Compound serves as the central settlement and ogre mound for the Dunemaul clan in Tanaris.",sec={{t="A Stronghold in the Sands",b="Carved into the rugged desert rock of western Tanaris, the Dunemaul Compound is the primary stronghold of the Dunemaul ogres. These hulking desert dwellers have adapted to the harsh arid climate, scratching out an existence through brute force and opportunism. The compound itself centers on an ogre mound and cave network. Though primitive, the clan fields a dangerous mix of warriors, enforcers, and twisted spellcasters practicing dark warlock and mage magics. For travelers journeying across the dunes, the settlement is a treacherous den of aggressive giants who violently reject uninvited guests.",sp=0}},faq={{q="Who rules the Dunemaul Compound?",a="Gor'marok the Ravager leads the Dunemaul ogres occupying the compound. Andi Lynn in Gadgetzan fears the strength of this newly arrived band.",al={"dunemaul leader","dunemaul boss"}},{q="What kinds of ogres live here?",a="The settlement contains a wide variety of Dunemaul ogres, ranging from common brutes and enforcers to cunning ogre mages and warlocks wielding dark fel and shadow magic.",al={"dunemaul types","dunemaul mobs"}},{q="Why is the Horde interested in this compound?",a="No Horde interest in the compound is recorded. The Dunemaul are an independent band of ogres led by Gor'marok the Ravager, and the call to destroy the compound comes from Andi Lynn in Gadgetzan, who fears that their growing strength will threaten the region.",al={"horde dunemaul"}},{q="Who is Omgorn the Lost?",a="Omgorn the Lost is an elusive, solitary ogre known to occasionally wander the edges of the Dunemaul Compound, distinct from the common sentries patrolling the mound.",al={"omgorn","rare ogre tanaris"}}},ang={["faction:Horde"]="Though many ogres once marched with the Old Horde, the reclusive Dunemaul answer to no outside power and treat Horde travelers as intruders like any other.",["class:Warlock"]="The presence of Dunemaul warlocks among a seemingly primitive desert clan is a curious sight, showing that shadow and fel traditions have taken root even within isolated ogre mounds."},kw={"dunemaul compound","dunemaul ogres","ogre mound","omgorn","tanaris"},rel={"zone:tanaris","subzone:southmoon-ruins","topic:horde"},src={"Dunemaul Compound"}}
E["subzone:eastmoon-ruins"] = {t="subzone",n="Eastmoon Ruins",z="tanaris",s="The Eastmoon Ruins are an ancient troll archaeological site situated in eastern Tanaris, perched just west of the Gaping Chasm. Once built by the desert empires of old, the crumbling stone masonry is now occupied by Dunemaul ogres using the remnants as a desert encampment.",h="The Eastmoon Ruins are an ancient troll archaeological site situated in eastern Tanaris, perched just west of...",sec={{t="Stones in the Sand",b="Rising out of the blistering desert floor just west of the insect-infested Gaping Chasm, the Eastmoon Ruins preserve the crumbling architecture of ancient troll civilization. Decaying pillars, weathered stone plazas, and sun-bleached monuments hint at a time long before the sands swallowed this region. Rather than scholars or troll descendants tending the shrines, the site is firmly held by the Dunemaul ogres, who rely on the broken walls for shelter and vantage over nearby trade routes.",sp=0}},faq={{q="Who built the Eastmoon Ruins?",a="The architecture belongs to ancient trolls. Long before Tanaris became an arid wasteland, troll civilizations dominated southern Kalimdor, leaving behind stone stonework, temples, and plazas like those weathering at Eastmoon.",al={"who made eastmoon ruins","eastmoon origin","trolls built eastmoon"}},{q="Who controls Eastmoon Ruins now?",a="The ruins are occupied by the Dunemaul ogres of Tanaris. These hulking desert brutes have claimed the ancient stone walls to set up camps and keep watch over eastern Tanaris.",al={"who lives at eastmoon","eastmoon ruins mobs","wastewanders at eastmoon"}},{q="Where are the Eastmoon Ruins located?",a="You can find them in the eastern reaches of Tanaris, situated immediately west of the silithid-infested hives of the Gaping Chasm.",al={"eastmoon ruins location","where is eastmoon","find eastmoon ruins"}},{q="Are there any quests in Eastmoon Ruins?",a="There are no formal quests directed specifically to the Eastmoon Ruins. The site serves primarily as a Dunemaul ogre camp and a historical landmark for adventurers exploring the deeper desert.",al={"eastmoon quests","quests at eastmoon ruins","is there a quest here"}}},ang={["race:Troll"]="The ruined masonry is a quiet reminder of your ancestors' far-reaching dominion over Kalimdor before the desert sands claimed the south.",["class:Rogue"]="The broken pillars and scattered stone walls provide plenty of blind corners to slip past or ambushing the Dunemaul ogres roaming the perimeter."},kw={"dunemaul","eastmoon","eastmoon ruins","gaping chasm","tanaris","troll ruins"},rel={"zone:tanaris","subzone:gaping-chasm","topic:troll"},src={"Eastmoon Ruins"}}
E["subzone:gadgetzan"] = {t="subzone",n="Gadgetzan",z="tanaris",s="Gadgetzan is the walled desert hub of the Steamwheedle Cartel, standing as an island of commerce in northern Tanaris. Open to both Horde and Alliance travelers, the town operates under strictly enforced goblin neutrality, welcoming anyone with coin to spend or odd jobs to undertake.",h="Gadgetzan is the walled desert hub of the Steamwheedle Cartel, standing as an island of commerce in northern...",sec={{t="A Bastion of Profit in the Dunes",b="Surrounded by scorching sands, Gadgetzan serves as the regional heart for the Steamwheedle Cartel's ventures in southern Kalimdor. Built with characteristic goblin ingenuity and haphazard architecture, the town boasts an independent auction house, bank, inn, and specialized crafting facilities for engineers, blacksmiths, and alchemists. It also houses flight masters catering to both major factions, ensuring steady traffic of adventurers heading toward Tanaris, Feralas, and the untamed basin of Un'Goro. Above all, commerce rules supreme: as long as visitors keep their weapons sheathed and their purses open, they are safe within its gates.",sp=0},{t="Desert Troubles and Enforced Order",b="Peace in Gadgetzan is maintained not by good will, but by heavily armed goblin bruisers who swiftly pummel anyone who threatens trade or instigates faction brawls. Beyond the gates, however, life is precarious. The Gadgetzan Water Company constantly battles the Wastewander bandits, a ruthless gang occupying the vital Waterspring Field. Water is liquid gold in Tanaris, and the cartel frequently hires outside mercenaries to eliminate bandit leadership and reclaim vital water pouches to keep the town's reservoirs functional.",sp=0}},faq={{q="Can Alliance and Horde attack each other in Gadgetzan?",a="No. Gadgetzan is strictly neutral territory owned by the Steamwheedle Cartel. Goblin bruisers heavily patrol the town and will immediately attack anyone caught disturbing the peace or initiating violence against other travelers.",al={"is gadgetzan safe","pvp in gadgetzan","can horde and alliance fight here"}},{q="Why is water such a big deal around here?",a="Situated in the middle of an arid desert, Gadgetzan relies entirely on the Gadgetzan Water Company's extraction towers at Waterspring Field. Wastewander bandits have overrun these wells, cutting off the town's primary supply and forcing the goblins to pay bounties for stolen water pouches.",al={"gadgetzan water company","why water pouches","waterspring field conflict"}},{q="Who controls Gadgetzan?",a="Gadgetzan is owned and governed by the Steamwheedle Cartel, the largest and most prominent mercantile goblin organization on Azeroth.",al={"who runs gadgetzan","gadgetzan faction","what cartel owns gadgetzan"}},{q="What makes the auction house here special?",a="Unlike the faction-restricted markets in Orgrimmar or Stormwind, Gadgetzan hosts a neutral auction house. Both Alliance and Horde players can buy and sell goods to one another here, though the goblins charge a much higher transaction fee for the privilege.",al={"gadgetzan auction house","neutral auction house","cross faction ah"}}},ang={["profession:Engineering"]="Gadgetzan is an essential crossroads for tinkerers, hosting advanced trainers, specialized schematics, and an arrival teleportation pad calibrated specifically for gnomish engineers.",["profession:Blacksmithing"]="The town features heavy-duty forges and anvils favored by advanced metalworkers, serving as a key staging ground for members of the Mithril Order."},kw={"auction house","gadgetzan","goblin","neutral","steamwheedle cartel","tanaris","wastewander","waterspring field"},rel={"topic:steamwheedle-cartel","zone:tanaris","subzone:waterspring-field","zone:ungoro","topic:goblin","subzone:ratchet"},src={"Gadgetzan"}}
E["subzone:gaping-chasm"] = {t="subzone",n="Gaping Chasm",z="tanaris",s="The Gaping Chasm is a sprawling silithid hive carved deep into the sands of southeastern Tanaris. Infested by aggressive insectoid horrors of the Hazzali brood, it serves as a grim warning of the growing silithid menace spreading beyond the western deserts.",h="The Gaping Chasm is a sprawling silithid hive carved deep into the sands of southeastern Tanaris.",sec={{t="The Hive in the Dunes",b="Breaking the rolling expanses of Tanaris, the Gaping Chasm plunges down into a teeming subterranean warren of tunnels, resinous mounds, and twitching carapaces. This hive belongs to the Hazzali, an aggressive brood of silithid that have burrowed beneath the desert wastes. Between subterranean stingers, swarmers, and hulking sandreavers, any travelers or treasure-hunters foolish enough to descend into the chasm quickly find themselves hunted as prey or preserved in sticky cocoons.",sp=0},{t="A Surveyor's Grave",b="The expanding hive caught the attention of Gadgetzan's enterprising minds, prompting Senior Surveyor Fizzledowser to dispatch his junior surveyor, Scrimshank, into the pit to map and measure the geological shifts caused by the insect tunnels. Unsurprisingly, the expedition ended in disaster. Scrimshank met a grim end amidst the chittering broods, leaving behind scattered gear and measuring instruments that caution anyone against underestimating the silithid threat.",sp=0}},faq={{q="What creatures dwell inside the Gaping Chasm?",a="The chasm is infested entirely by the Hazzali silithid. The hive includes numerous castes of the insectoid species, such as worker drones, winged stingers, overwhelming swarms, and massive, chitin-plated sandreavers.",al={"what lives in gaping chasm","bugs in tanaris chasm","gaping chasm mobs"}},{q="Where is the Gaping Chasm located?",a="The chasm lies in southeastern Tanaris, carved out of the desert sands south of Gadgetzan and east of the mountainous ridge dividing Tanaris from the western wilderness.",al={"where is gaping chasm","gaping chasm location","how to find gaping chasm"}},{q="Why was a gnome surveyor sent into the chasm?",a="Senior Surveyor Fizzledowser in Gadgetzan sent Junior Surveyor Scrimshank to survey the cavern and assess its geological activity. Unfortunately, Scrimshank was overwhelmed and killed by the Hazzali silithid before he could complete his assignment.",al={"who was scrimshank","fizzledowser surveyor quest","why did scrimshank go there"},sp=1},{q="Are the silithid here related to the ones in other parts of Kalimdor?",a="Yes. The Hazzali silithid in Tanaris share the same insectoid nature and hive-mind structure as broods found in the southern barrens and the blighted wastes of Silithus to the west, signaling a dangerous, coordinated expansion across southern Kalimdor.",al={"are these silithid connected to silithus","why are bugs in tanaris"}}},ang={["race:Gnome"]="The unfortunate demise of Junior Surveyor Scrimshank inside the chasm serves as a sobering reminder that field research in Kalimdor demands serious firepower alongside scientific curiosity.",["profession:Mining"]="The exposed subterranean clefts and sunken earth of the silithid hive occasionally reveal rich mineral deposits, though digging them out requires fending off dozens of vicious burrowing insects."},kw={"fizzledowser","gaping chasm","hazzali","hive","sandreaver","scrimshank","silithid","tanaris"},rel={"zone:tanaris","subzone:gadgetzan","npc:senior-surveyor-fizzledowser"},src={"Gaping Chasm"}}
E["subzone:land-s-end-beach"] = {t="subzone",n="Land's End Beach",z="tanaris",s="Land's End Beach is a desolate stretch of coastline at the far southern tip of Tanaris, effectively marking the southern edge of Kalimdor. Shielded by towering mountain ridges and vast ocean waters, it remains one of the most secluded and inaccessible shores on the continent.",h="Land's End Beach is a desolate stretch of coastline at the far southern tip of Tanaris, effectively marking...",sec={{t="The Edge of the World",b="Tucked away behind the southern mountain ranges of Tanaris and the sealed titan gateway to Uldum, Land's End Beach represents the absolute southern edge of Kalimdor's mainland. Cut off from overland routes across the desert dunes, reaching this windswept coast requires swimming along the dangerous, fatigue-inducing open waters of the South Seas. The beach is a barren frontier of crashing surf, shifting sand, and quiet isolation, largely untamed by the cartels or desert explorers who dwell farther north around Gadgetzan.",sp=0},{t="Offshore Mysteries",b="Beyond the breakers of the beach lie lonely, unnamed islets separated from the mainland by vast expanses of exhausting deep water. Navigating to these distant specks of rock is treacherous enough to push even seasoned swimmers to their physical limits. Few mortals have any reason to seek out the lonely waters at Kalimdor's end, leaving the beach and its surrounding shoals undisturbed beneath the blazing southern sun.",sp=0}},faq={{q="Where is Land's End Beach located?",a="Land's End Beach is located along the southernmost coast of Tanaris, directly south of the mountains that seal off the ancient titan gates of Uldum at the far southern tip of Kalimdor.",al={"where is lands end beach","lands end beach location","how to find lands end beach"}},{q="How do you reach Land's End Beach?",a="Because massive mountain ranges block overland access from the desert interior, travelers typically must swim along the southern coastline from eastern Tanaris or navigate around the perilous open waters, being careful not to succumb to fatigue in the deep sea.",al={"how do i get to lands end beach","get to lands end tanaris","reach lands end"}},{q="What is on the islands off the coast of the beach?",a="Remote, unnamed islands sit far off the shoreline across a wide channel of deep, fatigue-inducing ocean. They are desolate rocky spits that very few travelers have ever reached or explored.",al={"unnamed islands lands end","offshore islands tanaris","islands near lands end"}},{q="Does anyone live on Land's End Beach?",a="The shoreline is uninhabited by any major settlements. Cut off from trade and civilization, it remains a barren natural shore buffeted by the ocean winds.",al={"who lives at lands end","lands end beach inhabitants","is anyone at lands end"}}},kw={"beach","coast","kalimdor","land's end beach","shore","south seas","tanaris","uldum"},rel={"zone:tanaris","subzone:uldum","subzone:gadgetzan"},src={"Land's End Beach"}}
E["subzone:lost-rigger-cove"] = {t="subzone",n="Lost Rigger Cove",z="tanaris",s="Tucked away along the eastern cliffs of Tanaris, Lost Rigger Cove serves as the primary base of operations for the Southsea Pirates in the region. Shielded by towering desert mountains on three sides, this hidden port boasts docks, fortified encampments, and an active shipyard constructing new pirate vessels.",h="Tucked away along the eastern cliffs of Tanaris, Lost Rigger Cove serves as the primary base of operations...",sec={{t="Pirates and Mountain Walls",b="Naturally fortified by sheer rock walls on almost every side, Lost Rigger Cove provides the Southsea Freebooters an ideal maritime stronghold on Kalimdor's southeastern edge. Here, pirate cutthroats, dockworkers, and brigands haul salvage and assemble fresh hulls right under the noses of Gadgetzan's authorities. The cove allows the Southseas to project power across the Great Sea while raiding trade routes between Ratchet, Booty Bay, and coastal settlements.",sp=0},{t="Rivals on the Doorstep",b="The pirates do not hold their cove unchallenged. The goblins of Gadgetzan and nearby Steamwheedle Port resent the raiders on their doorstep and pay mercenaries to slaughter the Southseas, thin their ranks, and disrupt their operations.",sp=0}},faq={{q="Who controls Lost Rigger Cove?",a="The cove is held by the Southsea Pirates, an infamous maritime syndicate operating throughout Kalimdor and the South Seas. They use this natural harbor to repair their fleet and construct new warships.",al={"who owns lost rigger cove","who lives in lost rigger cove","lost rigger cove factions"}},{q="Who is fighting the pirates here?",a="The goblins of Gadgetzan and Steamwheedle Port, who resent the raiders on their doorstep, hire passing adventurers to strike at the pirate stronghold and thin the Southsea ranks.",al={"gnome goblin camp tanaris","why are gnomes here","why fight the pirates"}},{q="Where is Lost Rigger Cove located?",a="It lies along the eastern coast of Tanaris, southeast of Gadgetzan. It is accessed through a winding canyon path cut through the coastal mountain barrier.",al={"where is lost rigger cove","how to get to lost rigger cove","lost rigger cove map"}},{q="What are the pirates building in the cove?",a="The Southsea Pirates operate an active drydock and shipyard in the center of the cove, where carpenters and brigands are busy assembling the hull of a large ocean-going war vessel.",al={"shipyard lost rigger cove","pirate boat construction"}}},ang={["class:Rogue"]="The sprawling pirate camp is dense with pockets to pick, private lockboxes, and cutthroats who know every dirty trick of maritime swashbuckling.",["race:Gnome"]="For gnomish tinkerers, the pirates' drydock is a crude but telling display of salvaged machinery and stolen parts, and a standing threat to every merchant vessel on the southern seas."},kw={"freebooter","gadgetzan","lost rigger cove","shipyard","southsea pirates","tanaris"},rel={"zone:tanaris","subzone:gadgetzan","topic:gnome","topic:goblin","topic:pirate"},src={"Lost Rigger Cove"}}
E["subzone:noxious-lair"] = {t="subzone",n="Noxious Lair",z="tanaris",s="The Noxious Lair is a sunken silithid hive situated in the southwestern deserts of Tanaris, bordering Un'Goro Crater. Once a verdant basin with flowing water, the territory has been infested and drained of its vital resources by the burrowing Centipaar swarm. Now, it stands as an acidic breeding ground filled with swarming insectoids and rich mineral veins.",h="The Noxious Lair is a sunken silithid hive situated in the southwestern deserts of Tanaris, bordering Un'Goro...",sec={{t="A Drained Basin",b="Resting against the western ridges overlooking Un'Goro Crater, the Noxious Lair occupies a depression in the sand that once held a lake or shallow river. When the Centipaar silithid invaded, they consumed the desert's remaining underground moisture and transformed the basin into an encroaching colony. Vast pincers and twitching limbs rise directly from the sand dunes, surrounding subterranean tunnels slick with corrosive insect secretions and clusters of incubating eggs.",sp=0},{t="The Centipaar Swarm",b="Subterranean tunnels link the surface entrances to humid, acid-coated breeding chambers beneath the sands. Centipaar workers, tunnelers, wasps, and colossal sandreavers patrol the perimeter, defending their brood from outside threats. Beyond its biological dangers, the upheaval caused by silithid excavation has unearthed deep mineral deposits, creating an unusually diverse hunting and prospecting ground where subterranean ores sit exposed amid the swarming hives.",sp=0}},faq={{q="What kind of creatures live in the Noxious Lair?",a="The lair is populated by the Centipaar, a colony of the insectoid silithid. The hive is defended by workers, burrowing tunnelers, flying wasps, and predatory sandreavers, all guarded under the rule of rare hive terrors like Soriid the Devourer.",al={"what mobs are in noxious lair","noxious lair insects","centipaar silithid"}},{q="What was here before the silithid took over?",a="The sunken topography indicates that the area was once a riverbed or shallow desert lake. The arriving silithid burrowed beneath the earth, drained western Tanaris of its vital water and natural resources, and left behind a desolate, acid-soaked basin.",al={"noxious lair history","was noxious lair a lake","water in noxious lair"}},{q="Why are goblins interested in this hive?",a="Gadgetzan goblins view the hive as a hazard to desert commerce and have sent adventurers to investigate the lair and the silithid expansion.",al={"goblin quests noxious lair","steamwheedle noxious lair","thunderdrome silithid"}},{q="Is the Noxious Lair connected to other insect hives in the desert?",a="The Noxious Lair represents the Centipaar hive, one of several insectoid colonies spreading out from the southern wastes. While physically distinct from hives farther south, its tunnels share the same eerie subterranean architecture and threaten to choke out life across Tanaris.",al={"other hives tanaris","centipaar hive connection","silithid expansion"}}},ang={["profession:Mining"]="The silithid burrowing in the basin has exposed an unusually diverse selection of ore, letting miners gather Iron, Mithril, Truesilver, and Thorium veins in the same territory.",["class:Druid"]="The hive is a disturbing perversion of nature, demonstrating how quickly the invasive silithid can drain a once-watered basin into an arid, acidic wasteland."},kw={"centipaar","hive","noxious lair","sandreaver","silithid","soriid","tanaris"},rel={"zone:tanaris","zone:ungoro","topic:goblin"},src={"Noxious Lair"}}
E["subzone:ruins-of-uldum"] = {t="subzone",n="Ruins of Uldum",z="tanaris",s="Tucked into the jagged cliffs of the Valley of the Watchers in southern Tanaris, the Ruins of Uldum consist of an ancient stone hall guarding a sealed Titan facility. Massive stone doors protect its secrets from grave robbers and curious explorers alike.",h="Tucked into the jagged cliffs of the Valley of the Watchers in southern Tanaris, the Ruins of Uldum consist...",sec={{t="The Antechamber of the Titans",b="Carved deep into the bedrock of southern Tanaris, the Ruins of Uldum appear to be an antechamber or grand threshold to a far larger, sealed subterranean complex. Its colossal stone gates stand shut against the outside world, and no mechanism or key known to modern scholars has managed to open them.",sp=0},{t="Secrets of the Biosphere",b="According to ancient records and celestial watchers, Uldum was established by the Titans alongside facilities like Uldaman and Ulduar as a research site dedicated to modifying and monitoring the biosphere of Azeroth. When the Great Sundering tore the world apart ten thousand years ago, the earthen felt the agony of the world and retreated into these subterranean vaults to hibernate. Full access beyond the ruins' sealed inner threshold requires the lost Plates of Uldum, leaving the full extent of the facility locked away from modern surface-dwellers.",sp=1}},faq={{q="What is inside the Ruins of Uldum?",a="No one knows for certain. The ruins are an ancient titan hall sealed behind massive stone gates, and the complex beyond them remains closed to modern explorers.",al={"what's in uldum","what is uldum tanaris","ruins of uldum interior"}},{q="Can players enter the main facility behind the door?",a="No. The gates remain sealed. The Stone Watcher of Norgannon says entry into the Uldum compound is allowed only to those who carry the lost Plates of Uldum, and no one has yet found them.",al={"can you open the door to uldum","how to get into uldum","open uldum door"}},{q="What was Uldum built for?",a="Titan constructs such as the Stone Watcher of Norgannon describe Uldum as a research complex intended to study, sustain, and enhance Azeroth's biosphere, similar in origin to sites like Uldaman and Ulduar.",al={"why did titans build uldum","uldum purpose","lore of uldum"}}},ang={["race:Dwarf"]="For dwarves tracing their lineage back to the earthen, Uldum represents one of the original titan crèches where their ancestors first rested following the Sundering.",["profession:Mining"]="The stonework and machinery of Uldum showcase titan craftsmanship that has endured thousands of years of tectonic pressure and desert decay without faltering."},kw={"earthen","tanaris","titans","uldum","valley of the watchers"},rel={"subzone:valley-of-the-watchers","zone:tanaris","topic:titan","subzone:uldaman"},src={"Ruins of Uldum"}}
E["subzone:sandsorrow-watch"] = {t="subzone",n="Sandsorrow Watch",z="tanaris",s="Sandsorrow Watch is a sprawling desert outpost located just west of Gadgetzan in Tanaris. The surrounding dunes and ruins are overrun by hostile Sandfury trolls and their reanimated dead, who also hold the eastern watch tower overlooking the waste.",h="Sandsorrow Watch is a sprawling desert outpost located just west of Gadgetzan in Tanaris.",sec={{t="A Precarious Perch",b="Situated directly west of the bustling goblin trading hub of Gadgetzan, Sandsorrow Watch is a grim borderland in the Tanaris desert. The broad expanse is dominated by the Sandfury tribe, who aggressively defend the arid territory alongside legions of shambling troll zombies. An elevated watch tower at the eastern edge anchors the position, providing a fortified vantage point amidst the encroaching desert wilderness and the hostile indigenous tribes.",sp=0},{t="Frontier Outpost",b="Even the watch tower at the eastern edge, within sight of Gadgetzan's walls, is held by the Sandfury. From its heights the Sandfury keep a wary eye on the goblin town, and travelers leaving through Gadgetzan's western gate walk almost directly into their territory, a constant reminder of the volatile frontier tension between Tanaris's opportunistic settlers and the native sand trolls.",sp=0}},faq={{q="Where is Sandsorrow Watch located?",a="Sandsorrow Watch is located directly west of Gadgetzan in the northern desert plains of Tanaris. Travelers heading out through Gadgetzan's western gate will encounter it almost immediately.",al={"sandsorrow watch location","where is sandsorrow","how to get to sandsorrow watch"}},{q="Who controls Sandsorrow Watch?",a="The ruins, the surrounding dunes and the eastern watch tower are all occupied by hostile Sandfury trolls and their undead minions.",al={"who lives at sandsorrow","sandsorrow watch faction","who holds sandsorrow watch"}},{q="Why are there undead trolls at Sandsorrow Watch?",a="The Sandfury tribe practices dark necromantic arts and voodoo, frequently raising fallen Sandfury warriors as Sandfury Zombies to guard their desolate territory and outposts across Tanaris.",al={"sandfury zombies","why troll zombies tanaris","sandsorrow zombies"}},{q="What threats can adventurers expect in the surrounding dunes?",a="The area is heavily patrolled by Sandfury Axe Throwers, Firecallers, and Hideskinners, alongside their reanimated troll zombies. Unprepared travelers venturing off the main path west of Gadgetzan can easily be overwhelmed by roving Sandfury warbands.",al={"sandsorrow mobs","sandsorrow watch enemies","hostile trolls sandsorrow"}}},ang={["profession:Blacksmithing"]="No smith works at the Sandfury-held watch tower; desert smiths gather behind Gadgetzan's walls instead, just to the east.",["race:Troll"]="Darkspear trolls will find no kinship here: the hostile Sandfury tribe views all outsiders as invaders to be crushed and raised as shambling corpses."},kw={"gadgetzan","sand troll","sandfury","sandsorrow","sandsorrow watch","tanaris"},rel={"zone:tanaris","subzone:gadgetzan","topic:troll"},src={"Sandsorrow Watch"}}
E["subzone:south-seas"] = {t="subzone",n="South Seas",z="tanaris",s="The South Seas encompass the vast, sun-drenched waters separating the southern regions of Kalimdor and the Eastern Kingdoms. Lapping at the shores of Tanaris and Stranglethorn Vale, these tropical expanses are famed for lucrative trade routes, perilous reefs, and brazen pirate crews.",h="The South Seas encompass the vast, sun-drenched waters separating the southern regions of Kalimdor and the...",sec={{t="A Swashbuckler's Frontier",b="Spanning southward beneath the Great Sea and the Maelstrom, the South Seas wash against the deserts of Tanaris and the lush jungles of Stranglethorn Vale. Since the Great Sundering shattered the primeval continent ten thousand years ago, this ocean has nurtured remote tropical islands, unique oceanic beasts, and independent merchant networks. Goblin shipping cartels, operating out of havens like Steamwheedle Port and Booty Bay, maintain tenuous shipping lanes across the waves. However, the waters remain notoriously lawless, crawling with corsairs, Bloodsail buccaneers, and predatory sea life that prey on any vessel daring to venture far from shore.",sp=0},{t="Hidden Depths and Distant Isles",b="Beyond the coastal trade lanes lies a patchwork of legendary islands and sunken perils. Notable lands scattered across the South Seas include the ancient troll island of Zandalar and the produce-rich shores of Tel'Abim. Yet merchant sailors must contend with far more than cutthroats; the deeper waters harbor colossal giant squids, primeval sea turtles, and lurking naga who guard ancient ruins swallowed by the waves. Navigating these waters demands seasoned captains, reliable charts, and substantial firepower.",sp=0}},faq={{q="What zones border the South Seas?",a="In southern Kalimdor, the South Seas form the coastline of Tanaris, near the sealed gates of Uldum. Across the ocean to the east, they wash against the shores of Stranglethorn Vale and its outlying islands like Jaguero Isle and Yojamba Isle.",al={"where are south seas","south seas borders","what coast is south seas"},it="place"},{q="Who controls shipping in the South Seas?",a="No single faction rules the South Seas. The Steamwheedle Cartel controls the primary merchant traffic between Steamwheedle Port and Booty Bay, but they constantly contest the waters against rival pirate outfits such as the Bloodsail Buccaneers and the Southsea Freebooters.",al={"who runs south seas","south sea trade","ports in south seas"},it="in_charge"},{q="What dangerous creatures live in these waters?",a="The open waves teem with hazards ranging from ravenous giant squids and coastal reef sharks to armored giant turtles. In the Second War, the Horde's Stormreaver clan even captured giant turtles native to these waters to refit them as naval submersibles. Islands in the region also harbor flesh-eating bloodwing bats and lurking naga patrols.",al={"south seas monsters","sea monsters tanaris","south sea creatures"},it="threat"},{q="What notable islands lie out in the South Seas?",a="Renowned islands out in the deep waters include the fruit-rich island of Tel'Abim and Zandalar, the historic realm of the troll empire. Closer to the coasts lie smaller landmarks like Yojamba Isle and Jaguero Isle.",al={"islands in south seas","kezan zandalar south seas","south seas island list"}},{q="What is the South Seas?",a="The South Seas is the sprawling southern expanse of the Great Sea, separating the lower reaches of Kalimdor and the Eastern Kingdoms. Lying south of the raging Maelstrom, these warm, tropical waters wash against the coasts of Tanaris and Stranglethorn Vale, dotted with remote archipelagos, pirate havens, and uncharted islands.",al={"what is south seas","south seas overview","where is south seas"},it="place",add="b58adc59"},{q="What happened in the history of the South Seas?",a="Ten thousand years ago, all of Azeroth was a single continent before the Great Sundering shattered the landmass. When the Well of Eternity imploded during the War of the Ancients, the ocean rushed in to fill the rift, tearing continents apart and creating the Maelstrom and the surrounding seas. The islands scattered across the South Seas are remnants of that ancient world.",al={"south seas history","how was south seas formed","origin of south seas"},it="history",add="89d72661"},{q="Is traveling the South Seas dangerous?",a="These waters are notoriously treacherous. Beyond erratic weather and treacherous reefs, the South Seas teem with aggressive predators, including giant squids and monstrous, flesh-eating bloodwing bats nesting on tropical isles. Worse still, cutthroat pirate cartels such as the Bloodsail Buccaneers roam the shipping channels, preying upon merchant vessels and daring travelers.",al={"is south seas dangerous","south seas hazards","south seas threats"},it="danger",add="68566e28"},{q="Why is it called the South Seas?",a="The region simply takes its name from its geography as the southern portion of the Great Sea, covering the waters south of the central Maelstrom and bordering the southern coasts of both main continents.",al={"why south seas name","how did south seas get its name"},it="name",add="7fe84177"}},ang={["class:Rogue"]="The lawless South Seas are the lifeblood of pirate cartels and privateers, offering endless opportunities for scoundrels adept at boarding actions, smuggling contraband, and navigating cutthroat harbor politics.",["profession:Cooking"]="The exotic waters and coastal shores of the South Seas yield prized oceanic fish, giant squids, and the famous, sweet bananas shipped from isolated isles like Tel'Abim."},kw={"bloodsail","pirates","south seas","steamwheedle","stranglethorn","tanaris","tel'abim","zandalar"},rel={"zone:tanaris","subzone:steamwheedle-port","zone:stranglethorn","subzone:booty-bay","topic:pirate","topic:goblin","subzone:uldum","topic:war-of-the-ancients"},src={"South Seas"}}
E["subzone:southmoon-ruins"] = {t="subzone",n="Southmoon Ruins",z="tanaris",s="The Southmoon Ruins are ancient stone remains situated in southern Tanaris, just north of the Valley of the Watchers. Long claimed by the brutish Dunemaul ogres, the crumbling stonework preserves remnants of the ancient troll civilization that dominated the desert before the sands swallowed it.",h="The Southmoon Ruins are ancient stone remains situated in southern Tanaris, just north of the Valley of the...",sec={{t="Stones in the Shifting Sands",b="Rising out of the blistering wastes of southern Tanaris, the Southmoon Ruins stand as a weathered testament to the ancient troll empires that once ruled Kalimdor's southern reaches. Like nearby Eastmoon and Noonshade, its stone pillars and altars have weathered thousands of years of wind and abrasive grit. The site has often served as a squalid camp for the Dunemaul ogres, who show little reverence for the craftsmanship of the past, using the ancient structures purely for shelter and territory.",sp=0},{t="Secrets Beneath the Rubble",b="The architectural remnants are unmistakably trollish, but little is recorded of the people who raised Southmoon's stones or why they abandoned them. Whatever they left behind lies buried beneath the drifting sand, and the ogres who squat among the pillars care nothing for it.",sp=0}},faq={{q="Who originally built the Southmoon Ruins?",a="The Southmoon Ruins are ancient troll ruins, weathered remnants of the troll civilization that once held the southern reaches of what is now the Tanaris desert.",al={"who built southmoon","southmoon history","are these troll ruins"}},{q="Who inhabits the ruins currently?",a="The ruins have traditionally been occupied by the Dunemaul ogres, who wandered down into Tanaris and claimed various crumbling ancient outposts as their encampments, driving off other scavengers.",al={"who lives here","southmoon mobs","dunemaul at southmoon"}},{q="Where are the Southmoon Ruins located?",a="They lie in the southern half of Tanaris, situated northwest of the Valley of the Watchers and south of the central desert wastes.",al={"southmoon location","where is southmoon ruins","how to find southmoon"}}},ang={["race:Dwarf"]="Dwarven travelers crossing southern Tanaris find little at Southmoon beyond weathered troll stonework and the Dunemaul ogres camped among it.",["race:Troll"]="For Darkspear trolls, these broken columns are a sobering look at the fallen grandeur of their distant troll cousins, reduced to squalor beneath the desert sun."},kw={"dunemaul","ruins","southmoon","southmoon ruins","tanaris","valley of the watchers"},rel={"zone:tanaris","subzone:valley-of-the-watchers","topic:troll"},src={"Southmoon Ruins"}}
E["subzone:steamwheedle-port"] = {t="subzone",n="Steamwheedle Port",z="tanaris",s="Steamwheedle Port is a bustling coastal outpost on the eastern shore of Tanaris, directly connected to Gadgetzan. Operated by the neutral Steamwheedle Cartel, it serves as an essential sea link across the South Seas while constantly warding off encroaching Southsea Pirates.",h="Steamwheedle Port is a bustling coastal outpost on the eastern shore of Tanaris, directly connected to...",sec={{t="A Gateway on the Shifting Sands",b="Tucked against the dunes along the South Seas, Steamwheedle Port offers the inland desert city of Gadgetzan a direct lifeline to maritime trade. Run by the Steamwheedle Cartel, the settlement bustles with dockhands, traders, and sea captains braving the treacherous waters. Supply vessels regularly ply the routes between here and distant goblin trading posts, bringing valuable mechanical components, luxuries, and raw materials into southern Kalimdor.",sp=0},{t="Pirates and Strange Scholars",b="Life on the port is far from peaceful. Just south along the coast lies Lost Rigger Cove, home to rampant Southsea Freebooters who regularly raid goblin shipping, steal cargo, and contest control of the coastline. Aside from haggling dockworkers and paranoid merchants trying to recover stolen shipments, the port also shelters unusual travelers, such as the enigmatic troll Yeh'kinya, who studies the ancient and ominous spirits of the world away from prying eyes.",sp=0}},faq={{q="Who controls Steamwheedle Port?",a="The settlement is built and administered by the Steamwheedle Cartel, the primary trade conglomerate of neutral goblins. As long as you maintain standing with Gadgetzan and the Cartel, both Alliance and Horde travelers are welcomed freely.",al={"who runs steamwheedle port","steamwheedle port faction","is steamwheedle port friendly"}},{q="Where do the ships from this port travel?",a="The port serves as the Cartel's maritime link across the South Seas, connecting it to distant goblin trading hubs, and a passenger ship sails from its docks across the sea to Powderfuse Port in the Riverglades.",al={"where do ships go from steamwheedle","steamwheedle port ferry"}},{q="Why are there so many pirates nearby?",a="The Southsea Freebooters established their base just south at Lost Rigger Cove. They frequently hijack incoming cargo, raid dock supplies, and pick off stragglers along the shoreline, making them the primary local threat to goblin trade.",al={"lost rigger cove pirates","southsea pirates tanaris"}},{q="Who is Yeh'kinya?",a="Yeh'kinya is an eccentric troll scholar resting at the port. He enlists daring adventurers to travel abroad, capturing spiritual essences such as screechers from Feralas to research forgotten, primordial rituals.",al={"yehkinya purpose","troll in steamwheedle port"}}},ang={["profession:Engineering"]="The port is an invaluable depot for parts and supplies imported from across the South Seas, making it a natural hub of gossip and schematics for tinkerers.",["class:Rogue"]="The constant friction between goblin merchants and the nearby Southsea Pirates creates lucrative opportunities for pickpockets, scouts, and recovery contracts."},kw={"gadgetzan harbor","lost rigger cove","southsea pirates","steamwheedle port","tanaris docks","yeh'kinya"},rel={"zone:tanaris","subzone:gadgetzan","topic:steamwheedle-cartel","subzone:lost-rigger-cove","npc:yeh-kinya","topic:pirate","subzone:south-seas","topic:goblin"},src={"Steamwheedle Port"}}
E["subzone:thistleshrub-valley"] = {t="subzone",n="Thistleshrub Valley",z="tanaris",s="Tucked away in the southwestern reaches of Tanaris, Thistleshrub Valley is a bizarre oasis of prickly plant life amidst endless dunes. The canyon is known for its strange grove of giant cacti and hostile animated thistleshrubs that attack anything stepping through their thorn-choked territory.",h="Tucked away in the southwestern reaches of Tanaris, Thistleshrub Valley is a bizarre oasis of prickly plant...",sec={{t="A Grove of Thorns",b="While most of Tanaris is an arid wasteland stripped bare of vegetation, Thistleshrub Valley is curiously choked with life. Giant blooming cacti tower over the canyon floor, providing a sharp contrast to the surrounding sea of sand. However, this is no peaceful sanctuary. The valley takes its name from the hostile, living plant creatures that lurk among the brush. These thistleshrubs lash out with razor-sharp spines at any traveler who wanders near, making navigation hazardous for those trying to push past the cliffs toward the mysterious southern gates.",sp=0},{t="Sentinels of the Desert",b="The presence of animated flora in such a dry climate has long puzzled wanderers and desert survivalists. Whether awakened by forgotten elemental energies or stubborn adaptation to the harsh Tanaris climate, the thistleshrubs remain violently territorial. Travelers journeying through the canyon must contend not only with these thrashing thickets of thorn and root, but also the desert predators and venomous serpents that nest among the towering cacti.",sp=0}},faq={{q="Where is Thistleshrub Valley located?",a="Thistleshrub Valley is nestled in the southwestern corner of Tanaris, wedged along the southern mountain ridge near the mysterious sealed gates of Uldum.",al={"thistleshrub valley location","where is thistleshrub","find thistleshrub valley"}},{q="Why is there so much plant life in this part of Tanaris?",a="Unlike the rest of the barren desert, the valley shelters a microclimate dominated by towering cacti and animated plant life. How these unusual thistleshrubs thrive so aggressively in the dry desert sand remains an enduring mystery of the southern dunes.",al={"why giant cactus here","why are plants growing here"}},{q="What creatures live in Thistleshrub Valley?",a="The valley is overrun by hostile, walking thistleshrub creatures, aggressive desert blooms, and various venomous reptiles that hide beneath the thorny vegetation.",al={"thistleshrub valley mobs","monsters in thistleshrub valley"}},{q="What is the massive stone structure near the valley?",a="Just beyond the valley sits a massive, sealed Titan structure often referred to as the gateway to Uldum, which remains locked and enigmatic to desert wanderers.",al={"doors near thistleshrub","titan gate tanaris"}}},ang={["profession:Herbalism"]="The valley is an anomaly for herbalists traversing Tanaris, hosting peculiar and resilient desert plant life among thick groves of thorny brush.",["class:Druid"]="Druids may find the viciously animated thistleshrubs fascinating, pondering what primeval or elemental forces keep them thriving in an otherwise desolate desert."},kw={"cacti","cactus","desert","tanaris","thistleshrub","thorns","uldum","valley"},rel={"zone:tanaris","subzone:uldum"},src={"Thistleshrub Valley"}}
E["subzone:uldum"] = {t="subzone",n="Uldum",z="tanaris",s="Uldum is a massive, sealed Titan research installation tucked behind colossal stone gates in the southernmost cliffs of Tanaris. Long hidden away behind ancient wards and forgotten machinery, it remains inaccessible to modern explorers.",h="Uldum is a massive, sealed Titan research installation tucked behind colossal stone gates in the southernmost...",sec={{t="The Gates of the Makers",b="Carved into the rugged southern mountain range bordering the Tanaris desert, the monumental gateway to Uldum stands silent and impassable. Built during the ordering of ancient Kalimdor, the compound served as an advanced Titan facility tied to their mysterious efforts to shape and oversee the planet's biosphere. Titanic wardens and defensive constructs once maintained the perimeter, leaving modern mortals only monumental stone carved arches and buried secrets that have defied all mundane attempts at entry.",sp=0},{t="The Sealed Secrets",b="The site's unmistakable Titan craftsmanship draws the curiosity of dwarven scholars, yet no mechanism or key has been found that might unlock the ancient complex. Legend claims that true insight into the secrets locked within requires the lost Plates of Uldum, leaving the dwarven scholars peering through the keyhole of an empire they cannot yet breach.",sp=0}},faq={{q="Can you open the gates to Uldum?",a="No. The massive stone gates leading into the mountain pass are completely sealed and shut fast against any mortal intrusion. No mechanism or key exists in the surrounding desert to unlock them.",al={"how to get into uldum","open uldum door","enter uldum"}},{q="What is inside Uldum?",a="According to ancient records and Titan lore, Uldum is a vast research facility constructed by the Titans to study and enhance the biosphere of Azeroth. However, exact details remain locked away behind Titan security measures.",al={"what is uldum","purpose of uldum","inside uldum"}},{q="What are the Plates of Uldum?",a="The Plates of Uldum are ancient data discs created by the Titans. According to lore preserved by ancient stone keepers, specific knowledge regarding the work and facilities inside Uldum can only be accessed through these sacred plates.",al={"plates of uldum","discs of uldum","uldum tablets"}}},ang={["race:Dwarf"]="For dwarves pursuing their Titan heritage through the Explorers' League, the colossal gates of Uldum represent one of the greatest uncracked mysteries on the continent of Kalimdor.",["faction:Alliance"]="Alliance scholars hope to beat any rival power to whatever Titan secrets lie concealed in the southern mountains."},kw={"explorers' league","gates of uldum","plates of uldum","tanaris","titans","uldum"},rel={"zone:tanaris","topic:titan","topic:explorers-league","zone:ungoro","zone:silithus","topic:alliance"},src={"Uldum"}}
E["subzone:valley-of-the-watchers"] = {t="subzone",n="Valley of the Watchers",z="tanaris",s="Tucked away in the far southern reaches of the Tanaris desert, the Valley of the Watchers is a sun-scorched canyon defined by monumental stonework. At its end stands a colossal, sealed stone gate leading into the mysterious complex of Uldum, guarded by lumbering giants and ancient stone sentinels.",h="Tucked away in the far southern reaches of the Tanaris desert, the Valley of the Watchers is a sun-scorched...",sec={{t="The Sealed Threshold",b="The Valley of the Watchers marks the southern boundary where the shifting sands of Tanaris meet the mountainous edge of the continent. Dominating the canyon is a massive gate crafted from ancient stone, locked tight against the outside world. This sealed portal is believed to guard the entrance to Uldum, a subterranean facility of the enigmatic Titans. Massive Dune Smasher mountain giants roam the dusty approach, ensuring that whatever secrets lie buried beneath the sands remain undisturbed by travelers, tomb robbers, and scholars alike.",sp=0}},faq={{q="What is behind the huge stone gate here?",a="The monumental doors are the entrance to Uldum, an ancient subterranean facility constructed by the Titans long before recorded mortal history. For now, the mechanisms remain entirely sealed, keeping its true contents and purpose a total mystery.",al={"gate of uldum","what is uldum","what is behind the door"}},{q="Can the gate to Uldum be opened?",a="No. The massive stone gates are completely impassable. No mortal key, spell, or force currently known in Kalimdor can bypass the Titan safeguards locking the complex shut.",al={"can you open the uldum gate","open uldum door","how to get into uldum"}},{q="Why are there giants wandering the valley?",a="Colossal mountain giants known as Dune Smashers prowl the canyon floor. Drawn to the area's potent earthen energy, they fiercely guard the approach, crushing any adventurers who stray too close to the southern cliffs.",al={"why are there dune smashers","valley giants","mountain giants tanaris"}},{q="Where in Tanaris is this valley located?",a="The valley lies at the far southern edge of Tanaris, south of the Thistleshrub Valley and the gaping chasms of the Southbreak Shores, carved directly into the towering southern mountain wall.",al={"valley of the watchers location","how to find valley of the watchers","where is the gate"}}},ang={["race:Dwarf"]="For dwarven explorers and members of the Explorer's League, the massive stone gateway represents another tantalizing puzzle piece in the search for their Titan creators."},kw={"dune smasher","kalimdor","tanaris","titan gate","titans","uldum","valley of the watchers"},rel={"zone:tanaris","subzone:uldum","topic:titan"},src={"Valley of the Watchers"}}
E["subzone:waterspring-field"] = {t="subzone",n="Waterspring Field",z="tanaris",s="Waterspring Field is a vital water-pumping operation in northern Tanaris, constructed by the goblins of Gadgetzan to tap underground aquifers. Instead of supplying the boomtown, the field has been overtaken by the ruthless Wastewander bandits, who now hoard the desert's most precious resource.",h="Waterspring Field is a vital water-pumping operation in northern Tanaris, constructed by the goblins of...",sec={{t="A Stolen Oasis",b="In the searing wastes of Tanaris, nothing carries more value than fresh water. Seeking to support their expanding trade hub, the Steamwheedle Cartel goblins of Gadgetzan erected an array of industrial pumping towers across Waterspring Field to draw from underground reserves. Their plans collapsed when the Wastewanders—a sprawling band of human outlaws and desert marauders—seized the entire field. The bandits now guard the hijacked pumps with their lives, forcing Gadgetzan to look for hired blades willing to reclaim the moisture.",sp=0}},faq={{q="Who built the water towers here?",a="The towers were built by the goblins of Gadgetzan. They intended to pump fresh water from deep subterranean reserves to sustain their desert settlement and industrial operations.",al={"who built this","goblin pumps","waterspring field towers"}},{q="Why are there bandits squatting at Waterspring Field?",a="The Wastewander nomads invaded the field and seized the machinery for themselves. Controlling the primary source of fresh water in northern Tanaris gives them total leverage over surrounding travelers and merchants.",al={"who are the bandits","wastewanders waterspring","why are wastewanders here"}},{q="Why doesn't Gadgetzan take the field back directly?",a="Gadgetzan hires adventurers to drive back the Wastewander bandits and recover their water pouches. The reason its Bruisers are not sent into the field is unknown.",al={"why gadgetzan no fight","goblin guards waterspring"}}},ang={["profession:Engineering"]="The goblin-built mechanical pumping towers represent impressive desert hydraulics.",["race:Human"]="The Wastewander bandits occupying the towers are predominantly human outlaws who have forsaken the kingdoms of the north to carve out a brutal existence in the desert sun."},kw={"gadgetzan","pumps","tanaris","wastewander","water pouches","water towers","waterspring field"},rel={"zone:tanaris","subzone:gadgetzan","topic:goblin"},src={"Waterspring Field"}}
E["subzone:wavestrider-beach"] = {t="subzone",n="Wavestrider Beach",z="tanaris",s="Wavestrider Beach is the sun-scorched coastal strip lining the eastern edge of Tanaris. Stretching between Steamwheedle Port and the pirate stronghold at Lost Rigger Cove, its sands are inhabited by aggressive crustacean wildlife and overlook distant naval skirmishes out at sea.",h="Wavestrider Beach is the sun-scorched coastal strip lining the eastern edge of Tanaris.",sec={{t="A Treacherous Coastline",b="Running along the ocean border of eastern Tanaris, Wavestrider Beach connects the goblin settlement of Steamwheedle Port in the north to the cliffs guarding Lost Rigger Cove to the south. Rather than a gentle resort, the shoreline is plagued by vicious Steeljaw Snappers and Desert Crawlers scuttling across the baking sand. Out in the deep water just offshore, burning vessels remain locked in a perpetual naval clash, serving as a grim warning of the piratical violence that dominates these coastal waters.",sp=0}},faq={{q="Where is Wavestrider Beach located?",a="Wavestrider Beach lies along the eastern coastline of Tanaris, stretching directly between the docks of Steamwheedle Port to the north and the mouth of Lost Rigger Cove to the south.",al={"wavestrider beach location","where is wavestrider beach","wavestrider beach tanaris"}},{q="What creatures wander the sands here?",a="The beach is primarily overrun by aggressive marine scavengers, including native Desert Crawlers and heavily armored Steeljaw Snappers prowling the surf.",al={"wavestrider beach mobs","crabs on wavestrider beach"}},{q="What are the burning ships visible offshore?",a="Looking out to sea from the beach, travelers can spot two blazing vessels engaged in ongoing combat. They reflect the rampant pirate activity that plagues the waters surrounding the Southsea Freebooters' hideouts.",al={"burning ships tanaris","ships on fire wavestrider beach"}},{q="Is Wavestrider Beach safe to travel through?",a="It is relatively hazardous. Between the aggressive snapjaws and crabs along the water's edge and its close proximity to Southsea pirate territory, unwary explorers can quickly find themselves overwhelmed.",al={"is wavestrider beach dangerous","wavestrider beach safety"}}},kw={"coast","desert crawler","lost rigger cove","southsea","steamwheedle port","steeljaw snapper","tanaris","wavestrider beach"},rel={"zone:tanaris","subzone:steamwheedle-port","subzone:lost-rigger-cove"},src={"Wavestrider Beach"}}
E["subzone:zalashji-s-den"] = {t="subzone",n="Zalashji's Den",z="tanaris",s="Zalashji's Den is a secluded cave tucked along the eastern coast of Tanaris. It serves as the solitary lair of Zalashji, an enigmatic naga who dwells far from the typical gathering grounds of his serpentine kin.",h="Zalashji's Den is a secluded cave tucked along the eastern coast of Tanaris.",sec={{t="A Solitary Lair",b="Carved into the rugged bluffs along the eastern shoreline of Tanaris, this coastal cavern provides shelter to a single inhabitant: Zalashji. Naga are known across Kalimdor to gather in disciplined war parties or coastal outposts, yet Zalashji resides here entirely alone. Little is known about why he made this isolated cave his domain, far removed from the primary settlements and desert ruins of the region, but any traveler venturing along the surf should approach the cave mouth with caution.",sp=0}},faq={{q="Where is Zalashji's Den located?",a="The cave is located on the eastern coastline of Tanaris, recessed into the rocky bluffs that border the ocean waters.",al={"zalashji location","where is zalashji den","zalashji cave"}},{q="Who is Zalashji?",a="Zalashji is an individual naga who makes this isolated coastal cavern his home, lingering along the desert shore away from larger naga forces.",al={"who is zalashji","zalashji lore","what is zalashji"}},{q="Are there any quests associated with this cave?",a="There are no known quests directing adventurers to Zalashji's Den. It remains a curious landmark for coastal explorers traveling the eastern perimeter of Tanaris.",al={"zalashjis den quests","is there a quest here","zalashji quest"}},{q="Why is a naga living alone in Tanaris?",a="His true motives remain unknown. While naga generally congregate near sunken ruins or organized encampments, Zalashji keeps to himself in this solitary seaside lair.",al={"why is zalashji alone","naga in tanaris","why is zalashji here"}}},ang={["race:NightElf"]="For the night elves, any presence of the cursed, mutated naga on Kalimdor's shores is a grim reminder of the ancient Highborne and the Sundering."},kw={"cave","coast","naga","tanaris","zalashji","zalashji's den"},rel={"zone:tanaris","topic:naga"},src={"Zalashji's Den"}}
E["subzone:zul-farrak"] = {t="subzone",n="Zul'Farrak",z="tanaris",s="Zul'Farrak is a sprawling, sun-baked sandstone city tucked into the northwestern cliffs of Tanaris. Long isolated from the rest of their kind, the Sandfury trolls defend this ancient stronghold with fanatic zeal, dark voodoo, and a hoard of undead risen from their sandy graves.",h="Zul'Farrak is a sprawling, sun-baked sandstone city tucked into the northwestern cliffs of Tanaris.",sec={{t="The Withered Remnant",b="Little of Zul'Farrak's distant past survives beyond troll legend, but the Sandfury trolls who hold it have long endured the searing, arid wastes of Tanaris. Known across the desert for their particular ruthlessness, their priests now practice a brutal brand of dark mysticism, exhuming their own dead to build a shambling army within their sun-bleached walls.",sp=0},{t="Legends of the Sand",b="Whispers throughout Gadgetzan tell of treasures and terrors hidden behind Zul'Farrak's guarded gates. Troll lore speaks of Sul'thraze the Lasher, a legendary broadsword broken into two separate blades that remain hidden somewhere in the city. More alarming are the tales of a band of mercenaries led by Sergeant Bly who wandered into the city and were captured, as well as rumors of Gahz'rilla, an ancient hydra demigod slumbering within a sacred pool at the city's heart.",sp=0}},faq={{q="What tribe of trolls lives here?",a="Zul'Farrak is held by the Sandfury tribe, sand trolls known throughout Tanaris for their particular ruthlessness and dark mysticism.",al={"who lives in zulfarrak","sand troll tribe","what trolls are these"}},{q="Why are there so many zombies and graves inside?",a="Pushed to the brink of desperation and isolation, the Sandfury witch doctors and shadow hunters have turned to dark necromancy. They have begun raising their fallen kin as undead thralls to bolster their ranks and wage war across Tanaris.",al={"why undead in zulfarrak","sandfury zombies","troll graves"}},{q="What is the ancient monster sleeping in the city?",a="The creature is Gahz'rilla, a colossal hydra demigod. Kept slumbering in a deep sacred pool within the city, it is revered by the Sandfury, though disturbing rumors suggest the beast can be called forth with the proper ritual instrument.",al={"hydra boss","ancient creature in pool","gahzrilla"}},{q="What is Sul'thraze the Lasher?",a="Sul'thraze the Lasher is a legendary blade from ancient troll folklore, renowned for sapping the strength and will of anyone struck by it. Long ago it was shattered into two distinct swords, Jang'thraze and Sang'thraze, both of which are rumored to be kept inside the city.",al={"sandfury sword","sulthraze","zul farrak sword legend"}}},ang={["race:Troll"]="The Sandfury view the Darkspear as weak traitors allied with foreign conquerors, while Darkspear elders like Master Gadrin watch their corrupted desert cousins with grim concern.",["faction:Alliance"]="Human and dwarven explorers are frequently drawn here to recover ancient relics or rescue missing mercenaries who vanished into the ruins from Gadgetzan."},kw={"gadgetzan","gahz'rilla","sand trolls","sandfury","sul'thraze","tanaris","zul'farrak"},rel={"zone:tanaris","subzone:gadgetzan","topic:troll","npc:master-gadrin","subzone:sen-jin-village","quest:1179","subzone:mirage-raceway","subzone:tabetha-s-farm"},src={"Zul'Farrak"}}
E["topic:arthas-menethil"] = {t="topic",n="Arthas Menethil",z="tanaris",s="Once the golden prince of Lordaeron and a celebrated paladin of the Silver Hand, Arthas Menethil fell from grace during the Third War while pursuing the demonic orchestrators of the plague. After claiming the cursed runeblade Frostmourne in the frozen north, he surrendered his soul, murdered his father King Terenas, and spearheaded the destruction of his own homeland as the Scourge's dark champion.",h="Once the golden prince of Lordaeron and a celebrated paladin of the Silver Hand, Arthas Menethil fell from...",sec={{t="The Golden Prince",b="Born to King Terenas Menethil II, Arthas was raised to embody the ideals of the Alliance of Lordaeron. Trained in combat by Muradin Bronzebeard and inducted into the Order of the Silver Hand under the tutelage of Uther the Lightbringer, he was revered by high and low alike as the future of humanity. Bold, skilled, and fiercely protective of his people, he fought tenaciously against Blackrock clan orc incursions and forest troll warbands. Yet beneath his radiant exterior lay an uncompromising pride and an obsessive dread of failure.",sp=0},{t="The Scourge and the Culling",b="When the mysterious Plague of Undeath gripped northern Lordaeron, Arthas raced across the countryside alongside the sorceress Jaina Proudmoore to stem its spread. Tracing the tainted grain from Brill to Andorhal, he slew the necromancer Kel'Thuzad, only to discover a vast conspiracy orchestrated by the dreadlord Mal'Ganis. Confronting the infected populace at Stratholme, Arthas chose pragmatic cruelty over moral restraint, commanding the wholesale slaughter of the city's inhabitants before they could turn. Repulsed by his madness, Uther and Jaina abandoned him as the city burned.",sp=1},{t="The Fall and Ascendance",b="Fixated on vengeance, Arthas tracked Mal'Ganis to the frozen wastes of Northrend. There he reunited with Muradin and uncovered the runeblade Frostmourne, ignoring its dreadful curse to defeat the demon. The blade severed Arthas's soul, leaving him a puppet of the Lich King. Returning to Capital City as a Death Knight, Arthas drove the runeblade through his father's heart and drowned Lordaeron in ash and undeath. He crushed the Silver Hand, besieged Dalaran, and carved a bloody path through Quel'Thalas before journeying back to the Frozen Throne to fuse directly with his dark master.",sp=2}},faq={{q="Who was Arthas Menethil before his fall?",a="Arthas was the Crown Prince of the Kingdom of Lordaeron and heir to King Terenas Menethil II. He was inducted into the Knights of the Silver Hand at nineteen and was widely considered one of the finest young paladins and swordsmen of the realm.",al={"arthas backstory","who was prince arthas","arthas prince of lordaeron"},it="identity"},{q="Why did Arthas purge Stratholme?",a="The city's citizens had already consumed grain contaminated by the Plague of Undeath, ensuring they would rise as mindless undead under Mal'Ganis's control. Believing mercy was impossible, Arthas ordered the immediate slaughter of the entire populace to prevent an army of Scourge from rising.",al={"why did arthas cull stratholme","culling of stratholme","stratholme purge"},it="motive"},{q="How did Arthas become corrupted?",a="Obsessed with destroying Mal'Ganis, Arthas journeyed to Northrend and claimed Frostmourne, a cursed runeblade forged by the Lich King. The blade drained his soul and bound his mind to Ner'zhul, transforming him into the vanguard death knight of the Scourge.",al={"how did arthas turn evil","arthas corruption","why did arthas become death knight"},it="history"},{q="What happened to King Terenas?",a="After succumbing to Frostmourne, Arthas returned to Capital City under the guise of a returning conqueror. In the throne room, amid ringing bells and falling rose petals, he drew his runeblade and impaled his own father.",al={"arthas kills father","death of king terenas","what happened to terenas"}},{q="What was Arthas's relationship with Jaina Proudmoore?",a="Jaina Proudmoore and Arthas shared a romance in their youth, and she rode at his side as he fought to contain the plague. His descent into cruelty at Stratholme drove her away.",al={"arthas and jaina","did jaina love arthas","arthas romance"},it="ties"},{q="Where is Arthas right now?",a="Following the defense of the Frozen Throne against the demon hunter Illidan, Arthas ascended Icecrown, shattered the icy prison of the Lich King, and merged his essence with Ner'zhul, ruling the Scourge from Northrend.",al={"where is arthas","current status of arthas","is arthas alive"},it="today"},{q="Who leads Arthas Menethil?",a="Arthas serves the Lich King, the supreme master of the undead Scourge. Originally drawn to Northrend by vengeance, Arthas took up the cursed runeblade Frostmourne and sacrificed his own soul to its dark whispers. He surrendered his will entirely to become Ner'zhul's greatest death knight and champion, commanding armies in his master's name before traveling back to the Frozen Throne to merge directly with the Lich King himself.",al={"who does arthas serve","arthas leader","who controls arthas"},it="leader",add="b80d5fb0"},{q="Who is Arthas Menethil allied with?",a="Arthas commands the Scourge, a monstrous legion of mindless undead, necromancers, and horrors created by the Plague of Undeath. Among his chief lieutenants is the revived archlich Kel'Thuzad, whom Arthas once slew in life but later resurrected to oversee the ruins of Lordaeron. Arthas works solely on behalf of the Scourge and the Lich King, standing in bitter hostility against all living mortal nations across Azeroth.",al={"arthas allies","who does arthas work with","arthas faction"},it="allies",add="8c3ad81e"}},ang={["class:Paladin"]="Arthas is the greatest tragedy and shame of the Silver Hand; his fall corrupted the very tenets of justice and protection that Uther strove to instill.",["race:Human"]="The destruction of Lordaeron broke the human race in two, scattering refugees across the globe and leaving Stormwind as humanity's final great seat of power.",["race:Undead"]="The Forsaken view Arthas with unmatched hatred, having broken free from the dark prince's mental thrall under Queen Sylvanas to seek vengeance for their damnation.",["faction:Alliance"]="Arthas's treason cost the Alliance of Lordaeron its greatest kingdom, its capital city, and the legendary paladin order that once anchored human faith."},kw={"arthas","frostmourne","lich king","lordaeron","menethil","scourge","stratholme","terenas"},rel={"topic:scourge","topic:lich-king","subzone:stratholme","topic:terenas-menethil-ii","npc:jaina-proudmoore","topic:muradin-bronzebeard","topic:plague-of-undeath","topic:lordaeron"},src={"Arthas Menethil"}}
E["zone:tanaris"] = {t="zone",n="Tanaris",z="tanaris",s="Tanaris is a vast, sweltering desert spanning the southern reaches of Kalimdor, defined by rolling sand dunes and blistering heat. At its heart lies Gadgetzan, a neutral trading outpost operated by the goblins of the Steamwheedle Cartel. Beyond the bustling settlements, the dunes conceal hostile sand trolls, dangerous silithid hives, and the hidden domain of the bronze dragonflight.",h="Tanaris is a vast, sweltering desert spanning the southern reaches of Kalimdor, defined by rolling sand dunes...",sec={{t="A Sea of Dunes",b="Tanaris is a barren, sun-scorched wilderness. Within the walled city of Zul'Farrak, the hardened Sandfury trolls guard their isolated domain. Today, the desert floor is ruled by hyenas, basilisks, and scorpids, while subterranean tunnels snake beneath the baking earth.",sp=0},{t="Goblin Enterprise",b="Because Tanaris is as close to their island homeland of Kezan as the mainland allows, the Steamwheedle Cartel has established a thriving enterprise here. From the walled oasis of Gadgetzan to the coastal docks of Steamwheedle Port, the goblins maintain strict neutrality, welcoming coin from both the Alliance and the Horde. Their peace is maintained by heavy bruiser muscle, though rogue threats like the Southsea Freebooters constantly harass shipping and dig sites along the coastline.",sp=0},{t="Ancient Mysteries and Rising Perils",b="The sands hide powers far older than mortal empires. In the eastern reaches lie the Caverns of Time, the ancestral domain of Nozdormu and his bronze dragonflight, whose drakes can occasionally be seen riding the desert thermals. To the south, massive stone gates mark the titan complex of Uldum. Yet a darker danger stirs from subterranean nests like the Gaping Chasm and the Noxious Lair, where creeping silithid swarms have begun burrowing outward across the sands.",sp=0}},faq={{q="How do I travel to Tanaris?",a="Travelers on foot journey through Thousand Needles into the Shimmering Flats. A mountain pass carved through the cliffs at the southern end of the salt flats leads directly down into the desert, bringing you immediately within sight of Gadgetzan's walls. A ship also sails from Powderfuse Port in the Riverglades to Steamwheedle Port on the eastern coast.",al={"how to get to tanaris","getting to tanaris","tanaris entrance"}},{q="Why is Gadgetzan neutral to both factions?",a="Gadgetzan is governed by the Steamwheedle Cartel, whose sole allegiance is to profit. To maximize commerce and protect trade routes across the desert, the goblins enforce strict neutrality, employing bruisers to beat down anyone foolish enough to start faction brawls within their city walls.",al={"why is gadgetzan neutral","can horde and alliance go to gadgetzan","goblin neutrality gadgetzan"}},{q="What is Zul'Farrak?",a="Zul'Farrak is the fortified desert capital of the Sandfury trolls. Long isolated in the desert, the Sandfury tribe turned hostile to all outsiders, guarding their sacred pools and mysterious shrines from encroaching adventurers.",al={"what is zulfarrak","who lives in zulfarrak","sand troll city"}},{q="What are the insect creatures nesting across the desert?",a="The insectoid beasts are silithid, monstrous colonial burrowers that construct vast hives such as the Gaping Chasm and the Noxious Lair. Their emerging presence in Tanaris has unsettled observers like Senior Surveyor Fizzledowser, recalling the ancient horrors of the War of the Shifting Sands.",al={"what are the bugs in tanaris","tanaris insect hives","silithid in tanaris"}},{q="What is behind the massive stone doors in the south?",a="The monumental gates in the Valley of the Watchers mark the entrance to Uldum, a legendary research facility and holding of the ancient titans. The entrance remains firmly sealed, guarded by colossal stone sentinels and surveyed from afar by curious scholars and goblins.",al={"giant doors in south tanaris","ruins of uldum gates","titan gate tanaris"}},{q="Who dwells inside the Caverns of Time?",a="The Caverns of Time serve as the ancestral lair of the bronze dragonflight and their aspect, Nozdormu. From these hidden, winding depths, the timeless dragons watch over the flow of history, occasionally patrolling the skies high above the southern dunes.",al={"caverns of time lore","what is in caverns of time","dragons in tanaris"}}},ang={["profession:Mining"]="The arid cliffs and rocky outcrops surrounding the dunes offer rich veins of Mithril, Truesilver, Iron, and Gold, along with scattered deposits of Small Thorium in the deeper reaches.",["profession:Herbalism"]="The dry heat nurtures the elusive Firebloom across the shifting dunes, while shaded ruins and damp oases provide shelter for valuable Purple Lotus.",["race:Troll"]="Seeing the Sandfury of Zul'Farrak offers trolls a stark look at their ancient cousins, who hardened into a brutal culture in the isolation of the desert.",["faction:Alliance"]="With no major Alliance strongholds between Dustwallow Marsh and Feralas, the Alliance flight master in neutral Gadgetzan serves as a vital staging post for travels across southern Kalimdor.",["faction:Horde"]="Gadgetzan offers Horde scouts a convenient trade hub linking routes from Freewind Post and Camp Mojache directly to the silithid-infested wastes of the far south."},kw={"caverns of time","desert","freebooters","gadgetzan","nozdormu","sandfury","silithid","steamwheedle","tanaris","uldum","zul'farrak"},rel={"subzone:gadgetzan","subzone:zul-farrak","subzone:caverns-of-time","subzone:steamwheedle-port","subzone:ruins-of-uldum","subzone:shimmering-flats","subzone:gaping-chasm","quest:887"},src={"Tanaris (Classic)","Tanaris"}}
